"use strict";
app.controller("LoginController", [
    "$rootScope",
    "$scope",
    "authService",
    "ngProgress",
    "toaster",
    "UsersSvc",
    "globalService",
    "blockUI",
    "appConst",
    "$sce",
    "$timeout",
    "LookupSvc",
    "signalRSvc",
    function ($rootScope, $scope, authService, ngProgress, toaster, UsersSvc, globalService, blockUI, appConst, $sce, $timeout, LookupSvc, signalRSvc) {
        $rootScope.title = "تسجيل الدخول";
        $scope.submitLogin = false;
        $scope.myTab = { val: "1", name: "بوابـة المشترك" };
        $scope.showActivationForm = false;
        $rootScope.showLogin = true;
        $rootScope.showTFA = false; //two factor authentication form
        $rootScope.showSpin = false;
        $scope.showVideoPopup = false;
        $scope.showSpine = false;
        $scope.inputType = "password";
        $scope.showHideClass = "eye.svg";
        $scope.downloadModel = {};
        $rootScope.Message = "";
        $rootScope.confirmLoginErrors = "";
        $scope.VedioUrl = null;
        $rootScope.random = '';
        $rootScope.nafathError = '';
        $rootScope.timer = 0;
        $scope.identityPattern = appConst.identityPattern;
        $scope.loginNafathForm = {
            identityNumber: null
        };
        $scope.loginWays = {
            allowNafath: false
        };
        //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
        $scope.Sms = { TrackId: null, Code: null, CodeSent: false, UseTcc: false };
        $rootScope.chamberSettings.twitter =
            $rootScope.chamberSettings.twitter === null || $rootScope.chamberSettings.twitter === "" || $rootScope.chamberSettings.twitter === undefined
                ? "https://twitter.com/CSC_SA"
                : $rootScope.chamberSettings.twitter;

        if ($scope.loginForm) $scope.loginForm.$setPristine();
        document.forms["loginForm"].reset();
        $scope.ChamberList = [];
        $scope.captcha = {
            captchaKey: appConst.captchaKey,
            response: null,
            widgetId: null
        };

        $scope.swapTabs = function (way) {
            ngProgress.stop();
            $scope.loginWays.allowNafath = way == 1 ? false : true;
            if (way == 1) {
                $rootScope.showLogin = true;
            }

            $rootScope.showRetrySendCode = false;
            $rootScope.showTFA = false;
            $scope.showSpin = false;
            $scope.timeElapsed = 0;
        }

        $scope.loginNafath = function (form) {

            $rootScope.SubmitLogin = true;
            $rootScope.Message = "";
            $rootScope.confirmLoginErrors = "";
            $rootScope.nafathError = "";
            // if (!form.$valid) {
            //     return false;
            // }

            $rootScope.showSpin = true;
            loginNafathForm.identityNumber = form.identity;
            ngProgress.start();
            $rootScope.ErrorLogin = false;
            authService.loginNafath(form.identity, $scope.captcha.response).then(function (response) {
                if (response.succeeded) {
                    $rootScope.timer = 190; //3 minutes
                    var intervalNum = setInterval(() => {
                        --$rootScope.timer;
                        if ($rootScope.timer == 0) {
                            clearInterval(intervalNum);
                            $rootScope.random = '';
                        }
                    }, 1000);
                    $rootScope.random = response.data.random;
                } else {
                    vcRecaptchaService.reload($scope.captcha.widgetId);
                    $scope.captcha.response = null;
                    //show errors
                    $rootScope.nafathError = '';
                    if (response.messages && response.messages.length > 0) {
                        for (var i = 0; i < response.messages.length; i++) {
                            $rootScope.nafathError += response.messages[i] + " ";
                        }
                    }
                    else
                        $rootScope.nafathError = 'خطأ غير معروف';
                }
                ngProgress.complete();
                $rootScope.showSpin = false;
            });
        };
        $scope.setResponse = function (response) {
            $scope.captcha.response = response;
        };

        $scope.setWidgetId = function (widgetId) {
            $scope.captcha.widgetId = widgetId;
        };

        $scope.cbExpiration = function () {
            if ($scope.loginWays.allowNafath) {
                if ($rootScope.timer == 0) {
                    vcRecaptchaService.reload($scope.captcha.widgetId);
                    $scope.captcha.response = null;
                }
            } else {
                vcRecaptchaService.reload($scope.captcha.widgetId);
                $scope.captcha.response = null;
            }
           
        };
        //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
        $scope.login = function (form) {
            $rootScope.SubmitLogin = true;
            $rootScope.Message = "";
            $rootScope.confirmLoginErrors = "";
            $rootScope.nafathError = "";
            if (!form.$valid) {
                return false;
            }

            $rootScope.showSpin = true;

            ngProgress.start();
            angular.element("#confirm-form").addClass("w3-animate-bottomm");
            $rootScope.ErrorLogin = false;
            authService.login($scope.user, false);
        };

        $scope.confirmLogin = function (info) {
            $rootScope.showSpin = true;
            $rootScope.Message = "";
            authService.confirmLogin(info);
        };

        $scope.resendLoginCode = function () {
            if ($rootScope.codeMaxLength !== null && $rootScope.codeMaxLength !== undefined && $rootScope.codeMaxLength !== "") {
                if ($rootScope.codeMaxLength === 4) {
                    $scope.smsInputs = [
                        { id: 3, value: null },
                        { id: 2, value: null },
                        { id: 1, value: null },
                        { id: 0, value: null },
                    ];
                } else {
                    $scope.smsInputs = [
                        { id: 5, value: null },
                        { id: 4, value: null },
                        { id: 3, value: null },
                        { id: 2, value: null },
                        { id: 1, value: null },
                        { id: 0, value: null },
                    ];
                }
            }
            authService.resendLoginCode();
        };

        $scope.resendLoginCodeForAbshir = function () {
            authService.resendLoginCodeForAbshir();
        };

        //$scope.$watch('user.mobileLoginCode.length', function (newValue) {
        //    if (newValue === 4 && ($rootScope.activateByAbshir !== true && $rootScope.sendByRayah !== true )  ) {
        //        $scope.confirmLogin($scope.user);
        //    }
        //    else if (($rootScope.activateByAbshir === true || $rootScope.sendByRayah === true ) && newValue === 6) {
        //        $scope.confirmLogin($scope.user);
        //    }
        //});

        $scope.$watch("codeMaxLength", function (newValue) {
            if (newValue !== null && newValue !== undefined && newValue !== "") {
                if (newValue === 4) {
                    $scope.smsInputs = [
                        { id: 3, value: null },
                        { id: 2, value: null },
                        { id: 1, value: null },
                        { id: 0, value: null },
                    ];
                } else {
                    $scope.smsInputs = [
                        { id: 5, value: null },
                        { id: 4, value: null },
                        { id: 3, value: null },
                        { id: 2, value: null },
                        { id: 1, value: null },
                        { id: 0, value: null },
                    ];
                }
            }
        });
        //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

        $scope.ShowVideo = function () {
            $scope.VedioUrl = $rootScope.chamberSettings.definitionVedioUrl;
            $scope.showVideoPopup = !$scope.showVideoPopup;
        };

        $scope.showActivationForme = function () {
            $scope.downloadModel = {};
            $scope.showActivationForm = !$scope.showActivationForm;
        };

        //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

        $scope.DownloadActivationForm = function (Obj, form, event) {
            $scope.isFormSubmitted = true;
            event.preventDefault();

            if (!form.$valid) {
                return false;
            }
            $scope.showSpine = true;
            blockUI.start();
            UsersSvc.DownloadActivationForm(Obj).then(function (response) {
                if (response.success) {
                    if (response.data) {
                        globalService.fileDownload(response.data.fileData, Obj.MemberId);
                        //ngNotify.set(appConst.activationFileDownloadedSuccess, {
                        //    position: 'top',
                        //    type: 'success'
                        //});
                        $(".modal-backdrop").css("display", "none");
                        $scope.showActivationForm = false;
                        $scope.showSpine = false;
                    } else {
                        //ngNotify.set(response.message, {
                        //    position: 'top',
                        //    type: 'error'
                        //});
                        $scope.showSpine = false;
                    }
                } else {
                    //ngNotify.set(response.message, {
                    //    position: 'top',
                    //    type: 'error'
                    //});
                    $scope.showSpine = false;
                }
                blockUI.stop();
            });
        };

        //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

        $scope.myTabs = [{ val: "1", name: "بوابـة المشترك" }];
        $scope.SetMyTab = function (tab) {
            if (tab === 1) {
                $scope.myTab = { val: "1", name: "بوابـة المشترك" };
            }
            if (tab === 2) {
                $scope.myTab = { val: "4", name: "خدمات أخري" };
            }
        };

        $scope.goVerify = function () {
            window.location.href = "/#/Verify";
        };

        $scope.trustSrc = function (src) {
            return $sce.trustAsResourceUrl(src);
        };

        //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
        $scope.showPassword = function () {
            if ($scope.user !== null && Object.keys($scope.user).length !== 0 && $scope.user !== undefined) {
                if ($scope.user.password !== null) {
                    if ($scope.inputType === "password") {
                        $scope.inputType = "text";
                        $scope.showHideClass = "closed-eye.svg";
                    } else {
                        $scope.inputType = "password";
                        $scope.showHideClass = "eye.svg";
                    }
                }
            }
        };

        $scope.closeVideo = function () {
            $scope.VedioUrl = null;
            var iframe = document.getElementsByTagName("iframe")[0].contentWindow;
            iframe.postMessage('{"event":"command","func":"' + "pauseVideo" + '","args":""}', "*");
        };
        ////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
        //Combine SMS Code from front to one string value to be validated
        $scope.combineCode = function (digit, index) {
            if (digit !== null) {
                $scope.Sms.Code = $scope.Sms.Code === null ? ($rootScope.codeMaxLength === true ? "xxxxxx" : "xxxx") : $scope.Sms.Code;
                var a = $scope.Sms.Code.split("");
                a[$scope.smsInputs.length - index - 1] = digit.value;
                $scope.Sms.Code = a.join("");
                if ($scope.Sms.Code !== undefined && $scope.Sms.Code !== null && $scope.Sms.Code !== "") {
                    if ($scope.Sms.Code.toString().indexOf("x") === -1) {
                        if ($scope.Sms.Code.length === 4 && $rootScope.activateByAbshir !== true && $rootScope.sendByRayah !== true) {
                            $scope.user.mobileLoginCode = $scope.Sms.Code;
                            $timeout(function () {
                                $scope.confirmLogin($scope.user);
                            }, 300);
                        } else if (
                            ($rootScope.activateByAbshir === true || $rootScope.sendByRayah === true) &&
                            ($scope.Sms.Code.length === 6 || ($rootScope.useTcc === true && $scope.Sms.Code.length === 4))
                        ) {
                            $scope.user.mobileLoginCode = $scope.Sms.Code;
                            $timeout(function () {
                                $scope.confirmLogin($scope.user);
                            }, 300);
                        }
                    }
                }
            }
        };
        //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
        function GetDrops() {
            LookupSvc.GetChambersDrops().then(function (response) {
                $scope.ChamberList = $.grep(response.data, function (item) {
                    return item.allowUnifiedMode;
                });
            });
        }
        GetDrops();
        $scope.openDynRequest = function (dynRequest) {
            let isForNonMembers = dynRequest?.RT[0]?.IsForNonMember;
            $scope.showDynRequestAlertMsg = !isForNonMembers
                ? ` لتقديم الطلب يرجى تسجيل الدخول  ثم اختيار احد العضويات ثم الدخول على صفحة الطلبات حيث يوجد الطلب (${dynRequest.NameAr})`
                : ` لتقديم الطلب يرجى تسجيل الدخول ثم اختيار خدمات غير المشتركين  حيث يوجد الطلب (${dynRequest.NameAr})`;
            $scope.showDynRequestAlertModal = true;
        };

        // SignalR connection
        signalRSvc.init("nafathHub", [
            {
                eventName: "NafathResponse",
                callbackFn: function (jsonData) { 
                    // Add the message to the page.
                    if (jsonData.succeeded) {
                        //call log in function
                        authService.login({ username: loginNafathForm.identityNumber, password: '' }, true, jsonData.data.transactionId);
                    } else {
                        //show error messages
                        //$rootScope.timer = 0;
                        //$rootScope.random = '';
                        $rootScope.nafathError = '';
                        if (jsonData.messages && jsonData.messages.length > 0) {
                            for (var i = 0; i < jsonData.messages.length; i++) {
                                $rootScope.nafathError += jsonData.messages[i] + " ";
                            }
                        }
                        else
                            $rootScope.nafathError = 'خطأ غير معروف';
                    }
                    /**{"messages":[],"succeeded":true,"data":{"status":"","transactionId":""},"code":0} */
                },
            },
        ]);

        signalRSvc
            .startConnection()
            .then(function () {
                console.log("SignalR connected.", connectionId);
            })
            .catch(function (error) {
                console.log("SignalR could not connect: " + error);
            });
    },
]);
