"use strict";
app.directive('aDisabled', function () {
    return {
        compile: function (tElement, tAttrs, transclude) {
            //Disable ngClick
            tAttrs["ngClick"] = "!(" + tAttrs["aDisabled"] + ") && (" + tAttrs["ngClick"] + ")";

            //Toggle "disabled" to class when aDisabled becomes true
            return function (scope, iElement, iAttrs) {
                scope.$watch(iAttrs["aDisabled"], function (newValue) {
                    if (newValue !== undefined) {
                        iElement.toggleClass("disabled", newValue);
                    }
                });

                //Disable href on click
                iElement.on("click", function (e) {
                    if (scope.$eval(iAttrs["aDisabled"])) {
                        e.preventDefault();
                    }
                });
            };
        }
    };
}).controller('RegisterController', ['signalRSvc', 'toaster', 'blockUI', '$scope', '$timeout', '$rootScope', '$interval', 'appConst', 'registerService', 'vcRecaptchaService', 'authService', 'chamberList', 'globalService',
    function (signalRSvc, toaster, blockUI, $scope, $timeout, $rootScope, $interval, appConst, registerService, vcRecaptchaService, authService, chamberList, globalService) {
        // uncomment comming to make nafath work
        // setTimeout(() => {
        //     $rootScope.chamberSettings.allowNafath = true
        // }, 4000);
        $scope.ChamberList = chamberList;
        $scope.page = {
            showWaiting: false,
            isLoading: false,
            registerSuccess: false,
            showSmsTime: false,
            successRedirectLogin: false,
            AgreementAccepted: false,
            authOwnerPhone: false
        };
        $scope.registerForm = {};
        $scope.isFormSubmitted = false;
        $scope.registerData = {
            IdentityNo: null,
            ActivationWay: 3  //1 offline , 2 mobile,3 abshir
        };

        $scope.Sms = { TrackId: null, Code: null, CodeSent: false, UseTcc: false };
        $scope.Nafath = { Random: null, Status: '', TransactionId: '', Sent: false };

        //  $scope.captchaKey = appConst.captchaKey;
        $scope.captcha = {
            captchaKey: appConst.captchaKey,
            response: null,
            widgetId: null
        };

        $scope.identityPattern = appConst.identityPattern;
        $scope.passwordPattern = appConst.passwordPattern;
        $scope.PhoneNumbersList = [];
        $scope.identityFounded = false;

        $scope.showOtpModal2 = false;
        $scope.otp = {
            showTimer: false,
            timer: 0,
            isSent: false,
            code: '',
            useTcc: false,
            isResend: true
        };
        $scope.captcha2 = {
            captchaKey: appConst.captchaKey,
            response: null,
            widgetId: null,
        };
        $scope.loginWays = {
            allowNafath: false
        };
        /////////////////////////////////////////////////////////////////**** First Step ****////////////////////////////////////////////////////////////////////////

        //function to validate identity.no and  send OTP and Resend OTP
        $scope.SendValidateIdentity = function (form, event, isResend) {
            $scope.isFormSubmitted = true;
            event.preventDefault();

            if (!form.$valid) {
                return false;
            }

            $scope.page.isLoading = true;
            blockUI.start();
            $scope.Sms.Code = null;
            $scope.smsInputs = [{ id: 5, value: null }, { id: 4, value: null }, { id: 3, value: null }, { id: 2, value: null }, { id: 1, value: null }, { id: 0, value: null }];
            $timeout(function () {
                if ($rootScope.chamberSettings.useAbshir) {
                    registerService.SendValidateIdentity({
                        IdentityNo: $scope.registerData.IdentityNo, ReCaptchaResponse: $scope.captcha.response,
                        IsResend: isResend,
                        ChamberId: $scope.registerData.ChamberId
                    }, $scope.chamberDomain).then(function (response) {
                        $scope.page.isLoading = false;
                        blockUI.stop();
                        if (response.data.success) {
                            $scope.Sms.TrackId = response.data.data.trackId;
                            $scope.Sms.CodeSent = true;
                            $scope.Sms.UseTcc = response.data.data.useTcc;
                            if (response.data.data.useTcc === true)
                                $scope.smsInputs = [{ id: 3, value: null }, { id: 2, value: null }, { id: 1, value: null }, { id: 0, value: null }];
                            toaster.success({ title: 'تم إرسال كود التحقق بنجاح.' });
                            smsTimer();
                            $scope.ownerInfo = response?.data?.data?.ownerInfo;
                            if ($scope.ownerInfo) {
                                // $scope.registerData.UserFullNameEn = $scope.ownerInfo.mO_NameEN
                                $scope.registerData.UserFullName = $scope.ownerInfo.mO_Name
                                $scope.registerData.PhoneNumber = $scope.ownerInfo.mO_Mobile
                                $scope.registerData.Email = $scope.ownerInfo.mO_Email
                            }
                        } else {
                            $scope.cbExpiration();
                            toaster.error({ title: response.data.message });
                        }
                    });
                } else {
                    $scope.validateWithoutAbshirDone = false;
                    $scope.identityFounded = false;
                    registerService.ValidateIdentityRegisterByChamber({ IdentityNo: $scope.registerData.IdentityNo, ReCaptchaResponse: $scope.captcha.response, IsResend: isResend }, $scope.chamberDomain).then(function (response) {
                        $scope.page.isLoading = false;
                        blockUI.stop();
                        if (response.data.success) {
                            $scope.identityFounded = true;
                            $scope.PhoneNumbersList = response.data.data;
                            $scope.validateWithoutAbshirDone = true;
                        } else {
                            $scope.cbExpiration();
                            if (response.data.code === 4) {
                                $scope.identityFounded = false;
                                $scope.validateWithoutAbshirDone = true;
                                return false;
                            }

                            toaster.error({ title: response.data.message });
                        }
                    });
                }
            }, 800);

        }
        $scope.SendValidateIdentityViaNafath = function (form, event, isResend) {
             $scope.isFormSubmitted = true;
            event.preventDefault();

            if (!form.$valid) {
                return false;
            }

            $scope.page.isLoading = true;
            blockUI.start();
            $scope.Nafath.randomNo = null;
            $scope.Nafath.Sent = false
            $timeout(function () {
                if ($rootScope.chamberSettings.allowNafath) {
                    registerService.SendValidateIdentityViaNafath({
                        IdentityNumber: $scope.registerData.IdentityNo,
                        ReCaptchaResponse: $scope.captcha.response,
                        // IsResend: isResend,
                        // ChamberId: $scope.registerData.ChamberId
                    }, $scope.chamberDomain).then(function (response) {
                        $scope.page.isLoading = false;
                        blockUI.stop();
                        // uncomment comming to make nafath work
                        // response.data.succeeded = true
                        // response.data.data = {
                        //     Random:52,
                        //     TransactionId:12512512512512552,
                        //     Status:'WAITING'
                        // }
                        if (response.data.succeeded) {
                            $scope.loginWays.allowNafath = true;
                            $scope.Nafath.Random = response.data?.data?.Random
                            $scope.Nafath.Sent = true
                            $scope.Nafath.TransactionId = response.data?.data?.TransactionId
                            $scope.Nafath.Status = response.data?.data?.Status
                            // toaster.success({ title: 'تم إرسال كود التحقق بنجاح.' });
                            $scope.captcha = {
                                captchaKey: appConst.captchaKey,
                                response: null,
                                widgetId: null
                            };
                            smsTimer(60);
                            //$scope.ownerInfo = response?.data?.data?.ownerInfo;
                            //if ($scope.ownerInfo) {
                            //    // $scope.registerData.UserFullNameEn = $scope.ownerInfo.mO_NameEN
                            //    $scope.registerData.UserFullName = $scope.ownerInfo.mO_Name
                            //    $scope.registerData.PhoneNumber = $scope.ownerInfo.mO_Mobile
                            //    $scope.registerData.Email = $scope.ownerInfo.mO_Email
                            //}
                        } else {
                            $scope.cbExpiration();
                            response.data.messages?.forEach(message => {
                                toaster.error({ title: message });
                            });
                        }
                    }).catch(function (response) {
                        toaster.error({ title: response.data.message });
                        if (response.data.execptionMessage) {
                            toaster.error({ title: response.execptionMessage });
                        }
                        $scope.Sms.CodeSent = false;
                    }).finally(() => {
                        $timeout(function () { blockUI.stop(); }, 100);
                    });
                }
            }, 800);

        }

        $scope.onChamberDomainChange = function () {
            $scope.chamberDomain = $scope.ChamberList.filter(item => item.chamberId == $scope.registerData.ChamberId)[0].chamberDomain
        }

        $scope.hashNumber = function (number) {
            return "xxxxxx" + number.substring(6, 10);
        }

        $scope.swapTabs = function (way) {
            $scope.loginWays.allowNafath = way == 1 ? false : true;
        }

        $scope.ValidateIdentityOTP = function () {
            //ngProgress.start();
            blockUI.start();
            $scope.page.isLoading = true;
            registerService.ValidateIdentityOTP({ Code: $scope.Sms.Code, TrackId: $scope.Sms.TrackId, UseTcc: $scope.Sms.UseTcc }, $scope.chamberDomain).then(function (response) {
                //ngProgress.complete();
                blockUI.stop();
                if (response.data.success) {
                    // $scope.page.showOtpModal = false;

                    $timeout(function () {
                        $scope.page.isLoading = false;
                        $scope.Sms.Code = null;
                        $scope.Sms.CodeSent = false;
                        updateSteps(false, true);
                    }, 1000);
                } else {
                    // $scope.Sms.Code = null;
                    $scope.page.isLoading = false;
                    toaster.error({ title: response.data.message });
                }
            });
        }

        $scope.ValidateSMSCode = function () {
            blockUI.start();
            $scope.page.isLoading = true;
            registerService.ValidateSMSCode({ Code: $scope.Sms.Code, TrackId: $scope.Sms.TrackId, UserName: $scope.registerData.IdentityNo }, $scope.chamberDomain).then(function (response) {
                blockUI.stop();
                if (response.data.success) {
                    $timeout(function () {
                        $scope.page.isLoading = false;
                        $scope.Sms.Code = null;
                        $scope.Sms.CodeSent = false;
                        updateSteps(false, true);
                    }, 1000);
                } else {
                    $scope.page.isLoading = false;
                    toaster.error({ title: response.data.message });
                }
            });
        }

        ////////////////////////////////////////////// Register /////////////////////////////////////////////////////////

        $scope.SendCode = function (form, event, isResend) {
            $scope.isFormSubmitted = true;
            event.preventDefault();

            if (!form.$valid) {
                return false;
            }
            $scope.page.isLoading = true;
            blockUI.start();
            $scope.Sms.Code = null;
            $scope.smsInputs = [{ id: 3, value: null }, { id: 2, value: null }, { id: 1, value: null }, { id: 0, value: null }];

            $timeout(function () {
                registerService.SendRegisterCode({ PhoneNumber: $scope.registerData.PhoneNumber, IdentityNo: $scope.registerData.IdentityNo }, $scope.chamberDomain).then(function successCallback(response) {
                    $scope.page.isLoading = false;
                    blockUI.stop();
                    if (response.data.success) {
                        $scope.Sms.TrackId = response.data.data.trackId;
                        $scope.Sms.CodeSent = true;
                        smsTimer();
                    } else {
                        toaster.error({ title: response.data.message });
                    }
                }, function errorCallback(response) {
                    toaster.error({ title: response.data.message });
                    if (response.data.execptionMessage) {
                        toaster.error({ title: response.execptionMessage });
                    }
                    $scope.Sms.CodeSent = false;
                    $timeout(function () { blockUI.stop(); }, 100);
                });
            }, 800);

        };


        $scope.SendCodeMobile = function (form, event, isResend) {
            $scope.isFormSubmitted = true;
            event.preventDefault();

            if (!form.$valid) {
                return false;
            }
            $scope.page.isLoading = true;
            blockUI.start();
            $scope.Sms.Code = null;
            $scope.smsInputs = [{ id: 3, value: null }, { id: 2, value: null }, { id: 1, value: null }, { id: 0, value: null }];

            $timeout(function () {
                registerService.SendRegisterCode({ PhoneNumber: $scope.registerData.Mobile }, $scope.chamberDomain).then(function successCallback(response) {
                    $scope.page.isLoading = false;
                    blockUI.stop();
                    if (response.data.success) {
                        $scope.Sms.TrackId = response.data.data.trackId;
                        $scope.Sms.CodeSent = true;
                        smsTimer();
                    } else {
                        toaster.error({ title: response.data.message });
                    }
                }, function errorCallback(response) {
                    toaster.error({ title: response.data.message });
                    if (response.data.execptionMessage) {
                        toaster.error({ title: response.execptionMessage });
                    }
                    $scope.Sms.CodeSent = false;
                    $timeout(function () { blockUI.stop(); }, 100);
                });
            }, 800);
        };

        $scope.Register = function () {
            var model = {
                UserName: $scope.registerData.IdentityNo,
                UserFullName: $scope.registerData.UserFullName,
                UserFullNameEn: $scope.registerData.UserFullNameEn,
                Password: $scope.registerData.Password,
                ConfirmPassword: $scope.registerData.ConfirmPassword,
                PhoneNumber: $scope.registerData.PhoneNumber,
                Email: $scope.registerData.Email,
                AgreementAccepted: $scope.page.AgreementAccepted,
                ChamberId: $scope.registerData.ChamberId,
                ActivationWay: 3, //by Abshir
                SMS: {
                    Code: $scope.Sms.Code,
                    TrackId: $scope.Sms.TrackId
                }
            };
            toaster.pop('wait', appConst.savingInprogress, null, 15000);
            blockUI.start();

            try {
                registerService.Register(model, $scope.chamberDomain).then(function (response) {
                    toaster.clear();
                    if (response.data.success) {
                        $scope.Sms.CodeSent = false;
                        $scope.Sms.CodeSent = false;

                        //Redirect to automatic login and Memberships Page 
                        blockUI.stop();
                        $scope.page.successRedirectLogin = true;
                        $timeout(function () {
                            authService.login({ username: $scope.registerData.IdentityNo, password: $scope.registerData.Password }, true);
                        }, 1600);
                    } else {
                        toaster.error({ title: response.data.message });
                        $scope.page.isLoading = false;
                        $scope.isFormSubmitted = false;
                        $timeout(function () { blockUI.stop(); }, 100);
                    }
                });
            } catch (e) {

            }

        };

        ////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

        ///////////////////////////////////// Captcha ///////////////////////////////////
        $scope.setResponse = function (response) {
            $scope.captcha.response = response;
        };

        $scope.setWidgetId = function (widgetId) {
            $scope.captcha.widgetId = widgetId;
        };

        $scope.cbExpiration = function () {
            vcRecaptchaService.reload($scope.captcha.widgetId);
            $scope.captcha.response = null;
        };

        /////////////////////////////////////////////////////////////////////////////////
        //redirect to steps 
        function updateSteps(step1, step2) {
            if (step2 === true) {
                $scope.Sms = { TrackId: null, Code: null, CodeSent: false };
                $scope.smsInputs = [{ id: 3, value: null }, { id: 2, value: null }, { id: 1, value: null }, { id: 0, value: null }];
                $scope.firstStep = false;
                $scope.secondStep = true;
            } else {
                $scope.smsInputs =
                    $rootScope.chamberSettings.useAbshir ? [{ id: 5, value: null }, { id: 4, value: null }, { id: 3, value: null }, { id: 2, value: null }, { id: 1, value: null }, { id: 0, value: null }] :
                        [{ id: 3, value: null }, { id: 2, value: null }, { id: 1, value: null }, { id: 0, value: null }];
                $scope.firstStep = true;
                $scope.secondStep = false;
            }
            $scope.isFormSubmitted = false;
            $scope.page.isLoading = false;

        }

        /////////////////////////////////////////////////////////////////////////////////////////////////////////////////

        //Swap between steps
        $scope.Back = function () {
            $scope.page.showSmsTime = false;
            $scope.validateWithoutAbshirDone = false;
            $scope.page.smsTimer = 0;
            $scope.Nafath = { Random: null, Status: '', TransactionId: '', Sent: false };
            $scope.loginWays.allowNafath = false;
            if ($scope.firstStep === true) {
                if ($scope.Sms.CodeSent) {
                    $scope.Sms = { TrackId: null, Code: null, CodeSent: false };
                    $scope.PhoneNumbersList = [];
                    $scope.registerData.Mobile = null;
                    $scope.smsInputs = [{ id: 5, value: null }, { id: 4, value: null }, { id: 3, value: null }, { id: 2, value: null }, { id: 1, value: null }, { id: 0, value: null }];
                    $scope.captcha = {
                        captchaKey: appConst.captchaKey,
                        response: null,
                        widgetId: null
                    };
                } else {
                    $scope.Sms = { TrackId: null, Code: null, CodeSent: false };
                    $scope.smsInputs = [{ id: 3, value: null }, { id: 2, value: null }, { id: 1, value: null }, { id: 0, value: null }];
                    $scope.PhoneNumbersList = [];
                    $scope.registerData.Mobile = null;
                    $scope.captcha = {
                        captchaKey: appConst.captchaKey,
                        response: null,
                        widgetId: null
                    };
                }
            }
            else {
                if ($scope.Sms.CodeSent) {
                    $scope.Sms = { TrackId: null, Code: null, CodeSent: false };
                    $scope.smsInputs = [{ id: 3, value: null }, { id: 2, value: null }, { id: 1, value: null }, { id: 0, value: null }];
                } else {
                    $scope.registerData.UserFullName = null;
                    $scope.registerData.PhoneNumber = null;
                    $scope.registerData.ConfirmPassword = null;
                    $scope.registerData.Email = null;
                    $scope.registerData.UserFullName = null;
                    $scope.captcha = {
                        captchaKey: appConst.captchaKey,
                        response: null,
                        widgetId: null
                    };
                    updateSteps(true, false);
                }
            }
        }

        ////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
        //Combine SMS Code from front to one string value to be validated
        $scope.combineCode = function (digit, index) {
            toaster.clear();
            if (digit !== null) {
                $scope.Sms.Code = ($scope.Sms.Code === null) ? ($scope.firstStep === true && $rootScope.chamberSettings.useAbshir && $scope.Sms.UseTcc == false ? 'xxxxxx' : 'xxxx') : $scope.Sms.Code;
                var a = $scope.Sms.Code.split('');
                a[$scope.smsInputs.length - index - 1] = digit.value;
                $scope.Sms.Code = a.join('');
                if ($scope.Sms.Code !== undefined && $scope.Sms.Code !== null && $scope.Sms.Code !== '') {
                    if ($scope.Sms.Code.toString().indexOf('x') === -1) {
                        if ($scope.secondStep === true && $scope.Sms.Code.length === 4) {
                            //Validate SMS Code 
                            $scope.page.isLoading = true;
                            $scope.isFormSubmitted = true;
                            $timeout(function () { $scope.Register(); }, 300);
                        }
                        else if ($scope.firstStep === true && ($rootScope.chamberSettings.useAbshir && ($scope.Sms.Code.length === 6 || ($scope.Sms.UseTcc == true && $scope.Sms.Code.length === 4))) || (!$rootScope.chamberSettings.useAbshir && $scope.Sms.Code.length === 4)) {
                            //Validate OTP Abshir
                            $scope.page.isLoading = true;
                            $scope.isFormSubmitted = true;
                            $timeout(function () {
                                if ($rootScope.chamberSettings.useAbshir && ($scope.Sms.Code.length === 6 || ($scope.Sms.UseTcc == true && $scope.Sms.Code.length === 4))) {
                                    $scope.ValidateIdentityOTP();
                                } else {
                                    $scope.ValidateSMSCode();
                                }

                            }, 300);

                        }
                    }
                }
            }
        }
        ////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
        // Reset Form Model
        $scope.Reset = function () {
            if ($scope.firstStep === true) {
                if ($scope.Sms.CodeSent) {
                    $scope.Sms.Code = null;
                    if ($rootScope.chamberSettings.useAbshir) {
                        $scope.smsInputs = [{ id: 5, value: null }, { id: 4, value: null }, { id: 3, value: null }, { id: 2, value: null }, { id: 1, value: null }, { id: 0, value: null }];
                    } else if ($scope.Sms.UseTcc === true)
                        $scope.smsInputs = [{ id: 3, value: null }, { id: 2, value: null }, { id: 1, value: null }, { id: 0, value: null }];
                    else {
                        $scope.smsInputs = [{ id: 3, value: null }, { id: 2, value: null }, { id: 1, value: null }, { id: 0, value: null }];
                    }
                } else {
                    $scope.registerData.IdentityNo = null;
                    $scope.cbExpiration();
                }
            }
            else {
                if ($scope.Sms.CodeSent) {
                    $scope.Sms.Code = null;
                    $scope.smsInputs = [{ id: 3, value: null }, { id: 2, value: null }, { id: 1, value: null }, { id: 0, value: null }];
                } else {
                    $scope.registerData.UserFullName = null;
                    $scope.registerData.PhoneNumber = null;
                    $scope.registerData.ConfirmPassword = null;
                    $scope.registerData.Email = null;
                    $scope.registerData.UserFullName = null;
                }
            }

        }

        ////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
        //Count down timer
        function smsTimer(timer = 120) {
            $scope.page.smsTimer = timer;
            $scope.page.showSmsTime = true;
            $interval(decrementCountdown, 1000, $scope.page.smsTimer);
        }

        var decrementCountdown = function () {
            $scope.page.showSmsTime = true;
            $scope.page.smsTimer -= 1;
            if ($scope.page.smsTimer < 1) {
                $scope.page.showSmsTime = false;
                $scope.page.smsTimer = 0;
            }
        };



        //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
        $scope.showPassword = function () {
            if ($scope.user !== null && $scope.user !== {} && $scope.user !== undefined) {
                if ($scope.user.password !== null) {
                    if ($scope.inputType === 'password') {
                        $scope.inputType = 'text';
                        $scope.showHideClass = 'glyphicon glyphicon-eye-close';
                    }
                    else {
                        $scope.inputType = 'password';
                        $scope.showHideClass = 'glyphicon glyphicon-eye-open';
                    }
                }
            }
        };
        ////////////////////////////////////////////////////////////////////////////////////////////////////////////////
        ///////////////////////////////////////////////////////////////////////////////////////////////////

        // Init functions
        //set step 1 active
        updateSteps(true, false);


        $scope.acceptAgreement = function (AgreementAccepted, registerForm) {
            if (!AgreementAccepted || ($scope.chamberSettings.isUnified && !$scope.registerData.ChamberId)) {
                if (registerForm.ChamberId) registerForm.ChamberId.$setTouched();
                return false;
            }
            $scope.page.AgreementAccepted = AgreementAccepted;
            updateSteps(true, false);
        }
        $scope.sendOtp2 = function (form) {
            let isFormValid = globalService.checkFormValidityAndUpdateStatus(form)
            if (!isFormValid) return;
            $scope.otp.isResend = false;
            $scope.otp.isSent = false;
            $scope.otp.code = '';
            let body = {
                identityNo: $scope.registerData.IdentityNo,
                reCaptchaResponse: $scope.captcha.response
            }
            blockUI.start();
            $scope.page.isLoading = true;
            registerService.SendOTP(body).then(function (response) {
                if (response.success) {
                    $scope.verifyOtpModel = response.data;
                    $scope.otp.isSent = true;
                    $scope.showOtpModal2 = true
                    $scope.otp.trackId = response.data.trackId;
                    $scope.otp.useTcc = response.data.useTcc;
                    otpTimer2();
                } else {
                    $scope.otp.isSent = false;
                    $scope.otp.code = '';
                    $timeout(function () {
                        toaster.clear();
                        if (response.code === 14) {
                            toaster.error('لا يوجد لديك حساب بالبوابة الإلكترونية برجاء تسجيل حساب أولا.');
                        } else {
                            toaster.error(response.message);
                        }
                    }, 0);
                }
            }).catch(function (response) {
                $timeout(function () {
                    toaster.clear(); toaster.error(response.message);
                }, 0);
                if (response.execptionMessage) {
                    $timeout(function () {
                        toaster.clear(); toaster.error(response.execptionMessage);
                    }, 0);
                }
                $scope.otp.isSent = false;
                $scope.otp.code = '';
            }).finally(function () {
                $scope.page.isLoading = false;
                blockUI.stop();
                form.captchaKey.$setUntouched();
                $scope.cbExpiration();
            });
        };
        $scope.$watch('otp.code.length', function (newValue, oldValue) {
            if (($scope.verifyOtpModel?.codeLength === 1 && newValue === 4) || ($scope.verifyOtpModel?.codeLength === 6 && newValue === 6)) {
                $scope.validateOtp2();
            }
        });
        function otpTimer2() {
            $scope.otp.showTimer = true;
            $scope.otp.timer = 180;
            var x = setInterval(function () {
                $scope.otp.timer = --$scope.otp.timer;
                if ($scope.otp.timer <= 0) {
                    clearInterval(x);
                    $scope.otp.showTimer = false;
                    $scope.otp.timer = 0;
                }
            }, 1000);
        }
        $scope.hideOtpModal2 = function () {
            $scope.otp.isSent = false;
            $scope.otp.timer = 120;
            $scope.otp.showTimer = false;
            $scope.showOtpModal2 = false;
        }

        $scope.changePhoneNo = function () {
            $scope.showOtpModal2 = true;
        }
        $scope.cbExpiration2 = function () {
            vcRecaptchaService.reload($scope.captcha.widgetId);
            $scope.captcha.response = null;
        };
        $scope.setWidgetId2 = function (widgetId) {
            $scope.captcha.widgetId = widgetId;
        };

        $scope.sendCode2 = function () {
            $scope.otp.isResend = true;
        }
        $scope.validateOtp2 = function () {
            blockUI.start();
            $scope.page.isLoading = true;
            registerService.ValidateIdentityOTP({ Code: $scope.otp.code, TrackId: $scope.otp.trackId, UseTcc: $scope.otp.useTcc }, $scope.chamberDomain).then(function (response) {
                //ngProgress.complete();
                blockUI.stop();
                if (response.data.success) {
                    // $scope.page.showOtpModal = false;

                    $timeout(function () {
                        $scope.page.isLoading = false;
                        $scope.otp.code = null;
                        $scope.otp.isSent = false;
                        $scope.page.authOwnerPhone = true
                        $scope.hideOtpModal2();
                    }, 1000);
                } else {
                    // $scope.Sms.Code = null;
                    $scope.page.isLoading = false;
                    toaster.error({ title: response.data.message });
                }
            });
        }

        // SignalR connection
        signalRSvc.init("nafathHub", [
            {
                eventName: "NafathRegisterResponse",
                callbackFn: function (jsonData) {
                    // Add the message to the page.
                    alert(jsonData);
                    if (jsonData.succeeded) {
                        //TODO : add phonenumber and set readonly
                        $scope.registerData.UserFullNameEn = jsonData.mO_NameEN;
                        $scope.registerData.UserFullName = jsonData.mO_Name;
                        //call log in function
                    } else {


                        //show error messages
                        //$rootScope.timer = 0;
                        //$rootScope.random = '';
                        $rootScope.nafathError = '';
                        if (jsonData.messages && jsonData.messages.length > 0) {
                            for (var i = 0; i < jsonData.messages.length; i++) {

                            }
                        }
                        else { }
                    }
                    /**{"messages":[],"succeeded":true,"data":{"status":"","transactionId":""},"code":0} */
                },
            },
        ]);

        signalRSvc
            .startConnection()
            .then(function () {
                console.log("SignalR connected.", connectionId);
            })
            .catch(function (error) {
                console.log("SignalR could not connect: " + error);
            });
    }]);
;

"use strict";
app.controller('MemberIdQueryController', ['$route', 'blockUI', '$rootScope', '$scope', 'ngNotify', '$timeout', 'ngProgress', '$routeParams', '$q', '$compile', 'appConst', 'registerService', 'vcRecaptchaService', 'authService', 'LookupSvc',"chamberList",
    function ($route, blockUI, $rootScope, $scope, ngNotify, $timeout, ngProgress, $routeParams, $q, $compile, appConst, registerService, vcRecaptchaService, authService, LookupSvc,chamberList) {
        $scope.showresult = false;
        $scope.captcha = {
            captchaKey: appConst.captchaKey,
            response: null,
            widgetId: null
        };

        $scope.ChamberList = chamberList;

        $scope.registerData = { VerifyWay: null, CR_No: null, QueryByIdentity: $routeParams.id == "true" ? true : false, IdentityNo: null, MM_UnifiedNumber: null, ChamberId : null };

        $scope.VerifyWays = [{ key: 2, name: 'الرقم الموحد (700)' }]

        $scope.checkMember = function (form, event) {
            $scope.isFormSubmitted = true;
            event.preventDefault();

            if (!form.$valid) {
                return false;
            }
            var model = {
                CR_No: $scope.registerData.CR_No,
                IdentityNo: $scope.registerData.IdentityNo,
                MM_UnifiedNumber: $scope.registerData.MM_UnifiedNumber,
                VerifyWay: $scope.registerData.VerifyWay,
                QueryByIdentity: $scope.registerData.QueryByIdentity,
                ReCaptchaResponse: $scope.captcha.response,
                MemberId: '0'
            };
            blockUI.start();
            registerService.GetMemberId(model, $scope.chamberDomain).then(function (response) {
                if (response.data.success) {
                    if ($scope.registerData.QueryByIdentity) {
                        $scope.message = response.data.message;
                    } else {
                        $scope.message = "رقم العضوية الخاص بكم : " + response.data.data.mM_MemberId;
                    }
                 
                    $timeout(function () { blockUI.stop(); }, 100);
                    $scope.showresult = true;
                } else {
                    $scope.showresult = true;
                    $scope.message = " عفوا لا يوجد بيانات متوفرة ";
                    $timeout(function () { blockUI.stop(); }, 100);
                }
            });
        };

        ///////////////////////////////////// Captcha ///////////////////////////////////
        $scope.setResponse = function (response) {
            $scope.captcha.response = response;
        };

        $scope.setWidgetId = function (widgetId) {
            $scope.captcha.widgetId = widgetId;
        };

        $scope.cbExpiration = function () {
            vcRecaptchaService.reload($scope.captcha.widgetId);
            $scope.captcha.response = null;
        };

        $scope.resetRecaptcha = function () {
            $scope.cbExpiration();
        };
        /////////////////////////////////////////////////////////////////////////////////
        $scope.RestForm = function () {
            $route.reload();
        }
        $scope.onChamberDomainChange = function () {
            $scope.chamberDomain = $scope.ChamberList.filter(item => item.chamberId == $scope.registerData.ChamberId)[0].chamberDomain
        }

    }]);
;
"use strict";
app.controller('HomeController', ['$scope', '$rootScope', 'AllRequestSvc', '$timeout', 'blockUI', '$uibModal', 'localStorage', 'session', 'ngProgress', 'toaster', 'UsersSvc',
    function ($scope, $rootScope, AllRequestSvc, $timeout, blockUI, $uibModal, localStorage, session, ngProgress, toaster, UsersSvc) {

        $rootScope.NavigationTitle = 'الصفحة الرئيسية ';
        $rootScope.title = 'الصفحة الرئيسية ';
        if (!$rootScope.userInfo.globalSessionValues.CurrentMember && localStorage.getItem('Subscriber') === true) {
            window.location.href = '/#/Landing';
        }

        $rootScope.IsSubscriber = true;
        session.addDataToLocalStorage('IsSubscriber', true);
        $scope.showImagePopup = true;
        $scope.showMemberExpireAlret = false;
        // رسالة تنبيه لشحن المحفظة فى حالة الدخول لأول مرة 
        $(".modal-backdrop").css("display", "none");

        if ($rootScope.userInfo.globalSessionValues.ChamberData.UseMeetings && $rootScope.userInfo.globalSessionValues.ChamberData.ChamberId === 302) {
            $scope.showMeetingAlert = true;
        }

        if (!$rootScope.userInfo.globalSessionValues.CurrentMember.BannerIsSeen && $rootScope.chamberSettings.showServiceBanner === true && $rootScope.userInfo.globalSessionValues.ChamberData.ChamberId === 302) {
            $rootScope.showCommercialBanner = true;
            $uibModal.open({
                animation: true,
                templateUrl: 'ComPartnerBanner.html',
                controller: 'ModalInstanceCtrl'
            });
        }

        const currentDate = new Date();
        const expireDate = new Date($rootScope.userInfo.globalSessionValues.CurrentMember.ExpiredDate);
        const diffTime = Math.abs(expireDate - currentDate);
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

        if (diffDays < 30 && diffDays > 0 && $rootScope.userInfo.globalSessionValues.CurrentMember.IsExpired != 1) {
            $scope.showMemberExpireAlret = true;
        }

        /////////////////////////////////////////////////////////////////////////////////////////////////////////

        $scope.ChamberActivatedRequests = [];
        blockUI.start();
        AllRequestSvc.GetChamberActivatedRequests().then(function (response) {
            $scope.ChamberActivatedRequests = response.data;
            blockUI.stop();
        });


        $scope.getRequestName = function (id) {
            if ($scope.ChamberActivatedRequests && $scope.ChamberActivatedRequests.length > 0) {
                var row = $.grep($scope.ChamberActivatedRequests, function (b) {
                    return b.requestTypeId === id;
                })[0];
                if (row !== null && row !== '' && row !== undefined) {
                    return row.nameAr;
                }
            }
        }

        $scope.checkRequests = function (id) {
            var exist = false;
            if ($rootScope.userInfo.globalSessionValues.ChamberData.ChamberId == 201 && id == 28) {
                id = 57
            }
            if ($rootScope.userInfo.globalSessionValues.ChamberData.ChamberId == 201 && id == 41) {
                id = 53
            }
            angular.forEach($scope.ChamberActivatedRequests, function (value, key) {
                if (value.requestTypeId === id) {
                    exist = true;
                }
            });
            if ($rootScope.userInfo.globalSessionValues.ChamberData.ChamberId == 302) {
                exist = false;
            }
            return exist;
        }

        $scope.checkIsMostUsed = function (id) {
            var exist = false;
            if ($rootScope.userInfo.globalSessionValues.ChamberData.ChamberId == 201 && id == 28) {
                id = 57
            }
            if ($rootScope.userInfo.globalSessionValues.ChamberData.ChamberId == 201 && id == 41) {
                id = 53
            } agreementText
            angular.forEach($scope.ChamberActivatedRequests, function (value, key) {
                if (value.requestTypeId === id && value.isMostUsed === true) {
                    exist = true;
                }
            });
            return exist;
        }

        $scope.updateInformation = function (crNumber) {
            swal({
                title: 'تأكيد طلب تحديث بيانات السجل', type: "warning",
                text: 'يرجى العلم أن طلب تحديث البيانات يتم مرة كل عدد ' + $rootScope.chamberSettings.crWathiqUpdateTime + ' ساعة، هل تود الاستمرار ؟',
                showCloseButton: true,
                showCancelButton: true,
                closeOnConfirm: true,
                closeOnCancel: true,
                confirmButtonText: 'موافق',
                cancelButtonText: 'الغاء'
            },
                function (isConfirm) {
                    if (isConfirm) {
                        // call the new api    
                        toaster.pop('wait', "جاري تحديث البيانات")
                        swal.close()
                        blockUI.start();
                        let chamberId = $rootScope.userInfo.globalSessionValues.ChamberData.ChamberId
                        UsersSvc.UpdateCommercial({ crNumber, chamberId, MemberId: $rootScope.userInfo.globalSessionValues.CurrentMember.MemberId }).then((response) => {
                            toaster.clear();
                            if (response.success) {
                                toaster.success({ title: "تم تحديث بيانات السجل بنجاح." });
                            } else {
                                toaster.error({ title: response.message });
                            }

                        }).finally(() => {
                            blockUI.stop();
                        })
                    }
                }
            )
        }
    }]);
;

"use strict";
app.controller('ProfileController', ['$rootScope', '$route', 'session', '$timeout', 'toaster', 'ngProgress', '$location', 'Alertify', '$q', 'appConst', '$scope', 'ProfileSvc', 'UsersSvc', 'GateWaySvc', '$window', 'blockUI',
    function ($rootScope, $route, session, $timeout, toaster, ngProgress, $location, Alertify, $q, appConst, $scope, ProfileSvc, UsersSvc, GateWaySvc, $window, blockUI) {

        $rootScope.title = "إعدادات الحساب";
        $rootScope.NavigationTitle = "إعدادات الحساب";
        ///////////////////////////////////////////////////////////////////////////////////////////////////////////////////
        $scope.page = {
            formType: '',
            childFormType: '',
            showMergeWays: false,
            showConfirmMergeCodeMoal: false,
            showConfirmStatusCodeMoal: false,
            showSpin: false
        };
        //if (!$scope.userInfo.globalSessionValues.CurrentMember && $scope.chamberSettings.isUnified) {
        //    $location.path('/Landing');
        //}
        //  swal.close();
        $scope.sms = { trackId: null, smsCode: null, codeNumber: '', codeToMatch: '', codeSent: false, UseTcc :false};
        $scope.changeStatus = { status: null, object: {} };
        $scope.mergeWays = [];

        $scope.PasswordPattern = '(?!^[0-9]*$)(?!^[a-zA-Z]*$)^([a-zA-Z0-9]{8,30})$';
        $scope.showHidePhone = false;
        $scope.MemberUser = {
            userName: ''
        };
        $scope.tab = 2;
        $scope.user = {
            currentPassword: '',
            newPassword: '',
            confirmNewPassword: ''
        };
        $scope.PageSize = 10;
        $scope.AllUsersData = [];
        $scope.transPageNo = 1;
        $scope.transCurrentPage = 1;
        $scope.transTotalCount = 0;
        $scope.transItemsPerPage = 10;
        $scope.Users = [];
        $scope.emailNotValid = true;

        $scope.setTab = function (tabId) {
            $scope.tab = tabId;
        };

        $scope.isSet = function (tabId) {
            return $scope.tab === tabId;
        };

        $scope.userData = {
            userName: '',
            userFullName: '',
            userFullNameEn: '',
            password: '',
            email: '',
            phoneNumber: ''
        };

        //////////////////////////////////////////////////////////////////////////////////////////////////////////////////
        $scope.$watch('sms.smsCode.length', function (newValue, oldValue) {
            if (newValue === 4) {
                $scope.addMerge();
            }
        });
        //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

        /*Change Password Function*/
        $scope.changePassword = function () {
            if ($scope.user.confirmNewPassword !== $scope.user.newPassword) {
                toaster.error('كلمة المرور الجديدة و تأكيد كلمة المرور الجديدة غير متشابهين.');
                return false;
            }
            ngProgress.start();
            blockUI.start();
            if ($scope.user.confirmNewPassword && $scope.user.newPassword) {
                var details = { OldPassword: $scope.user.currentPassword, NewPassword: $scope.user.newPassword, ConfirmPassword: $scope.user.confirmNewPassword };
                ProfileSvc.changePassword(details).then(function (response) {
                    if (response.success) {
                        ngProgress.complete();
                        $scope.user = {};
                        $location.path('/Login');
                        toaster.success(response.message);

                    } else {
                        ngProgress.complete();
                        toaster.error(response.message);
                       // $scope.user = {};
                    }
                });
                blockUI.stop();
            } else {
                ngProgress.complete();
                toaster.error(appConst.insertValidEntries);
                blockUI.stop();
            }
        };

        $scope.setPassword = function (form, event) {
            $scope.isFormSubmitted = true;
            event.preventDefault();
            if (!form.$valid) {
                return false;
            }
            ngProgress.start();
            blockUI.start();
            if ($scope.user.confirmNewPassword && $scope.user.newPassword) {
                var details = { NewPassword: $scope.user.newPassword, ConfirmPassword: $scope.user.confirmNewPassword };
                ProfileSvc.SetPassword(details).then(function (response) {
                    if (response.success) {
                        ngProgress.complete();
                        $scope.user = {};
                        $location.path('/Login');
                        toaster.success(response.message);

                    } else {
                        ngProgress.complete();
                        toaster.error(response.Message);
                        $scope.user = {};
                    }
                    blockUI.stop();
                });

            } else {
                ngProgress.complete();
                toaster.error(appConst.insertValidEntries);
                blockUI.stop();
            }
        };

        $scope.GetUsersByMemberId = function () {
            $scope.AllUsersData = [];
            $scope.showSpinner = true;
            ngProgress.start();

            var details = {
                StartRowNumber: $scope.transPageNo, PageSize: $scope.transItemsPerPage, UserName: $scope.MemberUser.UserName
            };
            ProfileSvc.GetUsersByMemberId(details).then(function (response) {
                if (response.success) {
                    if (response.data.length > 0) {
                        $scope.transTotalCount = response.data[0].rowsCount;
                        $scope.transCurrentPage = $scope.transPageNo;
                        angular.forEach(response.data, function (val, key) {
                            val.expanded = false;
                            $scope.AllUsersData.push(val);
                        });
                        $scope.showSpinner = false;

                        ngProgress.complete();
                    } else {
                        $scope.showSpinner = false;
                        $scope.AllUsersData = [];
                        $scope.transTotalCount = 0;

                        ngProgress.complete();
                    }
                } else {
                    $scope.showSpinner = false;
                    $scope.AllUsersData = [];
                    $scope.transTotalCount = 0;

                    ngProgress.complete();
                    Alertify.error(response.message);
                }
            });

        };

        $scope.ActiveStop = function (value, name) {
            if (value === 1) {
                $scope.isActive = true;
            }
            else {
                $scope.isActive = false;
            }
            var details = { UserName: name, IsActive: $scope.isActive };
            ProfileSvc.ActiveStop(details).then(function (response) {
                if (response.success) {
                    $scope.showSpinner = false;

                    ngProgress.complete();
                    Alertify.success(response.message);
                    $scope.GetUsersByMemberId();
                } else {
                    ngProgress.complete();
                    $scope.showSpinner = false;

                    Alertify.error(response.message);
                }
            });
        };

        $scope.Init = function () {
            $scope.GetUsersByMemberId();
        };

        $scope.checkEmailData = function (email) {
            if (email !== "") {
                var UserInfo = { UserName: null, Email: email };
                GateWaySvc.CheckEmailData(UserInfo).then(function (response) {
                    if (response.data.success === true) {
                        $scope.emailNotValid = true;
                    } else {
                        $scope.emailNotValid = false;
                    }
                });
            }
        };

        $scope.$watch('sms.codeToMatch.length', function (newValue, oldValue) {
            if (newValue === 6 || (newValue === 4 && $scope.sms.UseTcc === true)) {
                if (!Number.isInteger(parseInt($scope.sms.codeToMatch))) {
                    toaster.error('كود التحقق غير صحيح !');
                    return false;
                }

                $scope.userData.Code = $scope.sms.codeToMatch;
                $scope.userData.CheckOTP = true;
                $scope.userData.UseTcc = $scope.sms.UseTcc;

                //update user
                ngProgress.start();
                $scope.emailNotValid = false;
                var newEmail = false;
                if ($scope.userData.email !== session.getPropertyLocalStorage("Email", false)) {
                    newEmail = true;
                }

                toaster.pop('wait', appConst.updateInProgress, null, 8000);

                $scope.userData.NewEmail = newEmail;
                $scope.userData.UserName = $scope.userData.userName;
                $scope.userData.TrackId = $scope.userData.TrackId;
                $scope.userData.Code = $scope.userData.Code;
                $scope.userData.FromPortal = 1;
                $scope.userData.PhoneNumber = $scope.userData.phoneNumber;
                $scope.userData.Email = $scope.userData.email;
                $scope.userData.Current = true;
                $scope.userData.MemberId = $rootScope.userInfo.globalSessionValues.CurrentMember?.MemberId;
                $scope.userData.FilesList = $scope.imagesList; 

                UsersSvc.UpdateUser($scope.userData).then(function (response) {
                    toaster.clear();
                    if (response.success === true) {
                        var userInfo = JSON.parse($window.localStorage.getItem('userInfo_' + $location.$$host));
                        userInfo.globalSessionValues.LoggedInEmail = $scope.userData.Email;
                        userInfo.globalSessionValues.UserData.Email = $scope.userData.Email;
                        userInfo.globalSessionValues.UserData.PhoneNumber = $scope.userData.phoneNumber;
                        userInfo.globalSessionValues.UserData.AdditionalMobileNumber = $scope.userData.additionalMobileNumber;
                        userInfo.globalSessionValues.UserData.UserFullName = $scope.userData.userFullName;
                        userInfo.globalSessionValues.UserData.UserFullNameEn = $scope.userData.userFullNameEn; 
                        $scope.userData.userFullName = response.data.userFullName;
                        $scope.userData.userFullNameEn = response.data.userFullNameEn;
                        $scope.userData.email = response.data.email;
                        $scope.userData.phoneNumber = response.data.phoneNumber;
                        newEmail = false;
                        $window.localStorage['userInfo_' + $location.$$host] = JSON.stringify(userInfo);
                        swal.close();
                        toaster.success(appConst.dataSavedSuccess);
                        $route.reload();
                        if (!$rootScope.userInfo.globalSessionValues.CurrentMember) {
                            window.location.href = '/#/Landing';
                        }
                        ngProgress.complete();
                    }
                    else {
                        $timeout(function () {
                            toaster.error(response.message);
                        }, 0);
                        ngProgress.complete();
                    }
                });
            }
        });

        $scope.updateUserData = function (user, form, event) {
            $scope.isFormSubmitted = true;
            $scope.userData.CheckOTP = false;
            $scope.sms.codeSent = false;
            $scope.sms.codeToMatch = null;
            event.preventDefault();
            if (!form.$valid) {
                return false;
            }

            if (user.phoneNumber !== $rootScope.userInfo.globalSessionValues.UserData.PhoneNumber) {
                //send OTP
                blockUI.start();
                UsersSvc.SendChangePhoneNumberOTP({}).then(function (response) {
                    blockUI.stop();
                    if (!response.success) {
                        toaster.error(response.Message);
                        return false;
                    }

                    $scope.userData.TrackId = response.data.trackId;
                    $scope.sms.UseTcc = response.data.useTcc;
                    $scope.sms.TrackId = response.data;
                    $scope.sms.codeSent = true;
                });
            } else {
                ngProgress.start();
                $scope.emailNotValid = false;
                var newEmail = false;
                if (user.email !== session.getPropertyLocalStorage("Email", false)) {
                    newEmail = true;
                }
                toaster.pop('wait', appConst.updateInProgress, null, 8000);

                user.NewEmail = newEmail;
                user.UserName = user.userName;
                user.TrackId = $scope.userData.TrackId;
                user.Code = $scope.userData.Code;
                user.FromPortal = 1;
                user.PhoneNumber = user.phoneNumber;
                user.Email = user.email;
                user.Current = true;
                user.FilesList= $scope.imagesList;

                UsersSvc.UpdateUser(user).then(function (response) {
                    toaster.clear();
                    if (response.success === true) {
                        var userInfo = JSON.parse($window.localStorage.getItem('userInfo_' + $location.$$host));
                        userInfo.globalSessionValues.LoggedInEmail = response.data.email;
                        userInfo.globalSessionValues.UserData.Email = response.data.email;
                        userInfo.globalSessionValues.UserData.PhoneNumber = response.data.phoneNumber;
                        userInfo.globalSessionValues.UserData.AdditionalMobileNumber = response.data.additionalMobileNumber;
                        userInfo.globalSessionValues.UserData.UserFullName = response.data.userFullName;
                        userInfo.globalSessionValues.UserData.UserFullNameEn = response.data.userFullNameEn;
                       // userInfo.globalSessionValues.FilesList = $scope.imagesList;
                        newEmail = false;
                        $window.localStorage['userInfo_' + $location.$$host] = JSON.stringify(userInfo);

                        $scope.userData.userFullName = response.data.userFullName;
                        $scope.userData.userFullNameEn = response.data.userFullNameEn;
                        $scope.userData.email = response.data.email;
                        $scope.userData.phoneNumber = response.data.phoneNumber;

                        toaster.success(appConst.dataSavedSuccess);

                        if (!$rootScope.userInfo.globalSessionValues.CurrentMember) {
                            window.location.href = '/#/Landing';
                            $route.reload();
                        }
                        ngProgress.complete();
                    }
                    else {
                        toaster.error(response.message);
                        ngProgress.complete();
                    }
                });
            }
        };

        function setPage() {
            if ($location.absUrl().indexOf('AccountMembers') !== -1) {
                $rootScope.NavigationTitle = 'بيانات الحساب';
                window.location.href = "/#/Profile/AccountInfo";
            } else if ($location.absUrl().indexOf('AccountInfo') !== -1) {
                $rootScope.NavigationTitle = 'بيانات الحساب';
                $scope.userData = {
                    userName: $rootScope.userInfo.userName,
                    email: $rootScope.userInfo.globalSessionValues.UserData.Email,
                    phoneNumber: $rootScope.userInfo.globalSessionValues.UserData.PhoneNumber,
                    additionalMobileNumber: $rootScope.userInfo.globalSessionValues.UserData.AdditionalMobileNumber,
                    userFullName: $rootScope.userInfo.globalSessionValues.UserData.UserFullName,
                    userFullNameEn: $rootScope.userInfo.globalSessionValues.UserData.UserFullNameEn,
                    IdentityNo: $rootScope.userInfo.userName 
                };
               
                $scope.SelectedFileForUpload = [];
                angular.forEach($scope.imagesList, function (v, k) {
                    $scope.SelectedFileForUpload.push({
                        AttachmentTypeId: v.AttachmentTypeId, AttachmentTypeName: v.AttachmentTypeName, Name: v.Name,
                        Src: 'data:' + v.Type + ';base64,' + v.Source
                    });
                    if (v.AttachmentTypeId === 1) {
                        angular.forEach($scope.AttachmentTypes, function (vv, kk) {
                            if (vv.Id == v.AttachmentTypeId) {
                                vv.Uploaded = true; 
                            }
                        });
                    }
                    if (v.AttachmentTypeId === 2) {
                        angular.forEach($scope.AttachmentTypes, function (vv, kk) {
                            if (vv.Id == v.AttachmentTypeId) {
                                vv.Uploaded = true;
                            }
                        });
                    }

                });
                $scope.page.formType = 2;
                $scope.page.childFormType = 2;
            } else {
                $rootScope.NavigationTitle = 'تغيير كلمة السر';
                $scope.page.formType = 1;
            }
        }


        //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
        $scope.AttachmentTypes = [
            { Id: 1, Name: 'صورة الهوية / الإقامة', IsRequired: false, Uploaded: false, File: null, Hide: false },
            { Id: 2, Name: 'مرفقات أخري', IsRequired: false, Uploaded: false, File: null, Hide: false }
        ];

        $scope.imagesList = [];

        $scope.selectFile = function (file, type, title) {
            PrepareUpload(file, type, title).then(function (response) {
                if (!response.Success) {
                    $timeout(function () {
                        toaster.clear(); toaster.error(response.Message);
                    }, 0);
                }
            });
        };
        $scope.removeImg = function (item) {
            var indexx = $scope.imagesList.indexOf(item);
            if (indexx !== -1) {
                $scope.imagesList = $.grep($scope.imagesList, function (v, k) {
                    return indexx !== k;
                });
                var file = $scope.SelectedFileForUpload.find(v => v.name === item.name);
                var index = $scope.SelectedFileForUpload.indexOf(file);
                $scope.SelectedFileForUpload.splice(index, 1);
                angular.forEach($scope.AttachmentTypes, function (v, key) {
                    if (v.Id === item.AttachmentTypeId)
                        v.Uploaded = false;
                });
            }
        };
        $scope.imageIsLoaded = function (e) {
            $scope.$apply(function () {
                return new Uint8Array(e.target.result);
            });
        };
        function PrepareUpload(file, AttachmentTypeId, title) {
            var deferred = $q.defer();
            var FinalResponse = { Success: null, Message: null };
            var extentions = 'pdf,jpg,png,jpeg';
            angular.forEach(file, function (val, key) {
                var ext = val.name.slice(val.name.lastIndexOf('.') + 1).toLowerCase();
                if (extentions.indexOf(ext) <= -1) {
                    angular.forEach(
                        angular.element("input[type='files']"),
                        function (inputElem) {
                            angular.element(inputElem).val(null);
                        });
                    FinalResponse = { Success: false, Message: appConst.fileTypeNotSupported };
                    $scope.page.currentStep = 2;
                    file = [];
                    deferred.resolve(FinalResponse);
                    return deferred.promise;
                }
            });

            angular.forEach(file, function (val, key) {
                var maxfilesize = 2000000;
                var maxfilesizemessage = "لايمكن اضافة ملف اكبر من 2 ميجا";
                if (val.size > maxfilesize) {
                    FinalResponse = { Success: false, Message: maxfilesizemessage };
                    angular.forEach(
                        angular.element("input[type='files']"),
                        function (inputElem) {
                            angular.element(inputElem).val(null);
                        });
                    file = [];
                    deferred.resolve(FinalResponse);
                    return deferred.promise;
                }
            });

            if (window.File && window.FileList && window.FileReader) {
                var files = file,
                    filesLength = files.length;
                angular.forEach(files, function (val, key) {
                    var gg = $scope.SelectedFileForUpload;
                    $scope.SelectedFileForUpload = [];
                    $scope.SelectedFileForUpload.push(val);
                    angular.forEach(gg, function (v, key) {
                        $scope.SelectedFileForUpload.push(v);
                    });
                });

                Array.from(files).forEach(f => {
                    var reader = new FileReader();
                    var image = { Name: f.name, Source: [], Src: [], Type: f.type, AttachmentTypeId: AttachmentTypeId, AttachmentTypeName: title };
                    reader.onload = function (e) {

                        if (AttachmentTypeId !== undefined) {
                            image = { Name: f.name, Source: [], Src: e.target.result, Type: f.type, AttachmentTypeId: AttachmentTypeId, AttachmentTypeName: title };
                            angular.forEach($scope.AttachmentTypes, function (v, key) {
                                if (v.Id === AttachmentTypeId)
                                    v.Uploaded = true;
                            });
                        } else {
                            image = { Name: f.name, Source: [], Src: e.target.result, Type: f.type, AttachmentTypeId: 8, AttachmentTypeName: 'مرفق عام' };
                        }
                    };
                    reader.readAsDataURL(f);
                    $timeout(function () {
                        reader = new FileReader();
                        reader.onload = function (e) {
                            $scope.$apply(function () {
                                var array = new Uint8Array(e.target.result);
                                var arr = [];
                                for (var i = 0; i < array.length; i++) {
                                    arr.push(array[i]);
                                }

                                if (arr.length > 0) {
                                    image.Source = arr;
                                    $scope.imagesList.push(image);
                                }
                            });
                        };
                        reader.readAsArrayBuffer(f);
                    });
                });

                $('input[type="file"]').val(null);
                FinalResponse = { Success: true, Message: 'sucess load files ' };
                deferred.resolve(FinalResponse);
                return deferred.promise;

            } else {
                FinalResponse = { Success: false, Message: appConst.fileAPINotSupported };
                deferred.resolve(FinalResponse);
                return deferred.promise;
            }
        }

        $scope.capitalizeObject = function (model) {
            var key, keys = Object.keys(model);
            var n = keys.length;
            var newobj = {};
            while (n--) {
                key = keys[n];
                newobj[key.charAt(0).toUpperCase() + key.substr(1)] = model[key];
            }
            model = newobj;
            return model;
        };

        //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

        function GetUserProfileAttachments() {
            $scope.imagesList = [];
            UsersSvc.GetUserProfileAttachments({}).then(function (response) {
                if (response.success) {
                    angular.forEach(response.data, function (v, k) {
                        var row = $scope.capitalizeObject(v);
                        $scope.imagesList.push(row);
                    });

                    setPage();
                } else { 
                    Alertify.error(response.message);
                }
            });
        }

        /////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
        GetUserProfileAttachments();
        


    }]);
;

