        ///////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
        $scope.selectedRequest = {};
        $scope.PrepareAcceptOrRejectRequestWithWorkFlow = function (obj, IsAcceptRequest) {
            $scope.selectedRequest = obj;
            $scope.selectedRequest.IsAcceptRequest = IsAcceptRequest;
            Alertify.confirm(IsAcceptRequest === true ? appConst.areYouSureAccept : appConst.areYouSureReject).then(
                function onOk() {
                    if (IsAcceptRequest) {
                        $scope.sendCode(obj.requestType);
                    } else {
                        alertify.prompt("أدخل سبب الرفض ", function (e, str) {
                            if (e) {
                                $scope.selectedRequest.RejectReason = str;
                                $scope.sendCode(obj.requestType);
                            } else {
                                alertify.error('Cancel');
                            }
                        }, "");
                    }
                },
                function onCancel() { console.log("cancel"); }
            );
        };

        $scope.AcceptOrRejectRequestWithWorkFlow = function () {
            var model = {
                IsAcceptRequest: $scope.selectedRequest.IsAcceptRequest,
                RejectReason: $scope.selectedRequest.RejectReason,
                RequestId: $scope.selectedRequest.requestId,
                RequestType: $scope.selectedRequest.requestType,
                SMS: $scope.sms
            };
            blockUI.start();
            AllRequestSvc.AcceptOrRejectWithWorkFlow(model).then(function (response) {
                ngProgress.complete();
                blockUI.stop();
                if (response.success) {
                    $scope.sms.codeSent = false;
                    $scope.sms.Code = null;
                    $route.reload();
                } else {
                    toaster.clear();
                    toaster.pop('error', response.message);
                }
            });
        };

        $scope.sendCode = function (id) {
            $scope.sms.codeSent = false;
            $scope.sms.Code = null;
            blockUI.start();
            ngProgress.start();
            AllRequestSvc.SendRequestSMSCode(id).then(function successCallback(response) {
                if (response.success) {
                    ngProgress.complete();
                    $scope.sms.codeSent = true;
                    smsTimer();
                    $scope.sms.TrackId = response.data;
                } else {
                    ngProgress.complete();
                    $scope.sms.codeSent = false;
                    $scope.sms.codeNumber = '';
                    toaster.clear(); toaster.pop('error', response.message);
                }
                blockUI.stop();
            }, function errorCallback(response) {
                toaster.clear(); toaster.pop('error', response.message);
                if (response.execptionMessage) {
                    toaster.clear();
                    toaster.pop('error', response.execptionMessage);
                }
                ngProgress.complete();
                $scope.sms.codeSent = false;
                $scope.sms.codeNumber = '';
                blockUI.stop();
            });
        };

        //functon sms request 
        function smsTimer() {
            $scope.page.showSmsTime = true;
            $scope.page.smsTimer = 240;
            var x = setInterval(function () {
                $scope.page.smsTimer = --$scope.page.smsTimer;
                if ($scope.page.smsTimer <= 0) {
                    clearInterval(x);
                    $scope.page.showSmsTime = false;
                    $scope.page.smsTimer = 0;
                }
            }, 1000);
        }

        $scope.capitalizeObject = function (model) {
            var key, keys = Object.keys(model);
            var n = keys.length;
            var newobj = {};
            while (n--) {
                key = keys[n];
                newobj[key.charAt(0).toUpperCase() + key.substr(1)] = model[key];
            }
            model = newobj;
            return model;
        };

        $scope.sanitizeMe = function (text) {
            return $sce.trustAsHtml(text);
        };

        // Request Details
        $scope.formInputs = [];
        $scope.isDynamicForm = false;
        $scope.details = function (obj, from) {
            $scope.htmlPage = "";
            $scope.formInputs = [];
            $scope.isDynamicForm = false;
            angular.forEach($scope.objects, function (item, key) {
                if (item.requestId === obj.requestId) {
                    item.thereIsData = false;
                    item.noData = false;
                    item.showLoad = true;
                }
                else {
                    item.expanded = false;
                    item.thereIsData = false;
                    item.showLoad = false;
                    item.noData = false;
                }
            });
            ngProgress.start();
            $scope.RequestModel = null;
            AllRequestSvc.Details({ RequestId: obj.requestId }).then(function (response) {
                if (response.success) {
                    try {
                        $scope.RequestModel = $scope.capitalizeObject(response.data.model);
                        $scope.cityId = response.data.model.mM_AdrCity;
                        angular.forEach($scope.Cities, function (val, key) {
                            if ($scope.cityId === val.id) {
                                $scope.RequestModel.mM_AdrCity = val.name;
                            }
                        });
                        $scope.isDynamicForm = response.data.isDynamicForm;
                        if (response.data.isDynamicForm && !$scope.formInputs?.length) {
                            $scope.formInputs = [];
                            response.data.requestTypeDetail.forEach(input => {
                                // select case ( single & multi)
                                if (input.fieldType == 6) {
                                    if (input.isReadOnly) return
                                    let newInput = { ...input }
                                    if (input.options) newInput.options = JSON.parse(input.options)
                                    $scope.formInputs.push(newInput)
                                } else if ((input.fieldType == 2 && input.isReadOnly) || input.fieldType == 7) return // add && input.relatedMatch
                                // boolean case ( toggle )
                                else if (input.fieldType == 4 || input.fieldType == 11) {
                                    let existedInput = $scope.formInputs.filter(item => item.fieldName == input.relatedMatch || item.fieldName == input.fieldType)[0]
                                    if (input.fieldType == 4 && !input.relatedMatch) { // T
                                        input.trueLabel = input.nameAr
                                        existedInput ? existedInput = { existedInput, ...input, nameAr: existedInput.nameAr } : $scope.formInputs.push({ ...input, nameAr: '' })
                                    } else if (input.fieldType == 4 && input.relatedMatch) {
                                        existedInput ? existedInput.falseLabel = input.nameAr : $scope.formInputs.push({ falseLabel: input.nameAr, fieldName: input.relatedMatch })
                                    } else if (input.fieldType == 11) {
                                        existedInput ? existedInput.nameAr = input.nameAr : $scope.formInputs.push({ nameAr: input.nameAr, fieldName: input.relatedMatch })
                                    }
                                }
                                else {
                                    $scope.formInputs.push(input)
                                }
                            })
                        }

                        //dynamic grid settings
                        const distinct = (value, index, self) => {
                            return self.indexOf(value) === index;
                        }
                        
                        var GridsParents = response.data.gridDetails.map(function (a) { return a.detailFieldName; }).filter(distinct);
                        angular.forEach(GridsParents, function (val, key) {
                            var obj = {};
                            obj['Title'] = $.grep(response.data.gridDetails, function (b) {
                                return b.detailFieldName === val;
                            })[0].detailNameAr;
                            obj['Headers'] = Array.prototype.filter.call(response.data.gridDetails, function (b) {
                                if (b.detailFieldName === val) { return b }
                            }).map(function (a) { return a.nameAr; });
                            obj['Rows'] = $scope.RequestModel[val].length;
                            obj['Values'] = $scope.RequestModel[val];
                            $scope.RequestModel.GridsList.push(obj);
                        });

                        $scope.imagesList = [];
                        if (response.data?.openPdf !== null && response.data?.openPdf !== undefined) {
                            $scope.previewData = globalService.LoadPDFWithAnnotation(response.data.openPdf.attachmentImage, null, false, "pdf-container"); 
                        }
                    } catch (e) {
                        //  debugger;
                    }

                    $timeout(function () {
                        obj.thereIsData = true;
                        obj.noData = false;
                        obj.showLoad = false;
                        ngProgress.complete();
                    }, 800);
                }
                else {
                    obj.thereIsData = false;
                    obj.showLoad = false;
                    obj.noData = true;
                    ngProgress.complete();
                }
            });
        };

        $scope.templateUrl = function (obj) {
            $scope.selectedRequestType = obj.requestType;
            var paths = getTemplatesPaths();
            return $scope.isDynamicForm ? paths[1] : paths[3];
        };

        function getTemplatesPaths() {
            var input = '';
            var splitChar = ',';
            if ($scope.RequestTypes !== []) {
                var obj = $.grep($scope.RequestTypes, function (e) { return e.id === $scope.selectedRequestType; });
                if (obj !== null && obj !== undefined && obj !== []) {
                    if (obj.length > 0) {
                        input = obj[0].htmlTempleteUrl;
                    }
                }
            }
            return input.split(',');
        }

