        $scope.getCity = function () {
            var cityFromSession = session.getPropertyLocalStorage('CurrentMember.CityName', false)
            if (cityFromSession === null || cityFromSession === '' || cityFromSession === undefined) {
                AllRequestSvc.GetMemberCity().then(function (response) {
                    if (response.success) {
                        $scope.RequestModel.CityName = response.data;
                    }
                });
            } else {
                $scope.RequestModel.CityName = cityFromSession;
            }
        }

        $scope.CheckActivityExcepted = function () {
            $scope.loadCRActivity = true;
            AllRequestSvc.CheckActivityExcepted().then(function (response) {
                if (response.success) {
                    if (response.data !== null) {
                        if (response.data.activityCode !== 0) {
                            $scope.RequestModel.ActivityDisabled = true;
                            $scope.RequestModel.ActivityAllowed = true;
                            $scope.RequestModel.ActivityId = response.data.activityCode;
                            $scope.RequestModel.Activity = response.data.activityName;
                        } else {
                            $scope.RequestModel.ActivityDisabled = false;
                            $scope.RequestModel.ActivityAllowed = true;
                            $scope.RequestModel.Activity = response.data.activityName;
                        }
                    } else {
                        $scope.RequestModel.ActivityDisabled = false;
                        $scope.RequestModel.ActivityAllowed = true;
                    }
                    $scope.loadCRActivity = false;
                } else {
                    swal({
                        title: 'لا يمكن تنفيذ العملية', type: "error",
                        text: response.data,
                        showCloseButton: true,
                        confirmButtonText: ' موافق!'
                    });
                    $scope.loadCRActivity = false;
                    $scope.gotoStep($scope.page.currentStep - 1, null, null)
                }
            });
        }

