        $scope.handleRadioClick = function (radius) {
            $scope.RequestModel.selectedRadius = radius;
            if (radius.id === 1 || radius.id === undefined) { // مكتب
                $timeout(function () {
                    $scope.RequestModel.IsSir = false;
                    $scope.RequestModel.IsOffice = true;
                    $scope.officeChange(1);
                });
            }
            else if (radius.id === 2) { // السيد
                $timeout(function () {
                    $scope.RequestModel.IsSir = true;
                    $scope.RequestModel.IsOffice = false;
                    $scope.sirChange(2);
                });
            }
        };
        $scope.officeChange = function (val) {
            if (val === 1) {
                $scope.RequestModel.SirName = null;
                $scope.RequestModel.SirIdNumber = null;
            }
        };
        $scope.sirChange = function (val) {
            if (val === 2) {
                $scope.RequestModel.OfficeName = null;
                $scope.RequestModel.OfficeServiceNumber = null;
            }
        };
        $scope.changeBenefitInfo = function (benefitBool) {
            $scope.benefitBool.IsOneBenefit = benefitBool.IsOneBenefit === undefined ? false : benefitBool.IsOneBenefit;
            $scope.benefitBool.IsManyBenefit = benefitBool.IsManyBenefit === undefined ? false : benefitBool.IsManyBenefit;

            if (benefitBool.IsOneBenefit === true) {
                $scope.benefitBool.IsManyBenefit = false;
                $scope.oneBenefitChange(1);
            } else {
                $scope.benefitBool.IsManyBenefit = true;
                $scope.sirChange(2);
            }
        };
        $scope.oneBenefitChange = function (val) {
            if (val === 1) {
                $scope.AddRequestAuthorizedModel.authorizedType = "1";
                $scope.AddRequestAuthorizedModel.authorizedTypeName = $scope.AddRequestAuthorizedModel.officeName;
                $scope.AddRequestAuthorizedModel.authorizedTypeNumber = $scope.AddRequestAuthorizedModel.serviceNumber;
                $scope.AddRequestAuthorizedModel.officeName = undefined;
                $scope.AddRequestAuthorizedModel.serviceNumber = undefined;
            }
        };

        /////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

        $scope.CustomGotoStep = function (step, id) {
            if ($scope.page.currentStep == 1) { // to reset the dynamic inputs and request model if there are any cached ones 
                $scope.formInputs = []
                initRequestModel()
            }
            $scope.RequestModel.requestType = id;
            if ($scope.RequestModel.requestType === 28) {
                $scope.contestTab = 1;
            }
            $scope.gotoStep(step, null);
        };

        // Set Request Model Main Data Settings By Request Type
        $scope.setRequestModelByRequestType = function () {
            angular.forEach($scope.RequestTypes2, function (val, key) {
                if ($scope.RequestModel.requestType === val.id) {

                    $scope.RequestModel.sendCode = val.sendCode;
                    $scope.RequestModel.isAutomatic = val.isAutomatic;
                    $scope.RequestModel.requestTypeName = val.name;
                    $scope.RequestModel.MaxSelectedOptions = val.maxSelectedOptions;
                    $scope.RequestModel.AddAttachment = val.addAttachment;
                    $scope.RequestModel.IsAttachment = val.isAttachment;
                    $scope.RequestModel.MainAttachmentsNumber = val.attachmentsNumber;
                    $scope.RequestModel.AttachmentsNumber = val.attachmentsNumber;
                    $scope.RequestModel.ExpireDateInterval = val.expireDateInterval;
                    $scope.RequestModel.ShowPrizeAmount = val.showPrizeAmount;
                    $scope.RequestModel.ShowObligation = val.showObligation;
                    $scope.RequestModel.CanSubmit = val.canSubmit;
                    $scope.RequestModel.AddResponsibleSignature = val.addResponsibleSignature;
                    $scope.RequestModel.MaxRequestsCountPerYear = val.maxRequestsCountPerYear;
                    $scope.RequestModel.GridDetails = val.gridDetails;
                    $scope.RequestModel.MaxBeforeCompetitionStart = val.maxBeforeCompetitionStart;
                    $scope.currentRequestTypeName = val.name;
                    sessionStorage.setItem('OriginalGridDetails', JSON.stringify(val.gridDetails));

                    if (val.isDynamicForm && !$scope.formInputs?.length) {
                        $scope.attachmentsInput = {
                            addAttachment: val.addAttachment,
                            attachmentExtentions: val.attachmentExtentions,
                            attachmentList: val.attachmentList ? JSON.parse(val.attachmentList) : [],
                            attachmentSize: val.attachmentSize,
                            attachmentsNumber: val.attachmentsNumber
                        }
                        val.inputsDetails.forEach(input => {
                            // select case ( single & multi)
                            if (input.fieldType == 6 || input.fieldType == 8) {
                                if (input.isReadOnly) return
                                let newInput = { ...input }
                                if (input.options) newInput.options = JSON.parse(input.options)
                                if (newInput.isMultipleChoice) $scope.RequestModel[input.fieldName] = "[]" // default value
                                $scope.formInputs.push(newInput)
                            } else if ((input.fieldType == 2 && input.isReadOnly) || input.fieldType == 7) return // add && input.relatedMatch
                            // boolean case ( toggle )
                            else if (input.fieldType == 4 || input.fieldType == 11) {
                                let existedInputIndex = $scope.formInputs.findIndex(item => item.fieldName == input.relatedMatch || item.fieldName == input.fieldName)
                                if (input.fieldType == 4 && !input.relatedMatch) { // T
                                    input.trueLabel = input.nameAr
                                    existedInputIndex > -1 ? $scope.formInputs[existedInputIndex] = { ...$scope.formInputs[existedInputIndex], ...input, nameAr: $scope.formInputs[existedInputIndex].nameAr } : $scope.formInputs.push({ ...input, nameAr: '' })
                                    $scope.RequestModel[input.fieldName] = false // default value
                                } else if (input.fieldType == 4 && input.relatedMatch) { // F
                                    existedInputIndex > -1 ? $scope.formInputs[existedInputIndex].falseLabel = input.nameAr : $scope.formInputs.push({ falseLabel: input.nameAr, fieldName: input.relatedMatch })
                                    $scope.RequestModel[input.fieldName] = true // default value
                                } else if (input.fieldType == 11) {
                                    existedInputIndex > -1 ? $scope.formInputs[existedInputIndex].nameAr = input.nameAr : $scope.formInputs.push({ nameAr: input.nameAr, fieldName: input.relatedMatch, order: input.order })
                                }
                            }
                            else {
                                $scope.formInputs.push(input)
                            }
                        })
                    }
                    // OriginalGridDetails = angular.copy(val.gridDetails);
                    //تحديد رسم grids  الخاصة بالطلب 
                    //ParentName  هو اسم الgrid  التي ينتمي ليها السطر بجدول الجريد
                    //Title  اسم الجريد بقاعدة البيانات 
                    // Headers mean Table Headers
                    //Grid Mean Array of row Columns for each parent grid separately
                    const distinct = (value, index, self) => {
                        return self.indexOf(value) === index;
                    }
                    var arr = [];
                    var GridsParents = $scope.RequestModel.GridDetails.map(function (a) { return a.detailFieldName; }).filter(distinct);

                    angular.forEach(GridsParents, function (val, key) {
                        var obj = {};
                        obj['ParentName'] = val;

                        obj['Title'] = $.grep($scope.RequestModel.GridDetails, function (b) {
                            return b.detailFieldName === val;
                        })[0].detailNameAr;

                        obj['Headers'] = Array.prototype.filter.call($scope.RequestModel.GridDetails, function (b) {
                            if (b.detailFieldName === val) { return b }
                        }).map(function (a) { return a.nameAr; });
                        obj['Grid'] = [{ SmallGrid: [] }];
                        obj['Grid'][0].SmallGrid = $.grep($scope.RequestModel.GridDetails, function (b) {
                            return b.detailFieldName === val;
                        });
                        arr.push(obj);
                    });
                    $scope.GridsArray = arr;
                }
            });
        };

        //Wizard Second Step
        $scope.moveToStep2 = function (newStep, grid) {
            if (grid !== null && grid !== undefined) {
                $scope.GridsArray = grid;
            }
            if ($scope.page.currentStep > newStep) {
                $scope.page.wizardData = true;
                $scope.page.showWizardLoad = false;
                $scope.page.currentStep = newStep;
            }

            if ($scope.page.currentStep < newStep) {
                if ($scope.RequestModel.CanSubmit === false) {
                    $timeout(function () {
                        toaster.clear();
                        toaster.error('لا يمكن تقديم اكثر من  ' + $scope.RequestModel.MaxRequestsCountPerYear + ' ' + 'طلب فى السنة');
                        $scope.contestTab = null;
                    }, 0);
                    return false;
                }

                $scope.page.wizardData = false;
                $scope.page.showWizardLoad = true;
                if ($scope.page.wizardData === true) {
                    $scope.page.currentStep = newStep;
                }

                AllRequestSvc.CheckWalletBalanceForRequest({ RequestType: $scope.RequestModel.requestType, MemberExpireDate: session.getPropertyLocalStorage('CurrentMember.ExpiredDate', false) }).then(function (response) {
                    if (response.success) {
                        if (response.data === null) {
                            $timeout(function () {
                                toaster.clear();
                                toaster.pop('warning', response.message);
                            }, 0);
                            $scope.page.wizardData = true;
                            $scope.page.showWizardLoad = false;
                            $scope.page.currentStep = 1;
                            return false;
                        } else {
                            if (response.data.valid) {
                                $scope.page.wizardData = true;
                                $scope.page.showWizardLoad = false;
                                $rootScope.Balance = response.data.balance;
                                $scope.page.currentStep = newStep;
                            } else {
                                $timeout(function () {
                                    toaster.clear();
                                    toaster.pop('warning', response.message);
                                }, 0);
                                window.location.href = "/#/NewRequest";
                                $scope.page.wizardData = true;
                                $scope.page.showWizardLoad = false;
                                $scope.page.currentStep = 1;
                                return false;
                            }
                        }
                    }
                    else {
                        if (!response.success) {
                            $timeout(function () { toaster.clear(); toaster.pop('error', response.data); }, 0);
                            $scope.page.wizardData = true;
                            $scope.page.showWizardLoad = false;
                            $scope.page.TypesThereIsData = true;
                            $scope.page.currentStep = 1;
                            window.location.href = "/#/NewRequest";
                            return false;
                        }

                        $timeout(function () {
                            toaster.clear(); toaster.pop('error', response.data);
                        }, 0);
                        $scope.page.currentStep = 1;
                        $scope.page.wizardData = true;
                        $scope.page.showWizardLoad = false;
                        return false;
                    }
                });

                if (!$scope.notLoadGetDrops) {
                    $scope.GetDrops();
                }

                if (newStep > $scope.steps.length || $scope.RequestModel.requestType === '' || $scope.RequestModel.requestType === undefined || $scope.RequestModel.requestType === null) {
                    $timeout(function () {
                        toaster.clear(); toaster.pop('error', appConst.selectRequestType);
                    }, 0);
                    return false;
                }
                //Fetch member data for update personal data request
                if (newStep === 2 && $scope.RequestModel.requestType === 1) {
                    $scope.UpdateRequestStep1 = true;
                    //getContactMemberData();
                }

                return true;
            }
        };

        //Wizard Third Step
        $scope.moveToStep3 = function (form, newStep, grid) {
            var errors = [];
            if (grid !== null && grid !== undefined) {
                $scope.GridsArray = grid;
            }
            $scope.isFormSubmitted = true;
            event.preventDefault();
            if (!form.$valid) {
                $scope.page.currentStep = 2;
                if ($scope.RequestModel.requestType === 57 || $scope.RequestModel.requestType === 58) {
                    var Forms = [];
                    for (var i in form) {
                        if (form.hasOwnProperty(i)) {
                            if (i.indexOf('Form') > -1 && i !== '$$parentForm') {
                                Forms.push(form[i]);
                            }
                        }
                    }
                    // Validation for generic grids froms
                    angular.forEach(Forms, function (form, key) {
                        $scope.RequestModel.validationErrors[form.$name] = [];
                        if (!form.$valid) {
                            for (var key in form.$error) {
                                for (var index = 0; index < form.$error[key].length; index++) {
                                    var errorObj = {};
                                    var fields = form.$error[key][index].$name.split('_');
                                    errorObj.name = form.$error[key][index].$name;
                                    errorObj.parent = parseInt(fields[1]);
                                    errorObj.row = parseInt(fields[1]);
                                    errorObj.column = parseInt(fields[2]);
                                    errorObj.errors = [];
                                    var column = fields[0];

                                    var item = $filter('filter')($scope.RequestModel.GridDetails, { fieldName: column });
                                    if (key === 'required') {
                                        errorObj.errors.push(item[0].requiredMessage);
                                    }
                                    else if (key === 'minlength' || key === 'minlength') {
                                        errorObj.errors.push(item[0].lenghtMessage);
                                    }
                                    else if (key === 'pattern') {
                                        errorObj.errors.push(item[0].patternMessage);
                                    }

                                    if (item.length !== 0) {
                                        //  errorObj.errors.push(item[0].requiredMessage);
                                        $scope.RequestModel.validationErrors[form.$name].push(errorObj);
                                    }
                                }
                            }
                            return false;
                        }
                    })
                }
                if (form.benefitForm !== undefined) {
                    if (!form.benefitForm.$valid) {
                        $scope.RequestModel.validationErrors['benefitForm'] = [];
                        for (var key in form.benefitForm.$error) {
                            for (var index = 0; index < form.benefitForm.$error[key].length; index++) {
                                var errorObj = {};
                                var fields = form.benefitForm.$error[key][index].$name.split('_');
                                errorObj.name = form.benefitForm.$error[key][index].$name;
                                errorObj.row = parseInt(fields[1]);
                                errorObj.errors = [];
                                var column = fields[0];
                                var item = $filter('filter')($scope.RequestModel.GridDetails, { fieldName: column });
                                if (key === 'required') {
                                    errorObj.errors.push(item[0].requiredMessage);
                                }
                                else if (key === 'minlength' || key === 'minlength') {
                                    errorObj.errors.push(item[0].lenghtMessage);
                                }
                                else if (key === 'pattern') {
                                    errorObj.errors.push(item[0].patternMessage);
                                }
                                $scope.RequestModel.validationErrors['benefitForm'].push(errorObj);
                            }
                        }
                    }
                }
                if ($scope.RequestModel.requestType === 52) {
                    angular.forEach($scope.AttachmentTypes, function (v, key) {
                        if (v.Id === 3) {
                            if ($scope.RequestModel.MemberRelationTypeId === 1 || $scope.RequestModel.MemberRelationTypeId === 2 || $scope.RequestModel.OwnerExist) {
                                v.IsRequired = false;
                                v.Hide = true;
                            } else {
                                v.IsRequired = true;
                                v.Hide = false;
                            }
                        }
                    });
                }

                return false;
            }

            //check attachments 
            checkAttachments().then(function (response) {
                toaster.clear();
                if (!response.Success && response.Message) {
                    $timeout(function () {
                        toaster.clear();
                        toaster.pop('error', response.Message);
                    }, 0);
                    return false;
                }
            });

            // اضافة المرفق فى الطلبات
            if ($scope.RequestModel.AddAttachment !== null) {
                var requiredAttachments = $scope?.attachmentsInput?.attachmentList?.filter(item => item.IsRequired)?.length
                if (newStep === 3 && $scope.RequestModel.AddAttachment === true && $scope.RequestModel.AttachmentsNumber > 0) {
                    if ($scope.RequestModel.AddFollowers && $scope.Grid.length >= 1) {
                        $scope.RequestModel.AttachmentsNumber = $scope.RequestModel.MainAttachmentsNumber + $scope.Grid.length;
                    }
                    var attachsCount = requiredAttachments > 0 ? $scope.RequestModel.AttachmentsNumber - requiredAttachments : $scope.RequestModel.AttachmentsNumber;
                    if ($scope.RequestModel.AttachmentsNumber !== null && attachsCount > $scope.SelectedFileForUpload.length) {
                        $timeout(function () {
                            toaster.clear();
                            toaster.pop('error', 'فضلا يجب إضافة علي الاقل  ' + $scope.RequestModel.AttachmentsNumber + ' ' + 'مرفق');
                        }, 0);
                        return false;
                    } else if ($scope.SelectedFileForUpload.length === 0) {
                        $timeout(function () {
                            toaster.clear();
                            toaster.pop('error', appConst.addAttachment);
                        }, 0);
                        return false;
                    }
                }
            }

            if ($scope.RequestModel.requestType !== 58) {
                //check form validation for every request form
                $scope.RequestModel.Followers = ($scope.RequestModel.AddFollowers) ? $scope.Grid : [];

                errors = requestsValidationSvc.validateRequest($scope.RequestModel, $scope.page, $scope.LKUP_RequestsFormsReasons, $scope.RequestModel.Benefits, $scope.GridsArray);
                if (errors.length > 0) {
                    $timeout(function () {
                        toaster.clear();
                        toaster.error(errors[0]);
                    }, 0);
                    return false;
                }
            }
            if ($scope.RequestModel.requestType === 11) {
                var isForeign = new RegExp(/^2/).test(String($scope.RequestModel.IdNumber))
                var nationalityMatchIdNumber = isForeign && $scope.RequestModel.NationalityId > 2 || !isForeign && $scope.RequestModel.NationalityId <= 2
                if (!nationalityMatchIdNumber) {
                    $timeout(function () {
                        toaster.clear();
                        toaster.error('الجنسية المختارة لا تتناسب مع الهوية المدخلة');
                    }, 0);
                    return false;
                }
            }

            if ($scope.RequestModel.requestType === 2) {
                if ($scope.RequestModel.Language != 1) {
                    if ($scope.RequestModel.CompanyNameEn === null || $scope.RequestModel.CompanyNameEn === '' || $scope.RequestModel.CompanyNameEn === '---') {
                        $timeout(function () {
                            toaster.clear();
                            toaster.error('تأكد من إسم المنشأة بالإنجليزية بشكل صحيح لدي الغرفة');
                        }, 0);
                        return false;
                    }
                }
            }


            //assign Grid
            angular.forEach($scope.Grid, function (val, key) {
                if (val.IsDueDate === true && (val.DueDate === '' || val.DueDate === undefined)) {
                    val.IsDueDate === false;
                    val.IsDueText === true;
                    val.DueDate = val.DueDateSettings.defaultValue;
                }
            });

            $scope.RequestModel.Instruments = $scope.Grid;
            $scope.RequestModel.Followers = ($scope.RequestModel.AddFollowers) ? $scope.Grid : [];
            $scope.RequestModel.InDetailGridSalary = $scope.Grid;

            if ($scope.RequestModel.requestType === 57 || $scope.RequestModel.requestType === 58) {
                angular.forEach($scope.GridsArray, function (val, key) {
                    var Objects = [];
                    angular.forEach(val.Grid, function (v, k) {
                        var obj = {};
                        angular.forEach(v.SmallGrid, function (vv, kk) {
                            var fieldName = vv.fieldName;
                            var fieldValue = vv[vv.fieldName];
                            obj[fieldName] = fieldValue;
                        });
                        Objects.push(obj);
                    });
                    $parse(val.ParentName).assign($scope.RequestModel, Objects);
                });
                if ($scope.RequestModel.requestType === 58) {
                    errors = requestsValidationSvc.validateRequest($scope.RequestModel, $scope.page, $scope.LKUP_RequestsFormsReasons, $scope.RequestModel.Benefits, $scope.GridsArray);
                    if (errors.length > 0) {
                        $timeout(function () {
                            toaster.clear();
                            toaster.error(errors[0]);
                        }, 0);
                        return false;
                    }
                }
            }

            /////////////////// Assign drop down select string value

            if ($scope.RequestModel.requestType === 2) {
                if ($scope.RequestModel.EstName) {
                    $scope.RequestModel.MC_ExporterName = $scope.RequestModel.Language == 1 ? $scope.RequestModel.EstName : $scope.RequestModel.CompanyNameEn;
                }
                if ($scope.RequestModel.EstPhone) {
                    $scope.RequestModel.MC_ExporterPhone = $scope.RequestModel.EstPhone;
                }
                angular.forEach($scope.LKUP_Countries, function (val, key) {
                    if ($scope.RequestModel.MC_ImporterCountryId === val.id) {
                        $scope.RequestModel.MC_ImporterCountry = val.nameAr;
                    }
                });

                angular.forEach($scope.LKUP_ForeignCurrencies, function (val, key) {
                    if ($scope.RequestModel.MC_ForeignCurrencyId === val.id) {
                        $scope.RequestModel.MC_ForeignCurrency = val.nameAr;
                    }
                });
            }
            if ($scope.RequestModel.requestType === 4) {
                angular.forEach($scope.VisaTypes, function (val, key) {
                    if ($scope.RequestModel.VisaTypeId === val.id) {
                        $scope.RequestModel.VisaTypeName = val.nameAr;
                    }
                });
            }
            if ($scope.RequestModel.requestType === 32 || $scope.RequestModel.requestType === 11) {
                angular.forEach($scope.Nationalities, function (val, key) {
                    if ($scope.RequestModel.NationalityId === val.id) {
                        $scope.RequestModel.NationalityName = val.nameAr;
                    }
                });
            }
            if ($scope.RequestModel.requestType === 38) {
                sharedService.DateDiffMonth($scope.RequestModel.RentStartDate, $scope.RequestModel.RentPeriod).then(function (res) {
                    if (res.success) {
                        $scope.RequestModel.RentEndDate = res.data;
                    }
                });
            }
            if ($scope.RequestModel.requestType === 46) {
                angular.forEach($scope.ExcludedActvities, function (val, key) {
                    if ($scope.RequestModel.ActivityId === val.activityCode) {
                        $scope.RequestModel.Activity = val.activityName;
                    }
                });
            }
            if ($scope.RequestModel.requestType === 52) {
                angular.forEach($scope.MemberRelationType, function (val, key) {
                    if ($scope.RequestModel.MemberRelationTypeId === val.id) {
                        $scope.RequestModel.MemberRelationType = val.nameAr;
                    }
                });
                angular.forEach($scope.Qualifications, function (val, key) {
                    if ($scope.RequestModel.QualificationTypeId === val.id) {
                        $scope.RequestModel.QualificationType = val.nameAr;
                    }
                });
                angular.forEach($scope.SectoralCouncils, function (val, key) {
                    if ($scope.RequestModel.SectoralCouncilId === val.id) {
                        $scope.RequestModel.SectoralCouncil = val.nameAr;
                    }
                });
            }
            $scope.page.currentStep = newStep;
            return true;
        };



        //Swap Between Steps
        $scope.gotoStep = function (newStep, form, event, grid) {
            $scope.page.wizardData = true;
            $scope.page.showSmsTime = false;

            $('.calendars-popup').hide();
            if (session.getPropertyLocalStorage("CurrentMember.SettingExpired", false) !== false) {
                swal({
                    title: appConst.memberStatusExpiredForRequests,
                    type: "warning",
                    text: 'يجب تحديث عضويتك لدى وزارة التجارة',
                    showCloseButton: true,
                    showCancelButton: true,
                    cancelButtonText: 'التحديث',
                    confirmButtonText: 'تم التحديث',
                },
                    function (isConfirm) {
                        if (isConfirm) {
                            //Update Member Data 
                            blockUI.start();
                            toaster.pop('wait', 'جاري التحديث ...', null, 15000);
                            UsersSvc.ReplaceMember({ NewMemberId: $rootScope.userInfo.globalSessionValues.CurrentMember.MemberId, RelatedType: $rootScope.userInfo.globalSessionValues.CurrentMember.RelatedType }).then(function (response) {
                                toaster.clear();
                                if (response.success) {
                                    //Update Current Member Data in Local Storage
                                    session.updateLocalStorage('CurrentMember', globalService.capitalizeObject(response.data), false);
                                    $rootScope.userInfo.globalSessionValues.CurrentMember = globalService.capitalizeObject(response.data);
                                    toaster.pop('success', "تم التحديث بنجاح  ", null, 2000);
                                    blockUI.stop();
                                    $timeout(function () {
                                        $route.reload();
                                    }, 0);

                                } else {
                                    toaster.pop('error', response.message);
                                }
                                blockUI.stop();
                            });
                        }
                        else {
                            //Redirect to Commerce Authority Link

                            window.open("https://e2.business.sa/", "_blank");
                        }
                    });
                return false;
            }
            if (session.getPropertyLocalStorage("CurrentMember.DisableRatification", false) === true) {
                swal({
                    title: 'تنبيه', type: "warning",
                    text: appConst.RatificationDisabled,
                    showCloseButton: true,
                    confirmButtonText: ' موافق!'
                });
                return false;
            }

            //if ($scope.page.currentStep === 1 && $scope.RequestModel.requestType === 1 && $scope.UpdateRequestStep1 === true) {
            //    $scope.UpdateRequestStep1 = true;
            //    $scope.UpdateRequestStep2 = false;
            //    var filteredList = $filter("filter")($scope.RequestModel.UpdateRequestFields, { Checked: true });
            //    if (filteredList.length === 0) {
            //        toaster.error('قم بتحديد البيانات المراد تحديثها !');
            //        return false;
            //    }
            //    $scope.UpdateRequestStep2 = true;
            //}


            //Assign Request Type Settings To binding model
            $scope.setRequestModelByRequestType();

            if ($scope.RequestModel.requestType === '' || $scope.RequestModel.requestType === undefined || $scope.RequestModel.requestType === null) {
                $timeout(function () {
                    toaster.clear();
                    toaster.error(appConst.selectRequestType);
                }, 0);
                $scope.page.currentStep = newStep;
                return false;
            }
            //عند استخدام زر السابق للرجوع للخطوة الأولى
            if (newStep < $scope.page.currentStep && newStep === 1) {
                $scope.SelectedFileForUpload = [];
                $scope.imagesList = [];
                $scope.contestTab = null;
                $scope.RequestModel.Benefits = [{ benefitName: '', benefitId: '' }];
                if ($scope.LKUP_RequestsFormsReasons.length > 0) {
                    angular.forEach($scope.LKUP_RequestsFormsReasons, function (val, key) {
                        val.isChecked = false;
                    });
                }
            }

            // For request No. 5 and 36 fetching summernote text
            $scope.previewData = null;
            if (!$rootScope.chamberSettings.enableFroalaEditor) {
                // For request No. 5 and 36 fetching summernote text
                if (newStep < $scope.page.currentStep && newStep === 2 && ($scope.RequestModel.requestType === 36 || $scope.RequestModel.requestType === 5)) {
                    var content = $("<div />").html($($scope.RequestModel.requestType === 5 ? "#summernote" : "#summernote2").code());
                    content[0].innerHTML = $scope.RequestModel.RequestText;
                }
                if (newStep === 3 && ($scope.RequestModel.requestType === 36 || $scope.RequestModel.requestType === 5)) {
                    var _content = $("<div />").html($($scope.RequestModel.requestType === 5 ? "#summernote" : "#summernote2").code());
                    $scope.HtmlBodyContent = _content[0].innerHTML;
                    $scope.RequestModel.RequestText = $scope.HtmlBodyContent.replace("AL-Mohanad", "Arial");
                }
            }


            if (newStep === 1) {
                $scope.page.currentStep = newStep;
                $scope.page.TypesThereIsData = true;
                $scope.page.TypesShowLoad = false;
                window.location.href = "/#/NewRequest";
            }
            if (newStep === 2) {
                setFroalaOptions();
                var response = $scope.moveToStep2(newStep, grid);
                if (!response) {
                    return false;
                }
            }
            if (newStep === 3) {
                if ($scope.RequestModel.requestType === 5 || $scope.RequestModel.requestType === 36) {
                    if ($scope.RequestModel.RequestText === '' || $scope.RequestModel.RequestText === null || $scope.RequestModel.RequestText === undefined ||
                        $scope.RequestModel.RequestText === '<p data-f-id="pbf" style="text-align: center; font-size: 14px; margin-top: 30px; opacity: 0.65; font-family: sans-serif;">Powered by <a href="https://www.froala.com/wysiwyg-editor?pb=1" title="Froala Editor">Froala Editor</a></p>') {
                        $timeout(function () {
                            toaster.clear();
                            toaster.pop('error', 'نص الطلب مطلوب.');
                        }, 0);
                        return false;
                    }

                    var errors = requestsValidationSvc.validateRequest($scope.RequestModel, $scope.page, $scope.LKUP_RequestsFormsReasons, $scope.RequestModel.Benefits, $scope.GridsArray);
                    if (errors.length > 0) {
                        $timeout(function () {
                            toaster.clear();
                            toaster.error(errors[0]);
                        }, 0);

                        return false;
                    }
                    if (form.$valid) {
                        $scope.previewRequest(null);
                    }
                }
                if ($scope.RequestModel.requestType === 56 && $scope.RequestModel.RequestTotalAmount > $rootScope.userInfo.globalSessionValues.CurrentMember.Balance) {
                    $timeout(function () {
                        toaster.clear();
                        toaster.pop('error', 'قيمة الطلب تتعدي الرصيد الحالى');
                    }, 0);
                    return false;
                }
                if ($scope.committeeNotValid && $scope.RequestModel.requestType === 52) {
                    $timeout(function () {
                        toaster.clear();
                        toaster.pop('error', $scope.committeeNotValidMsg);
                    }, 0);
                    return false;
                }
                response = $scope.moveToStep3(form, newStep, grid);
                if (!response) {
                    return false;
                }
            }
        };

        // * Including Html pages *//
        $scope.templateUrl = function () {
            $scope.page.thereIsData = false;
            $scope.page.showLoad = true;
            $scope.page.NoData = false;
            if ($scope.page.currentStep === 1) {
                $scope.page.thereIsData = true;
                $scope.page.showLoad = false;
                $scope.page.NoData = false;
                return "NgApp/" + "Request" + "/Views/" + "step1.html";
            }

            $rootScope.title = "طلب جديد - " + $scope.page.selectedRequestName;

            var htmlArr = getHtmlTemplates();
            if ($scope.page.currentStep === 2) {
                $scope.page.thereIsData = true;
                $scope.page.showLoad = false;
                $scope.page.NoData = false;
                return htmlArr[0];
            }
            if ($scope.page.currentStep === 3) {
                $scope.page.thereIsData = true;
                $scope.page.showLoad = false;
                $scope.page.NoData = false;
                return htmlArr[1];
            }
        };
        $scope.addStampAuto = function (position) {
            let pageIndex = $scope.pdf.active_canvas;
            let pageWidth = $scope.pdf.fabricObjects[pageIndex].width
            let pageHeight = $scope.pdf.fabricObjects[pageIndex].height
            let stampWidth = 360;
            let stampHeight = 209;
            let paddingBuffer = 100;
            let stamp;
            let left = paddingBuffer;
            let right = pageWidth - paddingBuffer - stampWidth;
            let centerHz = pageWidth / 2 - stampWidth / 2;
            let top = paddingBuffer;
            let centerVC = pageHeight / 2 - stampHeight / 2;
            let bottom = pageHeight - paddingBuffer - stampHeight / 2;
            switch (position) {
                case 'top-left':
                    stamp = {
                        top,
                        left,
                    }
                    break
                case 'top':
                    stamp = {
                        top,
                        left: centerHz,
                    }
                    break
                case 'top-right':
                    stamp = {
                        top,
                        left: right,
                    }
                    break
                case 'center-left':
                    stamp = {
                        top: centerVC,
                        left,
                    }
                    break
                case 'center':
                    stamp = {
                        top: centerVC,
                        left: centerHz,
                    }
                    break
                case 'center-right':
                    stamp = {
                        top: centerVC,
                        left: right,
                    }
                    break
                case 'bottom-left':
                    stamp = {
                        top: bottom,
                        left,
                    }
                    break
                case 'bottom':
                    stamp = {
                        top: bottom,
                        left: centerHz,
                    }
                    break
                case 'bottom-right':
                    stamp = {
                        top: bottom,
                        left: right,
                    }
                    break
            }
            $scope.addStampToPage(pageIndex, stamp)
        }
        $scope.addStampToPage = async function (pageNo, stamp) {
            if (!$rootScope.chamberSettings.allowUserAddStamp) return
            let addedObjectsCount = await $scope.pdf.getAddedObjectsCount()
            if ($scope.RequestModel.RequiredPagesToAttestation === addedObjectsCount)
                return $timeout(function () {
                    toaster.clear();
                    toaster.error({ title: 'عدد الأماكن المقترحة للاختام يجب ان تكون تساوي او أقل من عدد الصفحات المطلوب تصديقها للملف المُرفق' }, null, null, null, 10000);
                }, 0);
            $scope.pdf.addImageToCanvas(appConst.trialStamp, 300, pageNo, stamp);
        }
        function getHtmlTemplates() {
            var input = '';
            if ($scope.RequestTypes2 !== []) {
                var obj = $.grep($scope.RequestTypes2, function (e) { return e.id === $scope.RequestModel.requestType; });
                if (obj !== null) {
                    if (obj[0] !== null) {
                        $scope.page.selectedRequestName = obj[0].name;
                        input = obj[0].htmlTempleteUrl;
                    }
                }
            }
            return input.split(',');
        }

        //final step add request to DB
        $scope.save = function () {
            if (session.getPropertyLocalStorage('CurrentMember.MemberId', false) == null || session.getPropertyLocalStorage('CurrentMember.MemberId', false) != $scope.RequestModel.MemberId) {
                $timeout(function () {
                    toaster.clear();
                    toaster.error({ title: 'تم تغيير العضوية برجاء تحديث بيانات الطلب من جديد' }, null, null, null, 10000);
                }, 0);
                $(".modal-backdrop").css("display", "none");
                $location.path('/Landing');
                return false;
            }
            if ($scope.RequestModel.requestType === 52) {
                AllRequestSvc.CheckCommitteeRequest({ IdNumber: $scope.RequestModel.IdNumber, SectoralCouncilId: $scope.RequestModel.SectoralCouncilId, MemberExpireDate: session.getPropertyLocalStorage('CurrentMember.ExpiredDate', false) }).then(function (response) {
                    if (!response.success) {
                        $timeout(function () {
                            toaster.clear();
                            toaster.error({ title: response.message }, null, null, null, 1000);
                        }, 0);
                        return false;
                    }
                    $scope.saveRequestStart = true;
                    $scope.page.showSmsTime = false;
                    $scope.page.smsTimer = 0;
                    if ($scope.RequestModel.sendCode) {
                        $scope.requestSendCode === true;
                        $scope.saveRequestStart = false;
                        $scope.sendCode();
                    } else {
                        //Request Amount Confirmation
                        $scope.AlertAmountConfirmation();
                    }
                })
            }
            if ($scope.RequestModel.requestType !== 52) {
                $scope.saveRequestStart = true;
                $scope.page.showSmsTime = false;
                $scope.page.smsTimer = 0;
                if ($scope.RequestModel.sendCode) {
                    $scope.requestSendCode === true;
                    $scope.saveRequestStart = false;
                    $scope.sendCode();
                } else {
                    $scope.AlertAmountConfirmation();
                }
            }
        };




        /* Add Request */
        $scope.addRequest = function () {
            $scope.showSpinner = true;
            $scope.page.showSmsTime = false;
            $scope.page.smsTimer = 0;
            $scope.RequestModel.Reasons = $scope.getCheckedReasons(false);
            $scope.RequestModel.Instruments = $scope.Grid;
            $scope.RequestModel.Followers = ($scope.RequestModel.AddFollowers) ? $scope.Grid : [];

            angular.forEach($scope.RequestModel.Instruments, function (v, k) {
                Object.keys(v).forEach(function (key) {
                    if (key.includes('Settings')) {
                        delete v[key];
                    }
                });
            });

            if ($scope.RequestModel === null || $scope.RequestModel === {} || $scope.RequestModel === undefined) {
                $timeout(function () {
                    toaster.clear();
                    toaster.error({ title: 'نموذج بيانات الطلب غير متوفر' }, null, null, null, 10000);
                }, 0);
                $scope.sms.codeSent = false;
                $(".modal-backdrop").css("display", "none");
                return false;
            }
            if ($scope.RequestModel.requestType == 56 && $scope.selectedStampWay > 0) {
                let SuggestedStamps = []
                $scope.pdf.fabricObjects.forEach((page, index) => {
                    let pageStamps = {
                        page: index,
                        height: page.height,
                        width: page.width,
                        stamps: []
                    }
                    page._objects.forEach(stamp => {
                        let stampData = {
                            top: stamp.top,
                            left: stamp.left,
                            width: stamp.width,
                            height: stamp.height,
                            scaleX: stamp.scaleX,
                            scaleY: stamp.scaleY,
                        }
                        pageStamps.stamps.push(stampData)
                    })
                    if (pageStamps.stamps.length) SuggestedStamps.push(pageStamps)
                })
                $scope.RequestModel.StampsLocations = JSON.stringify(SuggestedStamps);
            }
            var details = {
                RequestType: $scope.RequestModel.requestType,
                RequestData: $scope.RequestModel,
                FilesList: $scope.imagesList,
                IsAttachment: $scope.RequestModel.IsAttachment,
                MemberExpireDate: session.getPropertyLocalStorage('CurrentMember.ExpiredDate', false),
                CrNumber: session.getPropertyLocalStorage('CurrentMember.CrNumber', false),
                UnifiedNumber: session.getPropertyLocalStorage('CurrentMember.MM_UnifiedNumber', false),
                EstName: session.getPropertyLocalStorage('CurrentMember.EstName', false),
                EstNameEn: session.getPropertyLocalStorage('CurrentMember.EstNameEn', false),
                SMS: {
                    Code: $scope.sms.codeToMatch,
                    TrackId: $scope.sms.TrackId
                },
                CommitteeDetails: $scope.CommitteeDetails,
            };
            ngProgress.start();
            blockUI.start();
            AllRequestSvc.Add(details).then(function (response) {
                if (response === null) {
                    ngProgress.complete();
                    $scope.sms.codeSent = false;
                    blockUI.stop();
                    $timeout(function () {
                        toaster.clear();
                        toaster.error({ title: appConst.errorOccurred }, null, null, null, 10000);
                    }, 0);
                    $(".modal-backdrop").css("display", "none");
                    return false;
                }
                if (!response.success) {
                    ngProgress.complete();
                    blockUI.stop();
                    if (response.code === 18 && $scope.sms.codeSent === true) {
                        $timeout(function () {
                            toaster.clear();
                            toaster.error({ title: response.message }, null, null, null, 1000);
                        }, 0);
                        return false;
                    }
                    $scope.sms.codeSent = false;
                    if (response.code === 26) {
                        if (angular.isArray(response.data)) {
                            angular.forEach(response.data, function (val, key) {
                                response.message = '';
                                response.message += '(' + val.memberNames[0] + ' ' + val.errorMessage + ')' + '-';
                            });
                            $timeout(function () {
                                toaster.clear();
                                toaster.error({ title: response.message }, null, null, null, 10000);
                            }, 0);
                        } else {
                            $timeout(function () {
                                toaster.clear(); toaster.error({ title: response.data }, null, null, null, 10000);
                            }, 0);
                        }
                        return false;
                    }
                    else {
                        $timeout(function () {
                            toaster.clear(); toaster.error({ title: response.message }, null, null, null, 10000);
                        }, 200);
                        return true;
                    }

                }
                if (response.success && response.data.requestId !== null) {
                    ngProgress.complete();
                    blockUI.stop();
                    $(".modal-backdrop").css("display", "none");
                    $scope.sms.codeSent = false;
                    $timeout(function () {
                        toaster.clear(); toaster.success({ title: response.message }, null, null, null, 10000);
                    }, 0);
                    $timeout(function () { AlertSatisfaction(response); }, 200);
                }
                else {
                    $scope.sms.codeSent = false;
                    if (response.data !== null) {
                        //model validation result
                        if (response.data.length > 0) {
                            angular.forEach(response.data, function (val, key) {
                                response.message += errorMessage + '-';
                            });
                            ngProgress.complete();
                            blockUI.stop();
                            $timeout(function () {
                                toaster.clear(); toaster.error({ title: response.message }, null, null, null, 10000);
                            }, 0);
                            return false;
                        }
                    }
                    ngProgress.complete();
                    blockUI.stop();
                    $timeout(function () {
                        toaster.clear(); toaster.error({ title: response.message }, null, null, null, 10000);
                    }, 0);
                }
            });
        };

        $scope.AlertAmountConfirmation = function () {
            if ($scope.RequestModel.requestType == 4) {
                swal({
                    title: ' تأكيد إعتماد الطلب', type: "info",
                    text: 'في حالة إعتماد هذا الطلب لا يمكن إلغاؤه',
                    showCloseButton: true,
                    showCancelButton: true,
                    closeOnConfirm: true,
                    closeOnCancel: true,
                    confirmButtonText: 'إعتماد',
                    cancelButtonText: 'إلغاء'
                },
                    function (isConfirm) {
                        if (!isConfirm) {  
                            toaster.clear();
                            toaster.error({ title: "تم إلغاء العملية " }, null, null, null, 5000);
                            blockUI.stop();
                          //  $scope.saveRequestStart = false;
                            return;
                        }
                        $scope.proceedWithNextSteps();
                    });
                return;
            } else {
                $scope.proceedWithNextSteps();
            }
        }


        $scope.proceedWithNextSteps = function () {
            var details = {
                RequestType: $scope.RequestModel.requestType,
                RequestData: $scope.RequestModel,
                RequiredPagesToAttestation: $scope.RequestModel.RequiredPagesToAttestation,
                IsAttachment: $scope.RequestModel.requestType === 56 ? true : false,
                MemberExpireDate: session.getPropertyLocalStorage('CurrentMember.ExpiredDate', false),
                FilesList: $scope.imagesList,
                //Amount: $scope.RequestModel.requestType === 56 ? $scope.RequestModel.RequestTotalAmount : null,
                SMS: {
                    Code: $scope.sms.codeToMatch,
                    TrackId: $scope.sms.TrackId
                }
            };

            if (details.IsAttachment) {
                if (($rootScope.userInfo.globalSessionValues.CurrentMember.Balance - $rootScope.userInfo.globalSessionValues.ReservedBalance) < $scope.RequestModel.RequestTotalAmount) {
                    $timeout(function () {
                        toaster.clear(); toaster.error({ title: 'الرصيد غير كافي يرجي شحن المحفظة أولاً.' }, null, null, null, 1000);
                    }, 0);
                    return false;
                }
            }




            blockUI.start();
            AllRequestSvc.PreviewServiceAmount(details).then(function (response) {
                if (response.success) {
                    if (response.data.amount > 0) {
                        swal({
                            title: 'تأكيد اضافة الطلب', type: "info",
                            text: (response.data.amount > 0) ? 'سيتم خصم مبلغ   ' + response.data.amount + ' ريال من المحفظة بعد اعتماد الطلب  ' : '',
                            showCloseButton: true,
                            showCancelButton: true,
                            closeOnConfirm: true,
                            closeOnCancel: true,
                            confirmButtonText: 'موافق',
                            cancelButtonText: 'الغاء'
                        },
                            function (isConfirm) {
                                if (isConfirm) {
                                    blockUI.stop();
                                    $scope.addRequest();
                                } else {
                                    toaster.clear(); toaster.error({ title: "تم إلغاء العملية " }, null, null, null, 5000);
                                    blockUI.stop();
                                    window.location.href = "/#/AllRequests";
                                }
                            });
                    } else {
                        blockUI.stop();
                        $scope.addRequest();
                    }
                } else {
                    blockUI.stop();
                    $timeout(function () {
                        toaster.clear(); toaster.error({ title: response.message }, null, null, null, 1000);
                    }, 0);
                    return false;
                }
            });
        }

