        //send sms code to user to continue saving request
        $scope.sendCode = function () {
            $scope.sms.codeSent = false;
            $scope.sms.codeToMatch = '';
            blockUI.start();
            ngProgress.start();
            AllRequestSvc.SendRequestSMSCode($scope.RequestModel.requestType).then(function successCallback(response) {
                if (response.success) {
                    ngProgress.complete();
                    $scope.sms.codeSent = true;
                    smsTimer();
                    $scope.sms.TrackId = response.data;
                } else {
                    ngProgress.complete();
                    $scope.sms.codeSent = false;
                    $scope.sms.codeNumber = '';
                    $timeout(function () {
                        toaster.clear(); toaster.error(response.message);
                    }, 0);
                }
                blockUI.stop();
            }, function errorCallback(response) {
                $timeout(function () {
                    toaster.clear(); toaster.error(response.message);
                }, 0);
                if (response.execptionMessage) {
                    $timeout(function () {
                        toaster.clear(); toaster.error(response.execptionMessage);
                    }, 0);
                }
                ngProgress.complete();
                $scope.sms.codeSent = false;
                $scope.sms.codeNumber = '';
                blockUI.stop();
            });
        };

        /////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
        //Validate Attachments
        function checkAttachments() {
            var deferred = $q.defer();
            var FinalResponse = { Success: null, Message: null };
            if ($scope.RequestModel.AddAttachment !== null) {
                var requiredAttachments = $scope?.attachmentsInput?.attachmentList?.filter(item => item.IsRequired)?.length
                if ($scope.RequestModel.AddAttachment === true && $scope.RequestModel.AttachmentsNumber > 0) {
                    if ($scope.RequestModel.AddFollowers && $scope.Grid.length >= 1) {
                        $scope.RequestModel.AttachmentsNumber = $scope.RequestModel.MainAttachmentsNumber + $scope.Grid.length;
                    }
                    if (!requiredAttachments && $scope.RequestModel.AttachmentsNumber !== null && $scope.RequestModel.AttachmentsNumber - requiredAttachments > $scope.SelectedFileForUpload.length) {
                        toaster.clear();
                        FinalResponse = { Success: false, Message: 'فضلا يجب اضافة علي الاقل  ' + $scope.RequestModel.AttachmentsNumber + ' ' + 'مرفق' };
                    } else if (requiredAttachments && requiredAttachments > $scope.SelectedFileForUpload.length) {
                        toaster.clear();
                        FinalResponse = { Success: false, Message: 'فضلا يجب اضافة علي الاقل  ' + requiredAttachments + ' ' + 'مرفق' };
                    } else if ($scope.SelectedFileForUpload.length === 0) {
                        FinalResponse = { Success: false, Message: appConst.addAttachment };
                    } else {
                        FinalResponse = { Success: true, Message: null };
                    }
                } else {
                    FinalResponse = { Success: true, Message: null };
                }
            } else {
                FinalResponse = { Success: true, Message: null };
            }
            deferred.resolve(FinalResponse);
            return deferred.promise;
        }

        $scope.getNamingIcon = function (classificationName) {
            return classificationName.split(/\s/).reduce((response, word) => response += word.slice(0, 1), '')
        }

