        /* Print */
        $scope.GetForPrint = function (divName) {
            $scope.Date = new Date();
            var innerContents = document.getElementById(divName).innerHTML;
            var popupWinindow = window.open('', 'width=600,height=700,scrollbars=no,menubar=no,toolbar=no,location=no,status=no,titlebar=no');
            popupWinindow.document.open();
            popupWinindow.document.write('<html><head>  <link href="../Content/Theme/bower_components/bootstrap/dist/css/bootstrap.min.ar.css" rel="stylesheet"/><link href="https://maxcdn.bootstrapcdn.com/font-awesome/4.6.3/css/font-awesome.min.css" rel="stylesheet" type="text/css" /><link href="../Content/Theme/dist/css/components-rtl.css" rel="stylesheet" /> <link href="../Content/Theme/dist/css/sb-admin.ar.css" rel="stylesheet" />  <link href="../Content/Theme/dist/css/plugins-rtl.css" rel="stylesheet" /><link href="../Content/Custom.css" rel="stylesheet" /><link href="../Content/MaterialRTL.css" rel="stylesheet" /> <script src="../Scripts/jquery-1.11.2.min.js"></script> </head>');
            popupWinindow.document.write('<body  onload=" window.print();">' + innerContents + '</body></html>');
            popupWinindow.document.close();
        };
