        //طلب اجراء مسابقة
        $scope.gotoContest = function (newStep) {
            $scope.currentContest = newStep;
        };

        $scope.getStepTemplate = function () {
            for (var i = 0; i < $scope.contests.length; i++) {
                if ($scope.currentContest === $scope.contests[i].step) {
                    return $scope.contests[i].template;
                }
            }
        };

        $scope.setContestTabs = function (newTab, form, event) {
            $scope.DoneClass = "";
             $anchorScroll();
            if (newTab === 1) {
                $scope.DoneClass = "";
            }

            if (newTab === 3) {
                $scope.isFormSubmitted = true;
                event.preventDefault();
                if (!form.$valid) {
                    newTab === 2;
                    return false;
                }
            }
            else {
                $scope.DoneClass = "wizard-done-item";
            }

            if (newTab === 3) {
                var errors = requestsValidationSvc.validateRequest($scope.RequestModel, $scope.page, null, null, null);
                if (errors.length > 0) {
                    $timeout(function () { toaster.clear(); toaster.error(errors[0]); }, 0);
                    newTab === 2;
                    return false;
                }

                if ($scope.SelectedFileForUpload.length < 2) {
                    $timeout(function () {
                        toaster.clear(); toaster.error(' يجب ارفاق المرفقين المذكورين   .');
                    }, 0);

                    newTab === 2;
                    return false;
                }
                $scope.DoneClass = "wizard-done-item";
            }
            $scope.contestTab = newTab;
        };

        $scope.isSetr = function (tabNum) {
            return $scope.contestTab === tabNum;
        };


        $scope.setUpdateRequestSteps = function (newStep) {
            if (newStep === 2) {
                var errors = requestsValidationSvc.validateRequest($scope.RequestModel, $scope.page, $scope.LKUP_RequestsFormsReasons, $scope.RequestModel.Benefits, $scope.GridsArray);
                if (errors.length > 0) {
                    $scope.UpdateRequestStep1 = true;
                    $scope.UpdateRequestStep2 = false;
                    // $timeout(function () {
                    toaster.clear();
                    toaster.error(errors[0]);
                    // }, 0); 
                    return false;
                } else {
                    $scope.UpdateRequestStep2 = true;
                    $scope.UpdateRequestStep1 = false;
                }
            }

            if (newStep === 1) {
                $scope.UpdateRequestStep1 = true;
                $scope.UpdateRequestStep2 = false;
            }
        };


