        $scope.previewRequest = function (form) {
            if ($scope.RequestModel.RequestText === null || $scope.RequestModel.RequestText === '' || $scope.RequestModel.RequestText === undefined) {
                $timeout(function () {
                    toaster.clear(); toaster.pop('error', 'نص الطلب مطلوب.');
                }, 0);
                return false;
            }
            blockUI.start();
            ngProgress.start();

            var model = {
                RequestTypeId: $scope.RequestModel.requestType,
                SecondMemberId: $scope.RequestModel.SecondMemberId,
                SecondCRNumber: $scope.RequestModel.SecondCRNumber,
                RequestData: JSON.stringify({
                    "FirstMemberId": $scope.RequestModel.FirstMemberId, "FirstCRNumber": $scope.RequestModel.FirstCRNumber,
                    "FirstMemberName": $scope.RequestModel.FirstMemberName,
                    "SecondMemberId": $scope.RequestModel.SecondMemberId, "SecondCRNumber": $scope.RequestModel.SecondCRNumber,
                    "SecondMemberName": $scope.RequestModel.SecondMemberName, "RequestDirection": $scope.RequestModel.RequestDirection,
                    "RequestText": $scope.RequestModel.RequestText, "Notes": $scope.RequestModel.Notes
                })
            };
            AllRequestSvc.PreviewRequestDownload(model).then(function (response) {
                blockUI.stop();
                ngProgress.complete();

                if (response === null) {
                    $timeout(function () { toaster.clear(); toaster.error({ title: appConst.errorOccurred }, null, null, null, 10000); }, 0);
                    return false;
                }
                if (!response.success) {
                    $timeout(function () { toaster.clear(); toaster.error({ title: appConst.errorOccurred }, null, null, null, 10000); }, 0);
                    return false;
                }
                if (response.success) {
                    var file = globalService.base64ToBlob(response.data);
                    var fileURL = URL.createObjectURL(file);
                    $scope.previewData = globalService.LoadPDFWithAnnotation(response.data, null, false, $scope.RequestModel.requestType === 36 ? "ppdf-container" : "pdf-container", 2, "SLOW");
                }
                else {
                    $timeout(function () { toaster.clear(); toaster.error({ title: response.message }, null, null, null, 10000); }, 0);
                }
            });
        };

