        /////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
        //group requests by there classifications 
        $scope.groupBy = function (arr, attribute) {
            // First, reset the groups.
            $scope.groups = [];
            // Now, sort the collection of friend on the
            // grouping-property. This just makes it easier
            // to split the collection.
            sortOn(arr, attribute);
            // I determine which group we are currently in.
            var groupValue = "_INVALID_GROUP_VALUE_";
            // As we loop over each friend, add it to the
            // current group - we'll create a NEW group every
            // time we come across a new attribute value.
            for (var i = 0; i < arr.length; i++) {
                var item = arr[i];
                // Should we create a new group?
                if (item[attribute] !== groupValue) {
                    var group = {
                        label: item[attribute],
                        name: item.classificationName,
                        classifyIconName: '../../../Content/Theme/dist/img/' + item.classifyIconName,
                        classifyIcon: item.classifyIconName,
                        classifyOrder: item.classifyOrder,
                        classifyId: item.classifyId,
                        requests: []
                    };
                    groupValue = group.label;
                    $scope.groups.push(group);
                }
                // Add the friend to the currently active
                // grouping.
                group.requests.push(item);
            }
            return $scope.groups;
        };

        function sortOn(collection, name) {
            collection.sort(
                function (a, b) {
                    if (a[name] <= b[name]) {
                        return (-1);
                    }
                    return (1);
                }
            );
        }

