        $scope.addNewGrid = function (form, event) {
            event.preventDefault();
            $scope.RequestModel.validationErrors = [];
            if (!form.$valid) {
                for (var key in form.$error) {
                    for (var index = 0; index < form.$error[key].length; index++) {
                        var errorObj = {};
                        var fields = form.$error[key][index].$name.split('_');
                        errorObj.name = form.$error[key][index].$name;
                        errorObj.row = parseInt(fields[1]);
                        errorObj.errors = [];
                        var column = fields[0];

                        var item = $filter('filter')($scope.RequestModel.GridDetails, { fieldName: column });
                        if (item.length !== 0) {
                            errorObj.errors.push(item[0].requiredMessage);
                            $scope.RequestModel.validationErrors.push(errorObj);
                        }
                    }
                }
                return false;
            }

            var validDate = true;
            angular.forEach($scope.Grid, function (val, key) {
                if (val.CreatedDate && val.DueDate) {
                    if (val.CreatedDate > val.DueDate) {
                        $timeout(function () { toaster.clear(); toaster.error('تاريخ التحرير أكبر من تاريخ الإستحقاق'); }, 0);
                        return validDate = false;
                    }
                }
            });

            if (!validDate) {
                return false;
            }
            var FieldsNames = $scope.RequestModel.GridDetails.map(function (a) { return a.fieldName; });
            var obj = {};
            angular.forEach(FieldsNames, function (val, key) {
                obj[val] = '';
                obj[val + 'Settings'] = $.grep($scope.RequestModel.GridDetails, function (b) {
                    return b.fieldName === val;
                })[0];
            });
            $scope.Grid.push(obj);
        };

        $scope.addDynamicNewGrid = function (form, event, parent) {
            //فانشكن لاضافة سطر جديد ب grid  تفاصيل الطلب 
            //يتم رسم السطر داخل الجدول كل CEll على حدة 
            //السطر عباره عن array of columns
            //كل cell  ليها Validation 
            //Parent  يعبر عن ال grid التي ينتمي ليها السطر والخلية نظرا لوجود بعض الطلبات تحتوي على أكثر من grid

            event.preventDefault();
            var formName = form;
            $scope.RequestModel.validationErrors[form] = [];
            form = $scope.requestForm[form];
            if (!form.$valid) {
                for (var key in form.$error) {
                    for (var index = 0; index < form.$error[key].length; index++) {
                        var errorObj = {};
                        var fields = form.$error[key][index].$name.split('_');
                        errorObj.name = form.$error[key][index].$name;
                        errorObj.parent = parseInt(fields[1]);
                        errorObj.row = parseInt(fields[1]);
                        errorObj.column = parseInt(fields[2]);
                        errorObj.errors = [];
                        var column = fields[0];

                        var item = $filter('filter')($scope.RequestModel.GridDetails, { fieldName: column });
                        if (key === 'required') {
                            errorObj.errors.push(item[0].requiredMessage);
                        }
                        else if (key === 'minlength' || key === 'minlength') {
                            errorObj.errors.push(item[0].lenghtMessage);
                        }
                        else if (key === 'pattern') {
                            errorObj.errors.push(item[0].patternMessage);
                        }

                        if (item.length !== 0) {
                            // errorObj.errors.push(item[0].requiredMessage);
                            $scope.RequestModel.validationErrors[formName].push(errorObj);
                        }
                    }
                }
                return false;
            }

            var _parent = $scope.GridsArray.find(v => v.ParentName == parent.ParentName);
            OriginalGridDetails = JSON.parse(sessionStorage.getItem('OriginalGridDetails')) || [];
            //var grid = $.grep(OriginalGridDetails, function (b) {
            //    return b.detailFieldName === parent.ParentName;
            //});
            var grid = $filter('filter')(OriginalGridDetails, { detailFieldName: parent.ParentName });
            // OriginalGridDetails.find(item => item.detailFieldName === parent.ParentName)
            if (grid.length > 0) {
                var arr = [];
                angular.forEach(grid, function (v, k) {
                    var obj = {
                        defaultValue: v.defaultValue,
                        defaultValue: v.defaultValue,
                        detailFieldName: v.detailFieldName,
                        detailId: v.detailId,
                        detailNameAr: v.detailNameAr,
                        fieldName: v.fieldName,
                        fieldType: v.fieldType,
                        fieldTypeMessage: v.fieldTypeMessage,
                        gridDetailId: v.gridDetailId,
                        id: v.id,
                        isRequired: v.isRequired,
                        lenghtMessage: v.lenghtMessage,
                        maxLength: v.maxLength,
                        maxValue: v.maxValue,
                        maxValueMessage: v.maxValueMessage,
                        maxValueType: v.maxValueType,
                        minLength: v.minLength,
                        minValue: v.minValue,
                        minValueMessage: v.minValueMessage,
                        minValueType: v.minValueType,
                        nameAr: v.nameAr,
                        nameEn: v.nameEn,
                        patternMessage: v.patternMessage,
                        regex: v.regex,
                        relatedFieldId: v.relatedFieldId,
                        requestName: v.requestName,
                        requestTypeDetailId: v.requestTypeDetailId,
                        requiredMessage: v.requiredMessage
                    }
                    arr.push(obj);
                });
                _parent.Grid.push({ SmallGrid: arr });
            }

            angular.forEach($scope.GridsArray, function (v, k) {
                if (v.ParentName == parent.ParentName) {
                    v.Grid = _parent.Grid;
                }
            });
            // $scope.GridsArray.find(v => v.ParentName == parent.ParentName).Grid = _parent.Grid;
            //angular.copy(_parent.Grid);
        };



