        $scope.toggleSelection = function (option, fieldName) {
            let parsedSelection = JSON.parse($scope.RequestModel[fieldName])
            var idx = parsedSelection.indexOf(option);

            // Is currently selected
            if (idx > -1) {
                parsedSelection.splice(idx, 1);
            }

            // Is newly selected
            else {
                parsedSelection.push(option);
            }
            $scope.RequestModel[fieldName] = JSON.stringify(parsedSelection)
        }
        $scope.isChecked = function (option, fieldName) {
            let parsedArray = JSON.parse($scope.RequestModel[fieldName])
            return parsedArray.indexOf(option) > -1
        }
        $scope.setSwitchValue = function (trueFieldName) {
            let falseFieldName = trueFieldName.substring(0, trueFieldName.length - 1) + 'F'
            let newValue = !$scope.RequestModel[trueFieldName]
            $scope.RequestModel[trueFieldName] = newValue
            $scope.RequestModel[falseFieldName] = !newValue
        }
