            $scope.prevModel.IsAdmin = false;

            angular.forEach($scope.OriginalPrvsArr, function (iitm) {
                if (iitm.isSelected) {
                    $scope.SelecteduserPrvs.push({ Val: iitm.id, IsSelected: iitm.isSelected, Code: iitm.code });
                }
            }); 
