        //send sms code to user to continue saving request
        //functon sms request 
        function smsTimer() {
            $scope.page.showSmsTime = true;
            $scope.page.smsTimer = 240;
            var x = setInterval(function () {
                $scope.page.smsTimer = --$scope.page.smsTimer;
                if ($scope.page.smsTimer <= 0) {
                    clearInterval(x);
                    $scope.page.showSmsTime = false;
                    $scope.page.smsTimer = 0;
                }
            }, 1000);
        }
        $scope.sendCode = function (form, event) {
            if ($scope.captcha.response === null || $scope.captcha.response === '') {
                ngNotify.set(appConst.notRobotCaptcha, {
                    position: 'top',
                    type: 'error'
                });
                return false;
            }
            $scope.isVerifyFormSubmitted = true;
            event.preventDefault();
            if (!form.$valid) {
                return false;
            }
            $scope.sms.codeSent = false;
            $scope.sms.codeToMatch = '';
            blockUI.start();
            ngProgress.start();
            CouncilSvc.SendRequestSMSCode({ IdentityNo: $scope.RequestModel.IdentityNo, ChamberId: $rootScope.chamberSettings.id, MemberId: $scope.RequestModel.MemberId, ReCaptchaResponse: $scope.captcha.response, }).then(function successCallback(response) {
                if (response.success) {
                    ngProgress.complete();
                    $scope.sms.codeSent = true;
                    smsTimer();
                    $scope.sms.TrackId = response.data;
                } else {
                    ngProgress.complete();
                    $scope.sms.codeSent = false;
                    $scope.sms.codeNumber = '';
                    ngNotify.set(response.message, {
                        position: 'top',
                        type: 'error'
                    });
                }
                blockUI.stop();
            }, function errorCallback(response) {
                ngNotify.set(response.message, {
                    position: 'top',
                    type: 'error'
                });
                if (response.execptionMessage) {
                    ngNotify.set(response.execptionMessage, {
                        position: 'top',
                        type: 'error'
                    });
                }
                ngProgress.complete();
                $scope.sms.codeSent = false;
                $scope.sms.codeNumber = '';
                blockUI.stop();
            });
        };
        $scope.$watch('sms.codeToMatch.length', function (newValue, oldValue) {
            if (newValue === 6) {
                $scope.showSpinner = true;
                $scope.page.showSmsTime = false;
                $scope.page.smsTimer = 0;
                $scope.sms.codeSent = false;
                $scope.CodeVerified = true;
                $timeout(function () {
                    angular.element(document.getElementById('injectCalnder')).append($compile("<script> $('.datepick').calendarsPicker({ calendar: $.calendars.instance('gregorian'), dateFormat: 'yyyy-mm-dd', onSelect: function (date) { $(this).change(); } });</script>")($scope));
                }, 1000)
            }
        });
