app.controller('MeetingTermsController', ['$rootScope', 'sharedService', 'session', '$routeParams', 'blockUI', '$window', '$timeout', 'MeetingSvc',
    '$scope', '$sce', 'globalService',
    function ($rootScope, sharedService, session, $routeParams, blockUI, $window, $timeout, MeetingSvc, $scope, $sce, globalService) {
        $scope.session = session;
        $rootScope.title = "بنود الإجتماع";
        $scope.MeetingGUID = ($routeParams.val !== null && $routeParams.val !== "" && $routeParams.val !== undefined) ? $routeParams.val : null;

        sharedService.stopInterval();

        $rootScope.showMeetingPopUp = false;
        $(".modal-backdrop").css("display", "none");
        $('#showMeetingPopUpId').modal('hide');

        $scope.page = {
            NoData: false,
            showPopup: false,
            thereIsData: false,
            showLoad: false,
            disableSelect: true
        };

        $scope.InitPage = function () {
            $scope.page.thereIsData = false;
            $scope.page.showLoad = true;
            $scope.page.NoData = false;
            $scope.meeting = {};
            $scope.meetingTerms = [];
            MeetingSvc.GetMeetingById({ MeetingGUID: $scope.MeetingGUID, PageSize: 100, PageIndex: 1 }).then(function (response) {
                if (response.success) {
                    if (response.data.meeting === null) {
                        $scope.page.NoData = true;
                        $scope.page.thereIsData = false;
                        $scope.page.showLoad = false;
                    }
                    else if (response.data.meeting.meeting.meetingStatusId === 3) {
                        $scope.page.NoData = true;
                        $scope.page.thereIsData = false;
                        $scope.page.showLoad = false;
                    }
                    else {
                        $scope.meeting = response.data.meeting;
                        $scope.meetingTerms = response.data.meetingTerms;
                        $scope.page.NoData = false;
                        $scope.page.thereIsData = true;
                        $scope.page.showLoad = false;
                    }
                } else {
                    $scope.page.NoData = true;
                    $scope.page.thereIsData = false;
                    $scope.page.showLoad = false;
                }
            });
        };


        $scope.showAttachment = function (obj) {
            if (obj.type === 'application/pdf') {
                globalService.filePreviewPDF(obj.source);
            }
            else {
                var image = new Image();
                image.src = "data:" + obj.type + ";base64," + obj.source;
                var w = window.open("");
                w.document.write(image.outerHTML);
            }
        }

        $scope.showAttachmentHttp = function (obj) {
            blockUI.start(); 
            MeetingSvc.GetTermAttachment({ IdGuid: obj.idGuid }).then(function (response) {
                blockUI.stop();
                if (response.success) {
                    $scope.showAttachment(response.data); 
                    ngProgress.complete();
                } else { 
                    ngProgress.complete();
                }
            });
        }


        $scope.InitPage();

    }]);
;
