;
"use strict";
app.controller('MeetingVoteController', ['$rootScope', 'session', 'appConst', 'blockUI', 'sharedService', '$routeParams', 'ngProgress', 'MeetingSvc',
    '$scope', '$timeout', 'ngNotify', 'renderFile', '$interval', '$filter', '$location', 'toaster','globalService',
    function ($rootScope, session, appConst, blockUI, sharedService, $routeParams, ngProgress, MeetingSvc, $scope, $timeout, ngNotify, renderFile, $interval, $filter, $location, toaster, globalService) {
        $scope.session = session;
        $rootScope.ShowLayout = false;
        $rootScope.title = "التصويت - الجمعية العمومية";
        $rootScope.NavigationTitle = "التصويت - الجمعية العمومية";
        blockUI.stop();
        blockUI.start();
        $scope.CurrentChamberId = null;

        if ($rootScope.chamberSettings?.pdfUrl) {
            let str = $rootScope.chamberSettings.pdfUrl;
            let matches = str.match(/(\d+)/);
            $scope.CurrentChamberId = matches[0];
        }
       
        $scope.RegisterModel = {
            IdentityNo: ($routeParams.uid !== null && $routeParams.uid !== "" && $routeParams.uid !== undefined) ? $routeParams.uid : null,
            MeetingGuid: ($routeParams.id !== null && $routeParams.id !== "" && $routeParams.id !== undefined) ? $routeParams.id : null
        }

        sharedService.stopInterval();
        $rootScope.showMeetingPopUp = false;
        $(".modal-backdrop").css("display", "none");
        $('#showMeetingPopUpId').modal('hide');
        $scope.identityPattern = appConst.identityPattern;
        $scope.page = {
            NoData: false,
            showPopup: false,
            thereIsData: false,
            showLoad: false,
            showTermsConditions: false,
            showAbshirConfirm: false,
            showMeetingTerms: false
        };
        $scope.sendByRayah = true;
        $scope.timeElapsed = appConst.timeElapsed;
        $scope.Sms = { TrackId: null, Code: null, CodeSent: false };
        $scope.isFormSubmitted = false;
        $scope.showSpin = false;


        $scope.currentStep = 1;

        if ($scope.RegisterModel.IdentityNo != null) {
            $scope.successRegisteration = false;
            $scope.currentStep = 3;
            $scope.ValidationDone = true;
            $scope.showRegister = false;
            $scope.showTFA = false;
            $scope.showSpin = true;
            blockUI.stop();
            blockUI.start();
            setTimeout(function () {
                init();
                $scope.$digest();
            }, 5000);
        } else {
            blockUI.stop();
            $scope.SubmitRegister = false;
            $scope.showTFA = false; //two factor authentication form
            $scope.showRegister = true;
            $scope.ValidationDone = false;
            $scope.successRegisteration = false;
        }


        $scope.showAttachmentHttp = function (obj) {
            blockUI.start();
            MeetingSvc.GetTermAttachment({ IdGuid: obj.idGuid }).then(function (response) {
                blockUI.stop();
                if (response.success) {
                    $scope.showAttachment(response.data[0]);
                    ngProgress.complete();
                } else {
                    ngProgress.complete();
                }
            });
        }

        $scope.showAttachment = function (obj) {
            if (obj.type === 'application/pdf') {
                globalService.filePreviewPDF(obj.source);
            }
            else {
                var image = new Image();
                image.src = "data:" + obj.type + ";base64," + obj.source;
                var w = window.open("");
                w.document.write(image.outerHTML);
            }
        }

        $scope.ValidateVote = function (form, event, isRetry) {
            $scope.SubmitRegister = true;
            $scope.Message = '';
            if (!form.$valid && !isRetry) {
                event.preventDefault();
                return false;
            }

            $scope.showSpin = true;
            MeetingSvc.ValidateVote($scope.RegisterModel).then(function (response) {
                if (response.success) {
                    $scope.smsInputs = [{ id: 3, value: null }, { id: 2, value: null }, { id: 1, value: null }, { id: 0, value: null }];
                    $scope.Sms.TrackId = response.data.msgResult.data.trackId;
                    $scope.Sms.CodeSent = true;
                    //Show OTP Inputs
                    $scope.showTFA = true;
                    $scope.showSpin = false;
                    $scope.showRegister = false;
                    //$scope.showRetrySendCode = true;
                    $scope.currUserMobile = response.data.hashedMobile;
                    $scope.currentStep = 2;
                    $scope.cancel();
                    $scope.timeElapsed = appConst.timeElapsed;
                    startTimer();
                } else {
                    $scope.showTFA = false;
                    $scope.showSpin = false;
                    $scope.Message = response.message;
                }
            });
        }

        $scope.resendLoginCode = function () {
            // if ($rootScope.codeMaxLength !== null && $rootScope.codeMaxLength !== undefined && $rootScope.codeMaxLength !== '') {
            //  if ($rootScope.codeMaxLength === 4) {
            $scope.smsInputs = [{ id: 3, value: null }, { id: 2, value: null }, { id: 1, value: null }, { id: 0, value: null }];
            //    } else {
            //        $scope.smsInputs = [{ id: 5, value: null }, { id: 4, value: null }, { id: 3, value: null }, { id: 2, value: null }, { id: 1, value: null }, { id: 0, value: null }];
            //    }
            //}
            authService.resendLoginCode();
        };


        $scope.$watch('codeMaxLength', function (newValue) {
            //if (newValue !== null && newValue !== undefined && newValue !== '') {
            //    if (newValue === 4) {
            $scope.smsInputs = [{ id: 3, value: null }, { id: 2, value: null }, { id: 1, value: null }, { id: 0, value: null }];
            //    } else {
            //        $scope.smsInputs = [{ id: 5, value: null }, { id: 4, value: null }, { id: 3, value: null }, { id: 2, value: null }, { id: 1, value: null }, { id: 0, value: null }];
            //    }
            //}
        });


        $scope.resendLoginCodeForAbshir = function () {
            authService.resendLoginCodeForAbshir();
        };


        var increaseCounter = function () {
            $scope.timeElapsed = --$scope.timeElapsed;
            if ($scope.timeElapsed <= 0) {
                $scope.cancel();
                $scope.showRetrySendCode = true;
            }
        }

        var promise;
        $scope.cancel = function () {
            $interval.cancel(promise);
        };

        function startTimer() {
            $scope.showRetrySendCode = false;
            // $scope.timeElapsed = 5;
            promise = $interval(increaseCounter, 1000);
        }


        //Combine SMS Code from front to one string value to be validated
        $scope.combineCode = function (digit, index) {
            if (digit !== null) {
                $scope.Sms.Code = ($scope.Sms.Code === null) ? 'xxxx' : $scope.Sms.Code;
                var a = $scope.Sms.Code.split('');
                a[$scope.smsInputs.length - index - 1] = digit.value;
                $scope.Sms.Code = a.join('');
                if ($scope.Sms.Code !== undefined && $scope.Sms.Code !== null && $scope.Sms.Code !== '') {
                    if ($scope.Sms.Code.toString().indexOf('x') === -1) {
                        if ($scope.Sms.Code.length === 4) {
                            $scope.showSpin = true;
                            $scope.Message = '';
                            $timeout(function () { ValidateVoteOTP({ IdentityNo: $scope.RegisterModel.IdentityNo, MeetingGuid: $scope.RegisterModel.MeetingGuid, Code: $scope.Sms.Code, TrackId: $scope.Sms.TrackId }); }, 300);
                        }
                    }
                }
            }
        }

        $scope.selectSubTerm = function (subTerms,index) {
            angular.forEach(subTerms, function (subTerm, i) {
                subTerm.meetingTerm.IsSelected = i === index;
            });
        };

        $scope.Terms = [];
        function ValidateVoteOTP(info) {
            $scope.Terms = [];
            MeetingSvc.ValidateVoteOTP(info).then(function (response) {
                setTimeout(function () { blockUI.stop(); });
                if (response.success) {
                    $scope.smsInputs = [{ id: 3, value: null }, { id: 2, value: null }, { id: 1, value: null }, { id: 0, value: null }];
                    //Show OTP Inputs
                    $scope.showTFA = false;
                    $scope.showSpin = false;
                    $scope.showRegister = false;
                    $scope.showRetrySendCode = false;

                    //main terms without sub terms
                    $scope.Terms = $.grep(response.data.data, function (n, i) {
                        return n.meetingTerm.parentTermId === null;
                    });

                    angular.forEach($scope.Terms, function (val, key) {
                        val.subTerms = $.grep(response.data.data, function (n, i) {
                            return n.meetingTerm.parentTermId === val.meetingTerm.meetingTermId;
                        });
                    });


                  //  $scope.Terms = MainTerms;

                    $scope.CrNumber = $rootScope.chamberSettings.meetingDirectVotingAfterRegister == true ? response.data.crNumber : null;
                    $scope.UnifiedNumber = $rootScope.chamberSettings.meetingDirectVotingAfterRegister == true ? response.data.unifiedNumber : null;
                    $scope.ValidationDone = true;
                    $scope.currentStep = 3;
                } else {
                    //$scope.showTFA = false;
                    $scope.showSpin = false;
                    $scope.showRetrySendCode = true;
                    $scope.timeElapsed = appConst.timeElapsed;
                    $scope.Message = response.message;
                }
            });
        };
        ///////////////////////////////////////////////////////////////////////////
        $scope.meetingStartDate = null;
        $scope.meetingEndDate = null;
        $scope.conferenceLink = null;
        $scope.showMeetingLink = null;

        $scope.ConfirmVote = function (model) {
            const voting = $.grep(model, function (n, i) {
                return (n.meetingTerm.VoteAction === null || n.meetingTerm.VoteAction === undefined) && n.subTerms.length == 0;
            });
            if (voting.length > 0) {
                toaster.clear();
                toaster.pop('error', 'يرجي التصويت بالقبول أو الرفض على جميع البنود');
                return false;
            }
            var list = [];
            var notValidVoteList = [];
            //Main Terms
            angular.forEach(model, function (val, key) {
                if (val.meetingTerm.VoteAction != true && val.subTerms.length==0) {
                    if (val.meetingTerm.VoteNotes == null || val.meetingTerm.VoteNotes == '' || val.meetingTerm.VoteNotes == undefined) { 
                        notValidVoteList.push(val); 
                    }
                }

                if (val.subTerms.length == 0) {
                    list.push({
                        IdentityNo: $scope.RegisterModel.IdentityNo,
                        MeetingTermId: val.meetingTerm.meetingTermId,
                        MeetingId: val.meetingTerm.meetingId,
                        VoteAction: val.meetingTerm.VoteAction,
                        VoteNotes: val.meetingTerm.VoteNotes,
                        HasSubTerms: val.subTerms.length ? true : false,
                        CrNumber: ($scope.CrNumber === '' || $scope.CrNumber == undefined ? null : $scope.CrNumber),
                        UnifiedNumber: ($scope.UnifiedNumber === '' || $scope.UnifiedNumber == undefined ? null : $scope.UnifiedNumber)
                    });
                }
            });
            if ($scope.CurrentChamberId != 402) {
                if (notValidVoteList.length > 0 && $rootScope.chamberSettings.id != 104) {
                    toaster.clear();
                    toaster.pop('error', 'فضلاً أدخل سبب الرفض على البنود التي تم التصويت عليها ب رافض');
                    notValidVoteList.push(val);
                    return false;
                }
            }
            //Sub Terms

            var subTerms = model
                .filter(item => item.subTerms && item.subTerms.length > 0)
                .flatMap(item => item.subTerms);

            // group subterms by parentTermId to do validate "one term must be selected to do voting"

            var subTermsList = subTerms.reduce((acc, item) => {
                acc[item.meetingTerm.parentTermId] = acc[item.meetingTerm.parentTermId] || [];
                acc[item.meetingTerm.parentTermId].push(item);
                return acc;
            }, {});

            angular.forEach(subTermsList, function (val, key) {
                var hasSelectedTerms = $.grep(val, function (n, i) {
                    return n.meetingTerm.IsSelected === true;
                }).length > 0;
                if (!hasSelectedTerms) {
                    toaster.clear();
                    toaster.pop('error', 'فضلاً قم بإختيار أحد البنود لإتمام بعملية التصويت');
                    return false;
                } 
            });
            angular.forEach(subTerms, function (val, key) {
                list.push({
                    IdentityNo: $scope.RegisterModel.IdentityNo,
                    MeetingTermId: val.meetingTerm.meetingTermId,
                    MeetingId: val.meetingTerm.meetingId,
                    VoteAction: val.meetingTerm.VoteAction,
                    VoteNotes: val.meetingTerm.VoteNotes,
                    IsSelected: val.meetingTerm.IsSelected,
                    HasSubTerms: false,
                    IsSubTerm:true,
                    CrNumber: ($scope.CrNumber === '' || $scope.CrNumber == undefined ? null : $scope.CrNumber),
                    UnifiedNumber: ($scope.UnifiedNumber === '' || $scope.UnifiedNumber == undefined ? null : $scope.UnifiedNumber)
                });
            });
          

            $scope.Message = '';
            $scope.showSpin = true;
            $scope.successRegisteration = false;
            blockUI.start();
            MeetingSvc.InsertVote(list).then(function (response) {
                blockUI.stop();
                $scope.showSpin = false;
                if (response.success) {
                    $scope.successRegisteration = true;
                    if (!$rootScope.chamberSettings.meetingDirectVotingAfterRegister) {
                        $timeout(function () { window.location.href = "/#/Login"; }, 8000);
                    } else {
                        $scope.meetingStartDate = response.data.startDate;
                        $scope.meetingEndDate = response.data.endDate;
                        $scope.conferenceLink = '/#/Meetings/Attendance?id=' + $rootScope.chamberSettings.id + '&uid=' + response.data.meetingMemberId + '&url=' + response.data.conferenceLink;
                        if (response.data.conferenceLink !== null && response.data.conferenceLink !== undefined && response.data.conferenceLink !== '') {
                            $scope.showMeetingLink = response.data.showMeetingLink;
                        } else {
                            $scope.showMeetingLink = false;
                        }
                    }
                } else {
                    $scope.Message = response.message;
                }
            });
        };

        $scope.setBack = function () {
            switch ($scope.currentStep) {
                case 2:
                case 3:
                    if ($scope.successRegisteration) {
                        $location.path('/Login');
                    }
                    $scope.showRegister = true;
                    $scope.showTFA = false;
                    $scope.Message = '';
                    $scope.smsInputs = [{ id: 3, value: null }, { id: 2, value: null }, { id: 1, value: null }, { id: 0, value: null }];
                    $scope.Sms = { TrackId: null, Code: null, CodeSent: false };
                    $scope.showSpin = false;
                    $scope.showRetrySendCode = false;
                    $scope.timeElapsed = 0;
                    $scope.cancel();
                    $scope.ValidationDone = false;
                    $scope.timeElapsed = appConst.timeElapsed;
                    $scope.currentStep = 1;
                    break;
                case 4:
                    $scope.showDelegated = false;
                    $scope.successRegisteration = false;
                    $scope.currentStep = 3;
                    break;
                default:
                    $location.path('/Login');
            }
        }

        $scope.AttachDownload = function (x) {
            $scope.FileExt = x.name.substr(x.name.length - 3);
            renderFile.generateFileType($scope.FileExt);
            renderFile.init({ data: x.source, name: x.name, type: $scope.FileExt });
        };

        $scope.DelegatedUsers = [];
        $scope.showDelegated = false;
        $scope.GetDelegatedUsers = function (model) {
            $scope.Message = '';
            blockUI.start();
            $scope.successRegisteration = false;
            $timeout(function () { $scope.showDelegated = true; }, 2000);
            MeetingSvc.GetDelegatedUsers(model).then(function (response) {
                blockUI.stop();
                if (response.success) {
                    const filteredData = Array.prototype.filter.call(response.data, function (b) {
                        if (b.userName !== $scope.RegisterModel.IdentityNo) { return b }
                    })
                    $scope.DelegatedUsers = filteredData;
                } else {
                    $scope.Message = response.message;
                }
            });
        };

        $scope.acceptTerms = function (form, event) {
            $scope.isFormSubmitted = true;
            event.preventDefault();

            if (!form.$valid) {
                return false;
            }
            $scope.page.showTermsConditions = false;
            $scope.page.showAbshirConfirm = true;
            $scope.sendCode(form, event);
        };

        $scope.cancelTerms = function () {
            swal({
                title: '', type: "info",
                text: "هل تريد تحويلك الي الصفحة الرئيسية وإلغاء حضور إجتماع الجمعية العمومية ؟",
                showCloseButton: true,
                showCancelButton: true,
                closeOnConfirm: true,
                closeOnCancel: true,
                confirmButtonText: 'نعم قم بتحويلي للرئيسية لا أريد حضور الإجتماع',
                cancelButtonText: 'الغاء'
            },
                function (isConfirm) {
                    if (isConfirm) {
                        window.location.href = "/#/Home";
                    }
                });
        }


        function smsTimer() {
            $scope.page.showSmsTime = true;
            $scope.page.smsTimer = 240;
            var x = setInterval(function () {
                $scope.page.smsTimer = --$scope.page.smsTimer;
                if ($scope.page.smsTimer <= 0) {
                    clearInterval(x);
                    $scope.page.showSmsTime = false;
                    $scope.page.smsTimer = 0;
                }
            }, 1000);
        }

        $scope.sendCode = function (form, event) {
            event.preventDefault();
            if (!form.$valid) {
                return false;
            }
            $scope.sms.codeSent = false;
            $scope.sms.codeToMatch = '';
            blockUI.start();
            ngProgress.start();
            MeetingSvc.SendSMSCode().then(function successCallback(response) {
                if (response.success) {
                    ngProgress.complete();
                    $scope.sms.codeSent = true;
                    smsTimer();
                    $scope.sms.TrackId = response.data;
                } else {
                    ngProgress.complete();
                    $scope.sms.codeSent = false;
                    $scope.sms.codeNumber = '';
                    ngNotify.set(response.message, {
                        position: 'top',
                        type: 'error'
                    });
                }
                blockUI.stop();
            }, function errorCallback(response) {
                ngNotify.set(response.message, {
                    position: 'top',
                    type: 'error'
                });
                if (response.execptionMessage) {
                    ngNotify.set(response.execptionMessage, {
                        position: 'top',
                        type: 'error'
                    });
                }
                ngProgress.complete();
                $scope.sms.codeSent = false;
                $scope.sms.codeNumber = '';
                blockUI.stop();
            });
        };
        $scope.$watch('sms.codeToMatch.length', function (newValue, oldValue) {
            $scope.CodeVerified = false;
            if (newValue === 6) {
                $scope.showSpinner = true;
                $scope.page.showSmsTime = false;
                $scope.page.smsTimer = 0;

                //confirm OTP and add meeting member
                $scope.ConfirmAttendance();

            }
        });

        $scope.ConfirmAttendance = function () {
            var details = {
                MeetingGuid: $scope.RegisterModel.MeetingGuid,
                EstName: session.getPropertyLocalStorage('EstName', false),
                CrNumber: session.getPropertyLocalStorage('CRNumber', false),
                UnifiedNumber: session.getPropertyLocalStorage('MM_UnifiedNumber', false),
                SMS: {
                    Code: $scope.sms.codeToMatch,
                    TrackId: $scope.sms.TrackId
                },
                ResponsibleName: session.getPropertyLocalStorage('ResponsibleName', false)
            };
            ngProgress.start();
            blockUI.start();
            MeetingSvc.ConfirmAttendance(details).then(function (response) {
                if (response === null) {
                    ngProgress.complete();
                    $scope.sms.codeSent = false;
                    blockUI.stop();
                    ngNotify.set(appConst.errorOccurred, {
                        position: 'top',
                        type: 'error',
                        duration: 10000
                    });
                    return false;
                }
                if (!response.success) {
                    ngProgress.complete();
                    blockUI.stop();
                    if (response.code === 18 && $scope.sms.codeSent === true) {
                        ngNotify.set(response.message, {
                            position: 'top',
                            type: 'error',
                            duration: 1000
                        });
                        return false;
                    }
                    $scope.sms.codeSent = false;
                    if (response.code === 26) {
                        if (angular.isArray(response.data)) {
                            angular.forEach(response.data, function (val, key) {
                                response.message = '';
                                response.message += '(' + val.memberNames[0] + ' ' + val.errorMessage + ')' + '-';
                            });
                            ngNotify.set(response.message, {
                                position: 'top',
                                type: 'error',
                                duration: 10000
                            });
                        } else {
                            ngNotify.set(response.data, {
                                position: 'top',
                                type: 'error',
                                duration: 10000
                            });
                        }

                        return false;
                    }
                    else {

                        $timeout(function () {
                            ngNotify.set(response.message, {
                                position: 'top',
                                type: 'error',
                                duration: 10000
                            });
                        }, 200);
                        return true;
                    }

                }
                if (response.success) {
                    ngProgress.complete();
                    blockUI.stop();
                    $scope.sms.codeSent = false;
                    $scope.CodeVerified = true;
                    $scope.page.showMeetingTerms = true;
                    $scope.page.showAbshirConfirm = false;
                    ngNotify.set(response.message, {
                        position: 'top',
                        type: 'success',
                        duration: 10000
                    });
                }
                else {
                    $scope.sms.codeSent = false;
                    if (response.data !== null) {
                        //model validation result
                        if (response.data.length > 0) {
                            angular.forEach(response.data, function (val, key) {
                                response.message += errorMessage + '-';
                            });
                            ngProgress.complete();
                            blockUI.stop();
                            ngNotify.set(response.message, {
                                position: 'top',
                                type: 'error',
                                duration: 10000
                            });
                            return false;
                        }
                    }
                    ngProgress.complete();
                    blockUI.stop();
                    ngNotify.set(response.message, {
                        position: 'top',
                        type: 'error',
                        duration: 10000
                    });
                }
            });
        };


        function init() {
            if ($rootScope.chamberSettings.meetingDirectVotingAfterRegister) {
                $scope.successRegisteration = false;
                $scope.currentStep = 3;
                $scope.ValidationDone = false;
                $scope.showRegister = false;
                $scope.showTFA = false;
                $scope.showSpin = true;
                $scope.Message = '';
                ValidateVoteOTP({
                    IdentityNo: $scope.RegisterModel.IdentityNo, MeetingGuid: $scope.RegisterModel.MeetingGuid, Code: null, TrackId: null,
                    MeetingDirectVotingAfterRegister: $rootScope.chamberSettings.meetingDirectVotingAfterRegister
                });
            }
        }


        //$scope.ValidateMeeting = function () {
        //    $scope.page.thereIsData = false;
        //    $scope.page.showLoad = true;
        //    $scope.page.NoData = false;
        //    MeetingSvc.ValidateMeeting({ MeetingGuid: $scope.MeetingGUID }).then(function (response) {
        //        if (response.success) {
        //            $scope.meetingConfirmed = response.data.confirmed;
        //            if ($scope.meetingConfirmed) {
        //                $scope.page.showMeetingTerms = true;
        //                $scope.CodeVerified = true;
        //                $scope.page.showTermsConditions = false;
        //            } else {
        //                $scope.page.showTermsConditions = true;
        //            }
        //            $scope.page.NoData = false;
        //            $scope.page.thereIsData = true;
        //            $scope.page.showLoad = false;
        //        } else {
        //            $scope.page.NoData = true;
        //            $scope.page.thereIsData = false;
        //            $scope.page.showLoad = false;
        //        }
        //    });
        //}
        //if (!$rootScope.chamberSettings.meetingDirectVotingAfterRegister) {
        //    $scope.ValidateMeeting();
        //}

    }]);
