app.controller('ComPartnerInfoController', ['$rootScope', 'CommercialPartnerSvc', '$scope', 'toaster', 'session',
    function ($rootScope, CommercialPartnerSvc, $scope, toaster, session) {

        $rootScope.NavigationTitle = 'بياناتي ';
        $rootScope.title = "بياناتي";
        $scope.thereIsData = false;
        $scope.showLoad = false;
        $scope.noData = false;
        $scope.showActivityAlert = false;
        $scope.image = { Url: null, Array: [] };

        $scope.AddModel = {
            EstName: session.getPropertyLocalStorage('CurrentMember.EstName', false),
            EstActivity: session.getPropertyLocalStorage('CurrentMember.MemberActivity', false),
            Mobile: null,
            Email: null,
            DiscountType: null,
            DiscountPercentage: null,
            TwitterLink: null,
            InstagramLink: null,
            SnapchatLink: null,
            Slogan: [],
            AttachmentType: null
        }

        $scope.DiscountTypes = [
            { id: 1, nameAr: 'كلي' },
            { id: 2, nameAr: 'جزئي' }
        ];

        function GetData() {
            CommercialPartnerSvc.GetInfo().then(function (response) {
                $scope.thereIsData = false;
                $scope.showLoad = true;
                if (response.success) {
                    if (response.data) {
                        if (response.data.estActivity !== $scope.AddModel.EstActivity) {
                            $scope.showActivityAlert = true;
                        }

                        $scope.AddModel = $scope.capitalizeObject(response.data);
                        if ($scope.showActivityAlert) {
                            $scope.AddModel.EstActivity = session.getPropertyLocalStorage('CurrentMember.MemberActivity', false)
                        }
                        $scope.image = { Url: 'data:' + $scope.AddModel.AttachmentType + ';base64,' + $scope.AddModel.Slogan, Array: convertDataURIToBinary($scope.AddModel.Slogan), AttachmentType: $scope.AddModel.AttachmentType };

                    }


                    //add slogan and type to image object to be seen in screen
                    $scope.thereIsData = true;
                    $scope.showLoad = false;
                } else {
                    toaster.error(response.message);
                    $scope.thereIsData = true;
                    $scope.showLoad = false;
                }
            });
        }

        //Save & Update function
        $scope.Save = function (form, event) {
            $scope.isFormSubmitted = true;
            if (!form.$valid) {
                return false;
            }
            $scope.AddModel.Slogan = $scope.image.Array;
            if ($scope.AddModel.Slogan.length === 0) {
                toaster.error('شعار المنشأة مطلوب');
                return false;
            }
            $scope.AddModel.AttachmentType = $scope.image.AttachmentType;
            $scope.thereIsData = false;
            $scope.showLoad = true;
            CommercialPartnerSvc.AddComParnterMembersData($scope.AddModel).then(function (response) {
                if (response.success) {
                    $scope.AddModel = $scope.capitalizeObject(response.data);
                    //add slogan and type to image object to be seen in screen
                    $scope.image = { Url: 'data:' + $scope.AddModel.AttachmentType + ';base64,' + $scope.AddModel.Slogan, Array: convertDataURIToBinary($scope.AddModel.Slogan), AttachmentType: $scope.AddModel.AttachmentType };
                    $scope.thereIsData = true;
                    $scope.showLoad = false;
                    $scope.showActivityAlert = false;
                    toaster.success(response.message);
                } else {
                    toaster.error(response.message);
                    $scope.thereIsData = true;
                    $scope.showLoad = false;
                }
            });
        }
         
        $scope.imageUpload = function (event) {
            var files = event.target.files; //FileList object
            for (var i = 0; i < files.length; i++) {
                var file = files[i];
                if (file.type === "application/pdf") {
                    toaster.error("قم برفع صورة فقط");
                    return;
                }
                $scope.image.AttachmentType = file.type;
                var reader = new FileReader();
                reader.onload = $scope.imageIsLoaded;
                reader.readAsDataURL(file);
            }
        }

        $scope.imageIsLoaded = function (e) {
            $scope.$apply(function () {
                var arr = convertDataURIToBinary(e.target.result);
                $scope.image.Url = e.target.result;
                $scope.image.Array = arr;
            });
        }

        function _base64ToArrayBuffer(base64) {
            var binary_string = window.atob(base64);
            var len = binary_string.length;
            var bytes = new Uint8Array(len);
            for (var i = 0; i < len; i++) {
                bytes[i] = binary_string.charCodeAt(i);
            }
            return bytes.buffer;
        }

        function convertDataURIToBinary(dataURI) {
            var BASE64_MARKER = ';base64,';
            var base64Index = dataURI.split(BASE64_MARKER).pop();
            var array = new Uint8Array(_base64ToArrayBuffer(base64Index));
            var arr = [];
            for (var i = 0; i < array.length; i++) {
                arr.push(array[i]);
            }
            return arr;
        }

        $scope.capitalizeObject = function (model) {
            var key, keys = Object.keys(model);
            var n = keys.length;
            var newobj = {};
            while (n--) {
                key = keys[n];
                newobj[key.charAt(0).toUpperCase() + key.substr(1)] = model[key];
            }
            model = newobj;
            return model;
        };


        ///////////////////////////////
        //PageLoad Functions
        GetData();

    }]); 
;
