app.controller('MemberCardController', ['$rootScope', 'renderFile', '$scope', 'globalService', 'UsersSvc', '$timeout', '$http',
    function ($rootScope, renderFile, $scope, globalService, UsersSvc, $timeout, $http) {

        $rootScope.NavigationTitle = 'بطاقتي';
        $rootScope.title = "بطاقتي";
        $scope.thereIsData = true;
        $scope.showLoad = false;
        $scope.noData = false;


        $scope.qrCode = null;
        //{
        //    image: null,
        //    pdf: null
        //}




        $scope.downloadImage = function () {
            $timeout(function () {
                var container = document.getElementById("htmltoimage");
                html2canvas(container, { allowTaint: true }).then(function (canvas) {

                    var link = document.createElement("a");
                    document.body.appendChild(link);
                    //link.download = 'بطاقة تعريف ' + $scope.userInfo.userName + ".png";
                    //link.href = canvas.toDataURL("image/png");
                    //link.target = '_blank';
                    //link.click();

                    var imgData = canvas.toDataURL("image/jpeg", 1.0);
                    var pdf = new jsPDF();

                    pdf.addImage(imgData, 'JPEG', 0, 0);
                    pdf.save("download.pdf");
                });

            }, 1000);
        };

        //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

        function init() {
            var vm = {
                EstName: $rootScope.userInfo.globalSessionValues.CurrentMember.EstName,
                CrExpiryDate: $rootScope.userInfo.globalSessionValues.CurrentMember.CrExpiryDate,
                CRNumber: $rootScope.userInfo.globalSessionValues.CurrentMember.CrNumber,
                ExpiredDate: $rootScope.userInfo.globalSessionValues.CurrentMember.ExpiredDate
            }
            $scope.thereIsData = false;
            $scope.showLoad = true;
            $scope.noData = false;

            UsersSvc.GetMemberCard(vm).then(function (response) {
                if (response.success) {
                    $scope.qrCode = response.data.qrCode;//base 64 card as image

                    // $scope.qrCode.image = response.data.image;//base 64 card as image
                    // $scope.qrCode.pdf = response.data.pdf;//base 64 card as pdf
                    $scope.thereIsData = true;
                    $scope.showLoad = false;
                    $scope.noData = false;
                } else {
                    $scope.thereIsData = false;
                    $scope.showLoad = false;
                    $scope.noData = true;

                }
            });
        };

        function saveScreenshot(canvas) {
            const fileName = "image";
            const link = document.createElement("a");
            link.download = fileName + ".png";
            console.log(canvas);
            canvas.toBlob(function (blob) {
                console.log(blob);
                link.href = URL.createObjectURL(blob);
                link.click();
            });
        }


        $scope.download = function (type) {
            $timeout(function () {
                html2canvas(document.getElementById("htmltoimage"), {
                    allowTaint: true 
                }).then(saveScreenshot);

                //var container = document.getElementById("htmltoimage");
                //html2canvas(container, { allowTaint: true }).then(function (canvas) { 
                //    var link = document.createElement("a");
                //    document.body.appendChild(link);

                //    if (type === 1) { //Image
                //        link.download = 'بطاقة تعريف ' + $scope.userInfo.userName + ".png";
                //        link.href = canvas.toDataURL("image/png");
                //        link.target = '_blank';
                //        link.click();
                //    } else { //PDF
                //        var imgData = canvas.toDataURL("image/jpeg", 1.0);
                //        var pdf = new jsPDF();
                //        pdf.addImage(imgData, 'JPEG', 0, 0);
                //        pdf.save('بطاقة تعريف ' + $scope.userInfo.userName + ".pdf");
                //    }
                //});

            }, 1000);

        }


        const b64toBlob = (b64Data, contentType = '', sliceSize = 512) => {
            const byteCharacters = atob(b64Data);
            const byteArrays = [];

            for (let offset = 0; offset < byteCharacters.length; offset += sliceSize) {
                const slice = byteCharacters.slice(offset, offset + sliceSize);

                const byteNumbers = new Array(slice.length);
                for (let i = 0; i < slice.length; i++) {
                    byteNumbers[i] = slice.charCodeAt(i);
                }

                const byteArray = new Uint8Array(byteNumbers);
                byteArrays.push(byteArray);
            }

            const blob = new Blob(byteArrays, { type: contentType });
            return blob;
        }

        //////////////////////////////////////////////////////////////
        init();

    }]); 
;
