app.controller('SubscriptionsIndexController', ['$rootScope', 'CommitteeSvc', '$route', '$routeParams', 'globalService', 'renderFile', 'ngProgress', '$scope',
    'ngNotify', 'LookupSvc', 'appConst', '$sce', 'Alertify', 'session', 'blockUI', 'AllRequestSvc', 'CommercialPartnerSvc', '$filter',
    function ($rootScope, CommitteeSvc, $route, $routeParams, globalService, renderFile, ngProgress, $scope,
        ngNotify, LookupSvc, appConst, $sce, Alertify, session, blockUI, AllRequestSvc, CommercialPartnerSvc, $filter) {

        $rootScope.NavigationTitle = ' اشتراكاتى ';
        $rootScope.title = "اشتراكاتى ";

        $scope.page = {
            thereIsData: false,
            noData: false,
            showLoad: false
        };

        $scope.ShowData = false;

        $scope.Objects = [];
        $scope.EndDate = ''; 

        $(".modal-backdrop").css("display", "none");

        $scope.GetSubscribtion = function () {
            var model = { MemberId: null, ChamberId: null }
            CommercialPartnerSvc.GetSubscribtion(model).then(function (response) {
                if (response.success) {
                    $scope.Objects = response.data;
                    if ($scope.Objects.length > 0) {
                        $scope.EndDate = $scope.Objects[0].endDate;
                        $scope.EndDate = $filter('date')($scope.EndDate, "yyyy-MM-dd");
                        $scope.ShowData = true;
                    }
                    $scope.page.thereIsData = true;
                    $scope.page.showLoad = false;
                }
            });
        };


        ///////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
        ///////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////


        // Set the date we're counting down to
        // Update the count down every 1 second
        var x = setInterval(function () {
            var countDownDate = new Date($scope.EndDate).getTime();
            // Get today's date and time
            var now = new Date().getTime();
            // Find the distance between now and the count down date
            var distance = countDownDate - now;
            // Time calculations for days, hours, minutes and seconds
            var days = Math.floor(distance / (1000 * 60 * 60 * 24));
                // Output the result in an element with id="demo"
            //if (document.getElementById("expireDate") != null) {
            //    document.getElementById("expireDate").innerHTML = isNaN(days) ? null : days + " يوم ";
            //}
            $scope.expireDate = days + " يوم ";
           
            // If the count down is over, write some text
            if (distance < 0) {
                clearInterval(x);
                document.getElementById("expireDate").innerHTML = "<span class='expired-msg'>الباقة منتهية</b>";
            }
        }, 1000);

        //Page Load functions
        $scope.GetSubscribtion();

    }]);

;
