app.controller('NotificationsController', ['$rootScope', 'NotificationSvc', '$route', '$routeParams', 'globalService', 'renderFile', 'ngProgress', '$scope',
    'ngNotify', 'LookupSvc', 'appConst', '$sce', 'Alertify', 'session', 'blockUI', 'AllRequestSvc', 'CommercialPartnerSvc', '$filter',
    function ($rootScope, NotificationSvc, $route, $routeParams, globalService, renderFile, ngProgress, $scope,
        ngNotify, LookupSvc, appConst, $sce, Alertify, session, blockUI, AllRequestSvc, CommercialPartnerSvc, $filter) {

        $rootScope.NavigationTitle = ' الإشعارات ';
        $rootScope.title = "الإشعارات ";

        $scope.page = {
            thereIsData: false,
            noData: false,
            showLoad: false,
            showAttachmentsModal: false
            // showRejectReasonModal: false
        };

        $scope.searchModel = {
            CurrentPage: 1,
            ItemsPerPage: 10,
            FromDate: null,
            ToDate: null 
        };

        $scope.card = null;

        $scope.GetData = function () {
            var vm = {
                CurrentPage: $scope.searchModel.CurrentPage,
                PageSize: $scope.searchModel.ItemsPerPage,
                FromDate: $scope.searchModel.FromDate,
                ToDate: $scope.searchModel.ToDate 
            }

            $scope.objects = [];
            $scope.page.thereIsData = false;
            $scope.page.noData = false;
            $scope.page.showLoad = true;
            ngProgress.start();
            NotificationSvc.GetNotifications(vm).then(function (response) {
                if (response.success && response.data !== null) {
                    if (response.data.length > 0) {
                        $scope.searchModel.TotalCount = response.data[0].rowsCount;
                        session.updateLocalStorage('ComPartnerNotifyCount', response.data[0].rowsCount, false);
                        $rootScope.userInfo.globalSessionValues.ComPartnerNotifyCount = response.data[0].rowsCount;
                        $scope.objects = response.data;
                        $scope.page.noData = false;
                        $scope.page.thereIsData = true;
                        $scope.page.showLoad = false;
                        ngProgress.complete();
                    }
                    else {
                        $scope.page.noData = true;
                        $scope.page.thereIsData = false;
                        $scope.page.showLoad = false;
                        $scope.searchModel.totalCount = 0;
                        $scope.objects = [];
                        ngProgress.complete();
                    }
                } else {
                    $scope.page.noData = true;
                    $scope.page.thereIsData = false;
                    $scope.page.showLoad = false;
                    $scope.searchModel.totalCount = 0;
                    $scope.objects = [];
                    ngProgress.complete();
                }
            });
        };

        $scope.clearSearchModel = function () {
            $scope.searchModel = {
                CurrentPage: 1,
                ItemsPerPage: 10,
                FromDate: null,
                ToDate: null 
            };
        };

        $scope.currentObject = {};
        $scope.showDetailsModal = function (object) {
            $scope.currentObject = globalService.capitalizeObject(object);
            $scope.showModal = !$scope.showModal;
        }
        ///////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
        ///////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

 

        //Page Load functions
        $scope.GetData();

    }]);

