        //get member master name for open request between two members
        $scope.getMember = function () {
            $scope.RequestModel.SecondMemberName = '';
            $scope.RequestModel.noActiveUsers = true;
            if ($scope.RequestModel.FirstMemberId === $scope.RequestModel.SecondMemberId) {
                $timeout(function () { toaster.clear(); toaster.error(' أرقام العضويات متشابهه.'); }, 0);
                return false;
            }
            if ($scope.RequestModel.SecondCRNumber === $scope.RequestModel.FirstCRNumber) {
                $timeout(function () { toaster.clear(); toaster.error(' أرقام السجلات متشابهه.'); }, 0);
                return false;
            }
            if ($scope.RequestModel.SecondCRNumber && $scope.RequestModel.SecondMemberId) {
                if ($scope.RequestModel.SecondCRNumber.length === 10 && $scope.RequestModel.SecondMemberId.length === 12) {
                    AllRequestSvc.GetMemberMasterName({ SecondMemberId: $scope.RequestModel.SecondMemberId, CR_No: $scope.RequestModel.SecondCRNumber }).then(function successCallback(response) {
                        if (response.success) {
                            $scope.RequestModel.noActiveUsers = false;
                            $scope.RequestModel.SecondMemberName = response.data;
                            return true;
                        } else {
                            $scope.RequestModel.noActiveUsers = true;
                            $timeout(function () {
                                toaster.clear(); toaster.error({ title: response.code === 41 ? 'العضوية مُسجلة على غرفة أخري' : response.message }, null, null, null, 10000);
                            }, 0);
                            return false;
                        }
                    }, function errorCallback(response) {

                    });
                } else {
                    $scope.RequestModel.noActiveUsers = true;
                }
            }
        };

