        /////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
        //case with open request to preview print pdf before saving the request
        $scope.previewData = null;
        $scope.previewRequest = function (form) {
            if ($scope.RequestModel.RequestText === null || $scope.RequestModel.RequestText === '' || $scope.RequestModel.RequestText === undefined) {
                $timeout(function () {
                    toaster.clear(); toaster.pop('error', 'نص الطلب مطلوب.');
                }, 0);
                return false;
            }
            blockUI.start();
            ngProgress.start();

            var model = {
                RequestTypeId: $routeParams.id,
                ChamberId: $scope.page.DefaultChamberId,
                RequestData: JSON.stringify({
                    "RequestDirection": $scope.RequestModel.RequestDirection,
                    "RequestText": $scope.RequestModel.RequestText, "Notes": $scope.RequestModel.Notes
                })
            };
            NonMembersRequestsSvc.PreviewRequestDownload(model).then(function (response) {
                blockUI.stop();
                ngProgress.complete();
                if (response === null) {
                    $timeout(function () { toaster.clear(); toaster.error({ title: appConst.errorOccurred }, null, null, null, 10000); }, 0);
                    return false;
                }
                if (!response.success) {
                    $timeout(function () { toaster.clear(); toaster.error({ title: response.message }, null, null, null, 10000); }, 0);
                    return false;
                }
                if (response.success) {
                    var file = globalService.base64ToBlob(response.data);
                    var fileURL = URL.createObjectURL(file);
                    //remove toolbar actions like download file
                    $scope.previewData = $sce.trustAsResourceUrl(fileURL);
                }
                else {
                    $timeout(function () { toaster.clear(); toaster.error({ title: response.message }, null, null, null, 10000); }, 0);
                }
            });
        };

