        $scope.InitPage = function () {
            $scope.RequestTypes = [];
            $scope.ClassificationData = [];
            $scope.RequestStatuses = [];
            $scope.Cities = [];
            $scope.VisaTypes = [];
            $scope.ExcludedActvities = [];
            $scope.Nationalities = [];
            $scope.LKUP_RequestsFormsReasons = [];
            $scope.page.TypesThereIsData = false;
            $scope.page.TypesShowLoad = true;
            $scope.page.TypesNoData = false;
            //RequestsClassifications
            NonMembersRequestsSvc.GetRequestTypeSettingById({ Id: $routeParams.id, UserName: $rootScope.userInfo.userName }).then(function (response) {
                if (response.success) {
                    $scope.RequestModel.RequestTypeId = parseInt($routeParams.id);
                    $scope.RequestModel.htmlTempleteUrl = response.data.settings.htmlTempleteUrl;
                    $scope.RequestModel.sendCode = response.data.settings.sendCode;
                    $scope.RequestModel.isAutomatic = response.data.settings.isAutomatic;
                    $scope.RequestModel.requestTypeName = response.data.settings.name;
                    $scope.RequestModel.Amount = response.data.settings.amount;
                    $scope.RequestModel.MaxSelectedOptions = response.data.settings.maxSelectedOptions;
                    $scope.RequestModel.AddAttachment = response.data.settings.addAttachment;
                    $scope.RequestModel.IsAttachment = response.data.settings.isAttachment;
                    $scope.RequestModel.MainAttachmentsNumber = response.data.settings.attachmentsNumber;
                    $scope.RequestModel.AttachmentsNumber = response.data.settings.attachmentsNumber;
                    $scope.RequestModel.ExpireDateInterval = response.data.settings.expireDateInterval;
                    $scope.RequestModel.ShowPrizeAmount = response.data.settings.showPrizeAmount;
                    $scope.RequestModel.ShowObligation = response.data.settings.showObligation;
                    $scope.RequestModel.CanSubmit = response.data.settings.canSubmit;
                    $scope.RequestModel.MaxRequestsCountPerYear = response.data.settings.maxRequestsCountPerYear;
                    $scope.RequestModel.ShowTermsConditions = response.data.settings.showTermsConditions;
                    $scope.RequestModel.TermsConditions = response.data.settings.termsConditions;
                    $scope.RequestModel.IsDirectPay = response.data.settings.isDirectPay;
                    $scope.RequestModel.AdditionalMobileNumber = $rootScope.userInfo.globalSessionValues.UserData.AdditionalMobileNumber
                    $scope.page.DefaultChamberId = response.data.settings.chamberId;

                    $scope.currentRequestTypeName = response.data.settings.name;
                    $scope.page.selectedRequestName = response.data.settings.name;


                    $scope.RequestModel.GridDetails = response.data.gridDetails;
                    $scope.RequestModel.inputsDetails = response.data.inputsDetails;
                    SetInputValidation(response.data.inputsDetails);
                    sessionStorage.setItem('OriginalGridDetails', JSON.stringify(response.data.gridDetails));
                    $scope.formInputs = []
                    let inputsDetails = response.data.inputsDetails
                    let settings = response.data.settings
                    if (settings.isDynamicForm && !$scope.formInputs?.length) {
                        $scope.attachmentsInput = {
                            addAttachment: settings.addAttachment,
                            attachmentExtentions: settings.attachmentExtentions,
                            attachmentList: settings.attachmentList ? JSON.parse(settings.attachmentList) : [],
                            attachmentSize: settings.attachmentSize,
                            attachmentsNumber: settings.attachmentsNumber
                        }

                        if ($scope?.attachmentsInput?.attachmentList) {
                            var requiredAttachments = $scope?.attachmentsInput?.attachmentList?.filter(item => item.IsRequired)?.length
                            $scope.RequestModel.AttachmentsNumber = requiredAttachments
                        }

                        inputsDetails.forEach(input => {
                            // select case ( single & multi)
                            if (input.fieldType == 6 || input.fieldType == 8) {
                                if (input.isReadOnly) return
                                let newInput = { ...input }
                                if (input.options) newInput.options = JSON.parse(input.options)
                                if (newInput.isMultipleChoice) $scope.RequestModel[input.fieldName] = "[]" // default value
                                $scope.formInputs.push(newInput)
                            } else if ((input.fieldType == 2 && input.isReadOnly) || input.fieldType == 7) return // add && input.relatedMatch
                            // boolean case ( toggle )
                            else if (input.fieldType == 4 || input.fieldType == 11) {
                                let existedInputIndex = $scope.formInputs.findIndex(item => item.fieldName == input.relatedMatch || item.fieldName == input.fieldName)
                                if (input.fieldType == 4 && !input.relatedMatch) { // T
                                    input.trueLabel = input.nameAr
                                    existedInputIndex > -1 ? $scope.formInputs[existedInputIndex] = { ...$scope.formInputs[existedInputIndex], ...input, nameAr: $scope.formInputs[existedInputIndex].nameAr } : $scope.formInputs.push({ ...input, nameAr: '' })
                                    $scope.RequestModel[input.fieldName] = false // default value
                                } else if (input.fieldType == 4 && input.relatedMatch) { // F
                                    existedInputIndex > -1 ? $scope.formInputs[existedInputIndex].falseLabel = input.nameAr : $scope.formInputs.push({ falseLabel: input.nameAr, fieldName: input.relatedMatch })
                                    $scope.RequestModel[input.fieldName] = true // default value
                                } else if (input.fieldType == 11) {
                                    existedInputIndex > -1 ? $scope.formInputs[existedInputIndex].nameAr = input.nameAr : $scope.formInputs.push({ nameAr: input.nameAr, fieldName: input.relatedMatch, order: input.order })
                                }
                            }
                            else {
                                $scope.formInputs.push(input)
                            }
                        })
                    }
                    //تحديد رسم grids  الخاصة بالطلب 
                    //ParentName  هو اسم الgrid  التي ينتمي ليها السطر بجدول الجريد
                    //Title  اسم الجريد بقاعدة البيانات 
                    // Headers mean Table Headers
                    //Grid Mean Array of row Columns for each parent grid separately
                    const distinct = (value, index, self) => {
                        return self.indexOf(value) === index;
                    }
                    var arr = [];
                    var GridsParents = $scope.RequestModel.GridDetails.map(function (a) { return a.detailFieldName; }).filter(distinct);

                    angular.forEach(GridsParents, function (val, key) {
                        var obj = {};
                        obj['ParentName'] = val;

                        obj['Title'] = $.grep($scope.RequestModel.GridDetails, function (b) {
                            return b.detailFieldName === val;
                        })[0].detailNameAr;

                        obj['Headers'] = Array.prototype.filter.call($scope.RequestModel.GridDetails, function (b) {
                            if (b.detailFieldName === val) { return b }
                        }).map(function (a) { return a.nameAr; });
                        obj['Grid'] = [{ SmallGrid: [] }];
                        obj['Grid'][0].SmallGrid = $.grep($scope.RequestModel.GridDetails, function (b) {
                            return b.detailFieldName === val;
                        });
                        arr.push(obj);
                    });
                    $scope.GridsArray = arr;
                    $scope.pageTemplates = $scope.RequestModel.htmlTempleteUrl.split(',');
                    $scope.page.template = $scope.pageTemplates[0];

                    $scope.page.thereIsData = true;
                    $scope.page.showLoad = false;
                    $scope.page.NoData = false;

                    $scope.page.wizardData = true;
                    $scope.page.showWizardLoad = false;

                    $scope.page.currentStep = 1;
                } else {
                    $scope.page.wizardData = false;
                    $scope.page.showWizardLoad = false;
                }
            });

        };

        function SetInputValidation(requestInputsDetails) {
            $scope.modelValidation = {};
            var FieldsNames = requestInputsDetails.map(function (a) { return a.fieldName; });

            angular.forEach(FieldsNames, function (val, key) {
                var inputSettings = $.grep(requestInputsDetails, function (b) {
                    return b.fieldName === val;
                })[0];
                angular.forEach(inputSettings, function (k, v) {
                    $scope.modelValidation[val + '_' + v] = inputSettings[v];
                });
            });
        }


        $scope.getRequestTypes = function (classifyId, searchText) {
            $scope.selectedClassify = classifyId;
            if (searchText !== null && searchText !== undefined && searchText !== '') {
                angular.forEach($scope.groupRequests, function (val, key) {
                    val.requests = [];
                    if (val.classifyId === classifyId) {
                        var filteredList = $filter("filter")($scope.RequestTypes2, { name: searchText });
                        val.requests = $.grep(filteredList, function (n, i) {
                            return n.classifyId === classifyId;
                        });
                    }
                });
            }
            else {
                angular.forEach($scope.groupRequests, function (val, key) {
                    val.requests = [];
                    if (val.classifyId === classifyId) {
                        val.requests = $.grep($scope.RequestTypes2, function (n, i) {
                            return n.classifyId === classifyId;
                        });
                    }
                });
            }
        }

