        /////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
        $scope.getCheckedReasons = function (getCount) {
            //for request 52
            $scope.CommitteeDetails = [];
            //null return string , false return array , true return count
            var lst = $filter('filter')($scope.LKUP_RequestsFormsReasons, { requestType: $scope.RequestModel.requestType, isChecked: true });
            angular.forEach(lst, function (v, k) {
                angular.forEach($scope.SectoralCouncilsPrograms, function (vv, kk) {
                    if (vv.nameAr === v.name) {
                        $scope.CommitteeDetails.push({ DetailId: vv.id, Note: v.Note })
                    }
                })
            })
            var arr = [];
            var string = '';
            if (lst.length > 0) {
                string = '';
                angular.forEach(lst, function (value, key) {
                    if (value.Period !== null && value.Period !== undefined && value.Period !== '') {
                        arr.push(value.name + " " + value.Period);
                        string += (key === 0 ? '' : ' - ') + value.name + value.Period;
                    }
                    else if (value.Note !== null && value.Note !== undefined && value.Note !== '') {
                        arr.push(value.name + " " + value.Note);
                        string += (key === 0 ? '' : ' - ') + value.name + '"' + value.Note + '"';
                    }
                    else {
                        arr.push(value.name);
                        string += (key === 0 ? '' : ' - ') + value.name;
                    }

                });
            }
            return getCount === true ? lst.length : (getCount === null ? string : arr);
        };
