        /* Upload Attachment Fn*/
        $scope.selectFileforUpload = function (file) {
            //
            var extentions = 'pdf,jpg,png,jpeg';
            var ext = file[0].name.slice(file[0].name.lastIndexOf('.') + 1).toLowerCase();
            if (extentions.indexOf(ext) > -1) {
                //console.log('exist');
            } else {
                angular.forEach(
                    angular.element("input[type='file']"),
                    function (inputElem) {
                        angular.element(inputElem).val(null);
                    });
                $timeout(function () { toaster.clear(); toaster.error(appConst.fileTypeNotSupported); }, 0);
                $scope.page.currentStep = 2;
                return false;
            }

            $scope.SelectedFileForUpload = file;

            angular.forEach($scope.SelectedFileForUpload, function (val, key) {
                var maxfilesize = $scope.RequestModel.RequestTypeId === 2 ? 5000000 : 2000000;
                var maxfilesizemessage = $scope.RequestModel.requestType === 2 ? "لايمكن اضافة ملف اكبر من 5 ميجا" : "لايمكن اضافة ملف اكبر من 2 ميجا";
                if (val.size > maxfilesize) {
                    $timeout(function () {
                        toaster.clear(); toaster.error(maxfilesizemessage);
                    }, 0);

                    $scope.SelectedFileForUpload = [];
                    angular.forEach(
                        angular.element("input[type='file']"),
                        function (inputElem) {
                            angular.element(inputElem).val(null);
                        });
                    return false;
                }
            });
            $scope.$apply();
        };

