        $scope.addNew = function (benefitDetails) {
            var emptyArr = [];
            emptyArr = $.grep($scope.RequestModel.Benefits, function (n, i) {
                if (n !== null) {
                    return !n.benefitName || !n.benefitId;
                }
            });

            var notValidArr = [];
            notValidArr = $.grep($scope.RequestModel.Benefits, function (n, i) {
                if (n !== null) {
                    if (n.benefitId !== null && n.benefitId !== undefined && n.benefitId !== '') {
                        var FIndex = n.benefitId.charAt(0);
                        if (FIndex > "2" || FIndex === "0") {
                            $timeout(function () {
                                toaster.clear(); toaster.error(appConst.identityNotValid);
                            }, 0);
                            return n.benefitId;
                        }
                        if (n.benefitId.length < 10) {
                            $timeout(function () {
                                toaster.clear(); toaster.error(appConst.identityLength);
                            }, 0);
                            return n.benefitId;
                        }
                    }
                }
            });

            if (emptyArr.length > 0) {
                if (emptyArr.length === $scope.RequestModel.Benefits.length) {
                    $scope.RequestModel.Benefits = [];
                    $scope.RequestModel.Benefits.push({
                        'benefitName': "",
                        'benefitId': ""
                    });
                }
                $timeout(function () { toaster.clear(); toaster.error("فضلاً , ادخل الاسم و رقم هوية   ."); }, 0);
                return false;
            }
            else if (notValidArr.length > 0) {
                angular.forEach(notValidArr, function (v, k) {
                    angular.forEach($scope.RequestModel.Benefits, function (n, i) {
                        if (v.benefitName === n.benefitName && i !== 2) {
                            $scope.RequestModel.Benefits[i].benefitId = null;
                            $scope.RequestModel.Benefits[i].benefitName = null;
                        }
                    });
                });
                return false;
            }
            else if ($scope.RequestModel.Benefits.length <= 2) {
                $scope.RequestModel.Benefits.push({
                    'benefitName': "",
                    'benefitId': ""
                });
            } else {
                $timeout(function () {
                    toaster.clear(); toaster.error("لا يمكن اضافة اكثر من 3 مستفيدين   !  ");
                }, 0);
            }
        };

