        function PrepareUpload(file, AttachmentTypeId, title) {
            var deferred = $q.defer();
            var FinalResponse = { Success: null, Message: null };
            var extentions = ($scope.selectedRequestTypeId !== 59 ? 'pdf,jpg,png,jpeg' : 'pdf');
            angular.forEach(file, function (val, key) {
                var ext = val.name.slice(val.name.lastIndexOf('.') + 1).toLowerCase();
                if (extentions.indexOf(ext) <= -1) {
                    angular.forEach(
                        angular.element("input[type='files']"),
                        function (inputElem) {
                            angular.element(inputElem).val(null);
                        });
                    FinalResponse = { Success: false, Message: appConst.fileTypeNotSupported };
                    // $scope.page.currentStep = 2;
                    file = [];
                    deferred.resolve(FinalResponse);
                    return deferred.promise;
                }
            });

            angular.forEach(file, function (val, key) {
                var maxfilesize = $scope.RequestModel.RequestTypeId === 2 ? 5000000 : 2000000;
                var maxfilesizemessage = $scope.RequestModel.requestType === 2 ? "لايمكن اضافة ملف اكبر من 5 ميجا" : "لايمكن اضافة ملف اكبر من 2 ميجا";
                if (val.size > maxfilesize) {
                    FinalResponse = { Success: false, Message: maxfilesizemessage };
                    angular.forEach(
                        angular.element("input[type='files']"),
                        function (inputElem) {
                            angular.element(inputElem).val(null);
                        });
                    file = [];
                    deferred.resolve(FinalResponse);
                    return deferred.promise;
                }
            });

            if (window.File && window.FileList && window.FileReader) {
                var files = file,
                    filesLength = files.length;
                if ($scope.RequestModel.AttachmentsNumber === 1) {
                    angular.forEach(files, function (val, key) {
                        var gg = $scope.SelectedFileForUpload;
                        $scope.SelectedFileForUpload = [];
                        // $scope.SelectedFileForUpload.push(val);
                        angular.forEach(files, function (v, key) {
                            $scope.SelectedFileForUpload.push(v);
                        });
                    });

                    if ($scope.SelectedFileForUpload.length > 1) {
                        FinalResponse = { Success: false, Message: appConst.uploadOneFilesOnly };
                        $scope.SelectedFileForUpload.splice(0, filesLength);
                        deferred.resolve(FinalResponse);
                        $('input[type="file"]').val(null);
                        return deferred.promise;
                    }
                }
                else {
                    angular.forEach(files, function (val, key) {
                        var gg = $scope.SelectedFileForUpload;
                        $scope.SelectedFileForUpload = [];
                        $scope.SelectedFileForUpload.push(val);
                        angular.forEach(gg, function (v, key) {
                            $scope.SelectedFileForUpload.push(v);
                        });
                    });


                }

                Array.from(files).forEach(f => {
                    var reader = new FileReader();
                    var image = { Name: f.name, Source: [], Src: [], Type: f.type, AttachmentTypeId: AttachmentTypeId, AttachmentTypeName: title };
                    reader.onload = function (e) {

                        if (AttachmentTypeId !== undefined) {
                            image = { Name: f.name, Source: [], Src: e.target.result, Type: f.type, AttachmentTypeId: AttachmentTypeId, AttachmentTypeName: title };
                            angular.forEach($scope.AttachmentTypes, function (v, key) {
                                if (v.Id === AttachmentTypeId)
                                    v.Uploaded = true;
                            });
                        } else {
                            image = { Name: f.name, Source: [], Src: e.target.result, Type: f.type, AttachmentTypeId: 8, AttachmentTypeName: 'مرفق عام' };
                        }
                    };
                    reader.readAsDataURL(f);
                    $timeout(function () {
                        reader = new FileReader();
                        reader.onload = function (e) {
                            $scope.$apply(function () {
                                var array = new Uint8Array(e.target.result);
                                var arr = [];
                                for (var i = 0; i < array.length; i++) {
                                    arr.push(array[i]);
                                }

                                if (arr.length > 0) {
                                    image.Source = arr;
                                    if ($scope.RequestModel.AttachmentsNumber === 1) {
                                        $scope.imagesList = [];
                                    }
                                    $scope.imagesList.push(image);
                                    //stop Check Duplicate file by name
                                    // $scope.imagesList.find(v => v.Name === f.name) !== null ? $scope.imagesList.find(v => v.Name === f.name).Source = arr : [];
                                }
                            });
                        };
                        reader.readAsArrayBuffer(f);
                    });
                });

                $('input[type="file"]').val(null);
                FinalResponse = { Success: true, Message: 'sucess load files ' };
                deferred.resolve(FinalResponse);
                return deferred.promise;

            } else {
                FinalResponse = { Success: false, Message: appConst.fileAPINotSupported };
                deferred.resolve(FinalResponse);
                return deferred.promise;
            }
        }
