        $scope.pintype = function (id) {
            var constantCount = 0;
            var existbefore = false;
            angular.forEach($scope.RequestTypes2, function (item) {
                if (item.isConstant === true)
                    constantCount = constantCount + 1;
                if (item.id === id && item.isConstant === true) {
                    existbefore = true;
                }
            });
            if (constantCount >= appConst.pinedRequestsCount || existbefore) {
                if (existbefore) {
                    $timeout(function () { toaster.clear(); toaster.note(" نوع الطلب مثبت مسبقا"); }, 0);
                    return false;
                } else {
                    $timeout(function () { toaster.clear(); toaster.warning("لا يمكن تثبيت اكثر من " + appConst.pinedRequestsCount + " أنواع طلبات"); }, 0);
                    return false;
                }
            } else {
                $scope.submitpin(id);
            }
        };

