app.controller('WSSPAYWalletConfirmPaymentController', ['$rootScope', '$routeParams', 'blockUI', '$interval', '$http', '$scope', 'NonMembersRequestsSvc', 'appConst', 'toaster',
    function ($rootScope, $routeParams, blockUI, $interval, $http, $scope, NonMembersRequestsSvc, appConst, toaster) {

        $rootScope.title = "تأكيد الدفع ";
        $rootScope.NavigationTitle = 'تأكيد الدفع ';
        $scope.loadingResult = true;
        $scope.Refernce_no = $routeParams.id;


        // to remove history 

        history.pushState(null, document.title, location.href);
        window.addEventListener('popstate', function (event) {
            history.pushState(null, document.title, location.href);
        });

        WSS_VERIFY();

        function WSS_VERIFY() {
            $scope.paymentReferenceKey = $routeParams.paymentReferenceKey;
            $scope.paymentStatus = $routeParams.paymentStatus;
            $scope.guid = $routeParams.guid;

            var config = {
                headers: {
                    'Content-Type': 'application/json;charset=utf-8;x-www-form-urlencoded;',
                    dataType: 'json',
                    Authorization: appConst.wssPayAuthorization
                }
            };

            $scope.error_obj = {};
          
            $http.get(appConst.wssPayUrl + '/api/v1/Payment/Verify/' + $routeParams.paymentReferenceKey, config)
                .then(function successCallback(response) {
                    if (response.data.data === null && response.data.code === 3) {
                        $scope.loadingResult = false;
                        $scope.showResult = false;
                        $scope.Message = 'تم إلغاء العملية';
                        $scope.noResult = true;
                        return false;
                    }
                    switch (response.data.data.paymentStatusName) {
                        case 'Success':
                            NonMembersRequestsSvc.UpdateRequest({
                                Guid: $scope.guid, PaymentRefrenceId: response.data.data.paymentRefrenceId,
                                PaymentReferenceKey: $routeParams.paymentReferenceKey, Status: appConst.NonMemberRequestPaidStatus,
                                PaymentCompany: response.data.data.company, IsPortal: true
                            }).then(function successCallback(response) {
                                blockUI.stop();
                                if (response.success) {
                                    $scope.loadingResult = false;
                                    $scope.showResult = true;
                                    $scope.counter = 20;
                                    //   $interval(function () { console.log($scope.counter--) }, 1000);
                                } else {
                                    toaster.clear();
                                    $scope.loadingResult = false;
                                    toaster.error({ title: response.message });
                                    return false;
                                }
                            }, function errorCallback(response) {

                            });
                            break;
                        case 'Failed' || 'TechnincalError' || 'SessionTimeOut' || 'Canceled':
                            $scope.showResult = false;
                            $scope.loadingResult = false;
                            $scope.Message = appConst.NonMembersFailedPayment;
                            $scope.noResult = true;
                            break;
                        //case 'Initiated':
                        //    break;
                        default:
                    }

                }, function errorCallback(response) {
                    // ngNotify.set(' لم يتم استكمال عملية الدفع , برجاء التواصل مع الدعم الفنى', {
                    //    position: 'top',
                    //    type: 'error'
                    //});
                    //  $route.reload();
                    var h = { field: 'خطأ : ', error_str: 'لم يتم استكمال عملية الدفع , برجاء التواصل مع الدعم الفنى' };
                    $scope.error_obj.currentField.push(h);
                    $scope.SadadErrors.push(h.field + ' ' + h.error_str);
                    $scope.DataSuccessFound = false;
                });
        }

        $scope.$watch('counter', function (newValue, oldValue) {
            if (newValue === 0) {
                //    window.location.href = "/#/Non-Members/Home/2"; 
            }
        });


        //to prevent user refresh or access same action 
        //if ($window.localStorage[$routeParams.id])
        //    $location.path('/Home');
        // window.localStorage.setItem($routeParams.id, $location.$$url);

        //sharedService.GetWalletBalance().then(function (response) {
        //    if (!response) {
        //        authService.logOut();
        //    } else {
        //        $scope.loadingResult = false;
        //        if ($location.$$url.includes('Failed')) {
        //            $scope.showResult = false;
        //            $scope.Message = appConst.FailedPayment;
        //            $scope.noResult = true;
        //        }
        //        else
        //            $scope.showResult = true;

        //        $scope.noResult = false;
        //        if ($window.localStorage["ReturnToAddComPartner"]) {
        //            $scope.ReturnToAddComPartner = JSON.parse($window.localStorage["ReturnToAddComPartner"]);
        //            $window.localStorage.removeItem('ReturnToAddComPartner');
        //            $location.path('/CommercialPartner/AddSubscribtion');
        //        }
        //    }
        //});

        $scope.goToWalletCharge = function (from) {
            if ($scope.payForm) $scope.payForm.$setPristine();
            if (from === 1) {
                window.open('/#/WalletCharge', "_self");

            }
            else if (from === 2) {
                $scope.isSet = 2;
                $scope.creditCard.sadadAmount = '';
                $scope.creditCard.sadadName = '';
                $scope.SadadDataSuccessFound = false;
                $scope.SadadErrors = [];

            }
            else {
                window.open('/#/WalletCharge', "_self");
            }
            return true;
        };

        $scope.goToWalletTransactions = function () {
            if ($scope.payForm) $scope.payForm.$setPristine();
            window.open('/#/WalletsTrans', "_self");
            return true;
        };
        //
        $scope.errorMessages = [
            { message: 'تم إنشاء العملية', error: 'Initiated' },
            { message: 'تم الدفع بنجاح', error: 'Success' },
            { message: 'فشلت عملية الدفع , برجاء المحاولة مرة أخري', error: 'Failed' },
            { message: 'خطأ تقني - تواصل مع الدعم', error: 'TechnincalError' },
            { message: 'فشلت عملية الدفع - تم إنتهاء الوقت المسموح', error: 'SessionTimeOut' },
            { message: 'ملغاة', error: 'Canceled' }
        ];


    }]);
