app.controller('InstrumentDetailsController', ['$rootScope', 'ProfileSvc', 'globalService', '$routeParams', 'renderFile', 'AllRequestSvc', 'ngProgress', '$sce', '$scope', 'toaster', '$timeout', 'session', '$location', '$anchorScroll',
    function ($rootScope, ProfileSvc, globalService, $routeParams, renderFile, AllRequestSvc, ngProgress, $sce, $scope, toaster, $timeout, session, $location, $anchorScroll) {

        $rootScope.NavigationTitle = 'تفاصيل السند';
        $rootScope.title = 'تفاصيل السند';

        $scope.page = {
            noData: false,
            thereIsData: false,
            showLoad: false,
            CurrentPage: 1,
            documentsCount: 0,
            showSpinner: false,
            transItemsPerPage: 10,
            documentNoData: false,
            documentThereIsData: false,
            documentshowLoad: false,
            showAdvancedFilter: false,
            showSigTable: false,
            authorizedSignature: [],
            existdata: false,
            nodata: true,
            NoData: false,
            objects: [],
            showViewerjs: false,
            pdfContent: '',
            pdfClass: [],
            showEditFields: false,
            itemsPerPage: 10,
            ownersThereIsData: false,
            ownersShowLoad: false,
            ownersNoData: false
        };


        $scope.printTemplate = {};
        $scope.memberData = {};
        $scope.RequestModel = {};
        $scope.memberOwners = [];
        $scope.editMemberModel = {};
        $scope.documentsList = [];
        $scope.Cities = [];
        $scope.MainCities = [];
        $scope.tab = 1;
        $scope.userName = $rootScope.UserName;

        //  $rootScope.IsAdmin = session.getPropertyLocalStorage("IsAdmin", false);

        $scope.showPartial = function (tabId) {
            $scope.tab = tabId;
            if (tabId === 2) {
                $scope.showPdf();
            }
        };
        $scope.isSet = function (tabId) {
            return $scope.tab === tabId;
        };


        $scope.getMemberData = function () {
            $scope.page.thereIsData = false;
            $scope.page.showLoad = true;
            $scope.page.showEditFields = false;
            $scope.page.showSpinner = true;
            ngProgress.start();
            ProfileSvc.GetMemberData().then(function (response) {
                if (response.success) {
                    $scope.memberData = response.data;
                    $scope.details();
                    ngProgress.complete();

                } else {
                    $scope.page.noData = true;
                    $scope.page.thereIsData = false;
                    $scope.page.showSpinner = false;
                    ngProgress.complete();
                }
            });
        };


        $scope.details = function () {
            $scope.htmlPage = "";

            ngProgress.start();
            $scope.page.thereIsData = false;
            $scope.page.noData = false;
            $scope.page.showLoad = true;
            $scope.RequestModel = null;
            AllRequestSvc.Details({ Guid: $routeParams.id }).then(function (response) {
                if (response.success) {
                    try {
                        $scope.RequestModel = $scope.capitalizeObject(response.data.model);
                        $scope.RequestModel.OpenPdf = $scope.capitalizeObject(response.data.openPdf);
                        $scope.RequestModel.HtmlTempleteUrl = response.data.htmlTempleteUrl;
                        $scope.IsOnlyForPrint = response.data.isOnlyForPrint;
                        $scope.isAttachment = response.data.isAttachment;
                        $scope.isMultipleDownload = response.data.isMultipleDownload;


                        $scope.printTemplate.contentValue = (!response.data.model.isAttachment) ?
                            $sce.trustAsHtml(response.data.html) : $sce.trustAsResourceUrl('data:application/pdf;base64,' + response.data.openPdf.attachmentImage);

                        $rootScope.title = $scope.IsOnlyForPrint === true ? 'طباعة' : 'تحميل';

                        $scope.cityId = response.data.model.mM_AdrCity;
                        angular.forEach($scope.Cities, function (val, key) {
                            if ($scope.cityId === val.id) {
                                $scope.RequestModel.mM_AdrCity = val.name;
                            }
                        });

                        //dynamic grid settings
                        const distinct = (value, index, self) => {
                            return self.indexOf(value) === index;
                        }

                        if (response.data.model.requestType !== 57) {
                            var GridsParents = response.data.gridDetails.map(function (a) { return a.detailFieldName; }).filter(distinct);
                            angular.forEach(GridsParents, function (val, key) {
                                var obj = {};
                                obj['Title'] = $.grep(response.data.gridDetails, function (b) {
                                    return b.detailFieldName === val;
                                })[0].detailNameAr;
                                obj['Headers'] = Array.prototype.filter.call(response.data.gridDetails, function (b) {
                                    if (b.detailFieldName === val) { return b }
                                }).map(function (a) { return a.nameAr; });
                                obj['Rows'] = $scope.RequestModel[val].length;
                                obj['Values'] = $scope.RequestModel[val];
                                $scope.RequestModel.GridsList.push(obj);
                            });
                        }

                        $scope.imagesList = [];
                        if ($scope.RequestModel.OpenPdf !== null) {
                            $scope.previewData = globalService.LoadPDFWithAnnotation(response.data.openPdf.attachmentImage, null, false, "pdf-container");
                        }

                        $scope.page.noData = false;
                        $scope.page.thereIsData = true;
                        $scope.page.showLoad = false;
                        ngProgress.complete();
                    } catch (e) {
                    }
                }
                else {

                    $scope.page.showDownloadAlert = response.code === 67 ? true : false; // مع طلب شهادة عضوية لعرض رسالة مختلفة 

                    $scope.page.noData = true;
                    $scope.page.showLoad = false;
                    $scope.page.thereIsData = false;
                    ngProgress.complete();
                }
            });
        };

        $scope.InstrumentDownload = function () {
            $scope.IsDownloading = true;
            try {
                AllRequestSvc.DownloadInstrument({
                    Html: '',
                    RequestId: $scope.RequestModel.RequestId, MemberId: $scope.RequestModel.MemberId,
                    Guid: $scope.RequestModel.Guid, ChamberDomain: window.location.origin,
                    EstName: $scope.memberData.estName,
                    DegreeName: $scope.memberData.degreeName,
                    ExpiryDate: $scope.memberData.expiryDate,
                    CityName: $scope.memberData.cityName,
                    CrNumber: $scope.memberData.crNumber,
                    CrExpiryDate: $scope.memberData.crExpiryDate,
                    PaymentSystem: $scope.RequestModel.PaymentSystem,
                    RequiredPagesToAttestation: $scope.RequestModel.RequiredPagesToAttestation,
                    ActualPagesAttestated: $scope.RequestModel.ActualPagesAttestated,
                    ServiceAmount: $scope.RequestModel.ServiceAmount,
                    RatificationType: $scope.RequestModel.RatificationType,
                    InstrumentNum: $scope.RequestModel.InstrumentNum,
                    RequestDate: $scope.RequestModel.RequestDate,
                    IdentityNo: $scope.RequestModel.IdentityNo,
                    ChamberId: $rootScope.userInfo.globalSessionValues.ChamberData.ChamberId
                }).then(function (_response) {
                    if (_response.success) {
                        //function to download file pdf
                        if (_response.data.fileData === null) {
                            $scope.IsDownloading = false;
                            toaster.clear();
                            toaster.pop('error', appConst.errorOccurred);
                            ngProgress.complete();
                            return false;
                        }
                        globalService.fileDownload(_response.data.fileData, $scope.RequestModel.RequestId);
                        toaster.clear();
                        toaster.pop('success', 'تم تحميل السند بنجاح');
                        ngProgress.complete();
                    } else {
                        ngProgress.complete();
                        $scope.IsDownloading = false;
                        toaster.clear();
                        toaster.pop('error', _response.message);
                    }
                    $scope.IsDownloading = false;
                    angular.element(document.querySelector("#tblInfo")).attr("class", "table-responsive custom-table white-bg p-bottom-sm");
                });

            } catch (e) {
            }

        };

        $scope.capitalizeObject = function (model) {
            var key, keys = Object.keys(model);
            var n = keys.length;
            var newobj = {};
            while (n--) {
                key = keys[n];
                newobj[key.charAt(0).toUpperCase() + key.substr(1)] = model[key];
            }
            model = newobj;
            return model;
        };

        /*  DownloadImage */
        $scope.documentImageDownload = function (id, name) {
            ProfileSvc.DocumentImageDownload({ MemberDocumentID: id }).then(function (response) {
                if (response.success) {
                    renderFile.init({ data: response.data, type: name.substr(name.length - 3), name: name });
                }
            });
        };

        $scope.showPdf = function () {
            $scope.page.existdata = false;
            $scope.page.showLoad = true;
            $scope.page.showViewerjs = true;
            $scope.page.showSpinner = true;
            ngProgress.start();
            ProfileSvc.CreatePdf().then(function (response) {
                if (response.success) {
                    $scope.page.showViewerjs = true;
                    $scope.pdfContent = $sce.trustAsResourceUrl('data:application/pdf;base64,' + response.data);
                    $scope.page.pdfClass.push('cloading');
                    fetch(`data:application/pdf;base64,${response.data}`)
                        .then(response => response.blob())
                        .then(blob => {
                            document.querySelector("iframe").src = URL.createObjectURL(blob)
                        })
                    $timeout(function () {
                        $scope.page.showSpinner = false;
                        $scope.page.existdata = true;
                        $scope.page.showLoad = false;
                        $scope.page.showViewerjs = false;
                        ngProgress.complete();
                    }, 5000);
                    $timeout(function () {
                        $scope.page.pdfClass.pop('cloading');
                        ngProgress.complete();
                    }, 8000);

                } else {
                    $scope.page.noData = true;
                    $scope.page.existdata = false;
                    $scope.page.showSpinner = false;
                    $scope.page.showViewerjs = false;
                    $scope.page.pdfUrl = "";
                    ngProgress.complete();
                }
            });
        };
        /* add watch to view pdf if  its tab is active */
        $scope.$watch('$scope.tab', function handleFoChange() {
            if ($scope.tab === 2) {
                $scope.showPdf();
            } else {
                $scope.showViewerjs = false;
                $scope.pdfUrl = "";
            }
        });

        $scope.downloadInst = function () {

            html2canvas(document.getElementById('contentDiv'), {
                onrendered: function (canvas) {
                    var data = canvas.toDataURL();
                    var docDefinition = {
                        content: [{
                            image: data,
                            width: 500,
                        }]
                    };
                    pdfMake.createPdf(docDefinition).download("test.pdf");
                }
            });
        }

        $scope.printDiv = function (divName) {
            $scope.Date = new Date();
            var innerContents = document.getElementById(divName).innerHTML;
            var popupWinindow = window.open('', 'width=600,height=700,scrollbars=no,menubar=no,toolbar=no,location=no,status=no,titlebar=no');
            popupWinindow.document.open();
            popupWinindow.document.write('<html><head>  <link href="../Content/Theme/dist/css/bootstrap.min-ar.css" rel="stylesheet"/> <link href="../Content/angular-ui-switch.min.css" rel="stylesheet"/><link href="https://maxcdn.bootstrapcdn.com/font-awesome/4.6.3/css/font-awesome.min.css" rel="stylesheet" type="text/css" /> <link href="../Content/Theme/dist/css/bootstrap-dropdown-multilevel.css" rel="stylesheet" /><link href="../Content/Theme/dist/css/plugins-rtl.css" rel="stylesheet" /><link href="../Content/Theme/dist/css/components-rtl.css" rel="stylesheet" /> <link href="../Content/Theme/dist/css/style.css" /> <script src="../Content/Theme/dist/js/jquery-3.2.1.min.js"></script><script src="../Content/Theme/dist/js/bootstrap.min.js"></script><script src="../Content/Theme/dist/js/main.js"></script><script src="../Scripts/angular.js"></script><script src="../Scripts/angular-animate.js"></script><script src="../Scripts/angular-ui/ui-bootstrap.js"></script> </head>');
            popupWinindow.document.write('<body  onload=" window.print();">' + innerContents + '</body></html>');
            popupWinindow.document.close();




        };

        // Initialize Data 
        $scope.Init = function () {
            $scope.getMemberData();
            //  $scope.details();
        };

        $scope.Init();


    }]);
;

"use strict";
app.controller('TransferController', ['$rootScope', '$sce', 'UsersSvc', 'sharedService','$location', '$scope', '$interval', 'blockUI', 'WalletSvc', 'ngProgress', '$timeout', 'toaster', '$q', '$route', 'session',
    function ($rootScope, $sce, UsersSvc, sharedService,$location,$scope, $interval, blockUI, WalletSvc, ngProgress, $timeout, toaster, $q, $route, session) {

        $rootScope.title = "تحويل من المحفظة";
        $rootScope.NavigationTitle = 'تحويل من المحفظة';
        $scope.page = {
            noData: false,
            thereIsData: false,
            showLoad: false,
            isLoading: false,
            firstStep: true,
            secondStep: false,
            thirdStep: false
        };

        //التحقق من وجود صلاحية التحويل
        $scope.hasAccess = false;
        if (!$rootScope.userInfo.globalSessionValues.ChamberData.AllowPortalWalletTransfer) {
            return false;
        }
        if ($rootScope.userInfo.globalSessionValues.CurrentMember != null) {
            if ($rootScope.userInfo.globalSessionValues.CurrentMember.IsAdmin) {
                $scope.hasAccess = true;
            } else {
                var privleges = $rootScope.userInfo.globalSessionValues.CurrentMember.Privileges;
                if (privleges !== null && privleges !== undefined && privleges !== '') {
                    if (privleges.indexOf('AllowUserWalletTransfer') !== -1) {
                        $scope.hasAccess = true;
                    }
                }
            }
        }

        if (!$scope.hasAccess) {
            return false;
        }


        $scope.model = {
            MemberId: session.getPropertyLocalStorage('CurrentMember.MemberId', false), 
            EstName: session.getPropertyLocalStorage('CurrentMember.EstName', false),
            AvailableBalance: $rootScope.userInfo.globalSessionValues.CurrentMember.Balance - $rootScope.userInfo.globalSessionValues.ReservedBalance,
            ToMember: null,  // العضوية المُحول إليها
            Amount: 0,
            MemberType: "1",
            ToEstName: null // العضوية المُحول إليها
        }
        $scope.MembersType = [{ key: 1, name: 'مالك' }, { key: 2, name: 'مفوض' }]
        $scope.MembersList = [];
        $scope.Sms = { TrackId: null, Code: null, CodeSent: false };


        ////////////////////////////////////////////////////////////////////////////////////
        $scope.loadMembers = function (type) {
            $scope.MembersList = [];
            $scope.page.thereIsData = false;
            $scope.page.showLoad = true;
            ngProgress.start();
            blockUI.start();
            UsersSvc.GetIdentityRelatedDelegatedMembersGrid().then(function (response) {
                blockUI.stop();
                ngProgress.complete();
                if (response.success) {
                    //$scope.MembersList = response.data.map(function (obj) {
                    //    obj.relation = obj.relatedType == 1 ? 'العضويات التابعة' : 'العضويات المُفوضة';
                    //    return obj.memberId != $scope.model.MemberId;
                    //});

                    $scope.MembersList = response.data.filter(function (obj) {
                        return $rootScope.chamberSettings.isUnified ? obj.memberId != $scope.model.MemberId && obj.checked == true && obj.chamberId == $rootScope.userInfo.globalSessionValues.CurrentMember.ChamberId
                            : obj.memberId != $scope.model.MemberId && obj.checked == true;
                    }).map(function (obj) {
                        obj.relation = obj.relatedType == 1 ? 'العضويات التابعة' : 'العضويات المُفوضة';
                        return obj;
                    })

                    $scope.page.thereIsData = true;
                    $scope.page.noData = false;
                    $scope.page.showLoad = false;

                } else {
                    $scope.page.noData = true;
                    $scope.page.thereIsData = false;
                    $scope.page.showLoad = false;
                }
            });
        }
        ////////////////////////////////////////////////////////////////////////////////////

        $scope.validateTransfer = function (form, event) {
            //validate balance & send sms
            $scope.isFormSubmitted = true;
            event.preventDefault();

            if ($scope.model.MemberId !== session.getPropertyLocalStorage('CurrentMember.MemberId', false)) {
                $timeout(function () {
                    toaster.clear(); toaster.error({ title: 'تم تغيير العضوية الحالية للحساب , يرجي إعادة تحديد العضوية ' }, null, null, null, 1000);
                   // $location.path('/Landing');
                }, 0);
                return false;
            }

            if (!form.$valid) {
                return false;
            }
            if ($scope.model.Amount <= 0 || $scope.model.Amount == null || $scope.model.Amount == undefined) {
                toaster.error({ title: 'يرجي إدخال مبلغ التحويل أكبر من 0' });
                return false;
            }

            if ($scope.model.Amount > $scope.model.AvailableBalance) {
                toaster.error({ title: 'المبلغ المدُخل أكبر من الرصيد المتوفر' });
                return false;
            }

            $scope.page.isLoading = true;
            blockUI.start();
            $scope.Sms.Code = null;
            $scope.smsInputs = [{ id: 3, value: null }, { id: 2, value: null }, { id: 1, value: null }, { id: 0, value: null }];

            $timeout(function () {
                WalletSvc.ValidateTransfer($scope.model).then(function successCallback(response) {
                    $scope.page.isLoading = false;
                    blockUI.stop();
                    if (response.success) {
                        $scope.page.firstStep = false;
                        $scope.page.secondStep = true;
                        $scope.page.thirdStep = false;
                        $scope.Sms.TrackId = response.data;
                        $scope.Sms.CodeSent = true;
                        smsTimer();
                    } else {
                        $scope.page.firstStep = true;
                        $scope.page.secondStep = false;
                        $scope.page.thirdStep = false;
                        toaster.error({ title: response.message });
                    }
                }, function errorCallback(response) {
                    toaster.error({ title: response.message });
                    if (response.data.execptionMessage) {
                        toaster.error({ title: response.execptionMessage });
                    }
                    $scope.Sms.CodeSent = false;
                    $timeout(function () { blockUI.stop(); }, 100);
                });
            }, 800);
        }



        $scope.confirmTransfer = function () { 
            if ($scope.model.MemberId !== session.getPropertyLocalStorage('CurrentMember.MemberId', false)) {
                $timeout(function () {
                    toaster.clear(); toaster.error({ title: 'تم تغيير العضوية الحالية للحساب , يرجي إعادة تحديد العضوية ' }, null, null, null, 1000);
                   // $location.path('/Landing');
                }, 0);
                return false;
            }
            //validate balance & send sms
            var details = {
                MemberId: $scope.model.MemberId, // العضوية المُحول منها
                EstName: $scope.model.EstName,  // العضوية المُحول منها
                ToMember: $scope.model.ToMember,  // العضوية المُحول إليها
                ToEstName: $scope.MembersList.filter(x => x.memberId === $scope.model.ToMember)[0].estName, // العضوية المُحول إليها
                Amount: $scope.model.Amount,
                SMS: {
                    Code: $scope.Sms.Code,
                    TrackId: $scope.Sms.TrackId
                }
            };

            blockUI.start();
            WalletSvc.ConfirmTransfer(details).then(function (response) {
                blockUI.stop();
                if (response.success) {
                    $scope.page.firstStep = false;
                    $scope.page.secondStep = false;
                    $scope.page.thirdStep = true;
                } else {
                    $scope.page.firstStep = false;
                    $scope.page.secondStep = true;
                    $scope.page.thirdStep = false;
                    $timeout(function () {
                        toaster.clear(); toaster.error({ title: response.message }, null, null, null, 1000);
                       // $location.path('/Wallet/Transfer');
                        $route.reload();
                    }, 0);
                    return false;
                }
            });
        }

        $scope.back = function () {
            $scope.page.firstStep = true;
            $scope.page.secondStep = false;
            $scope.page.thirdStep = false;
            $scope.Sms.CodeSent = false;
            $scope.Sms.Code = null;
            $scope.smsInputs = [{ id: 3, value: null }, { id: 2, value: null }, { id: 1, value: null }, { id: 0, value: null }];
        }

        //Combine SMS Code from front to one string value to be validated
        $scope.combineCode = function (digit, index) {
            toaster.clear();
            if (digit !== null) {
                $scope.Sms.Code = ($scope.Sms.Code === null) ? 'xxxx' : $scope.Sms.Code;
                var a = $scope.Sms.Code.split('');
                a[$scope.smsInputs.length - index - 1] = digit.value;
                $scope.Sms.Code = a.join('');
                if ($scope.Sms.Code !== undefined && $scope.Sms.Code !== null && $scope.Sms.Code !== '') {
                    if ($scope.Sms.Code.toString().indexOf('x') === -1) {
                        if ($scope.page.secondStep === true && $scope.Sms.Code.length === 4) {
                            //Validate SMS Code 
                            $scope.page.isLoading = true;
                            $scope.isFormSubmitted = true;
                            $timeout(function () { $scope.confirmTransfer(); }, 300);
                        }

                    }
                }
            }
        }


        ////////////////////////////////////////////////////////////////////////////////////
        $scope.sanitizeMe = function (text) {
            return $sce.trustAsHtml(text);
        };
        $scope.reload = function () {
            //$scope.model = {
            //    MemberId: session.getPropertyLocalStorage('CurrentMember.MemberId', false),
            //    EstName: session.getPropertyLocalStorage('CurrentMember.EstName', false),
            //    AvailableBalance: $rootScope.userInfo.globalSessionValues.CurrentMember.Balance - $rootScope.userInfo.globalSessionValues.ReservedBalance,
            //    ToMember: null,  // العضوية المُحول إليها
            //    Amount: 0,
            //    MemberType: "1",
            //    ToEstName: null // العضوية المُحول إليها
            //}
            sharedService.GetWalletBalance();
            $timeout(function () {
                //toaster.clear(); toaster.error({ title: response.message }, null, null, null, 1000);
                // $location.path('/Wallet/Transfer');
                $route.reload();
            }, 100);
           // $route.reload();
        };

        //Count down timer
        function smsTimer() {
            $scope.page.smsTimer = 120;
            $scope.page.showSmsTime = true;
            $interval(decrementCountdown, 1000, $scope.page.smsTimer);
        }

        var decrementCountdown = function () {
            $scope.page.showSmsTime = true;
            $scope.page.smsTimer -= 1;
            if ($scope.page.smsTimer < 1) {
                $scope.page.showSmsTime = false;
                $scope.page.smsTimer = 0;
            }
        };

        // Reset Form Model
        $scope.Reset = function () {
            $scope.Sms.Code = null;
            $scope.smsInputs = [{ id: 3, value: null }, { id: 2, value: null }, { id: 1, value: null }, { id: 0, value: null }];
        }
        ////////////////////////////////////////////////////////////////////////////////////
        //init dropdownlist
        $scope.loadMembers($scope.model.MemberType);

    }]);
;
"use strict";
app.controller('IntegratrionIndexController', ['$rootScope', 'IntegrationSvc', 'renderFile', 'NgMap', 'globalService', '$scope', 'toaster', '$timeout', 'session', '$location', '$anchorScroll',
    function ($rootScope, IntegrationSvc, renderFile, NgMap, globalService, $scope, toaster, $timeout, session, $location, $anchorScroll) {

        $rootScope.NavigationTitle = 'بيانات العضوية ';
        $rootScope.title = "بيانات العضوية";
        $scope.thereIsData = false;
        $scope.showLoad = false;
        $scope.noData = false;
        $scope.showActivityAlert = false;
        $scope.image = { Url: null, Array: [] };

        $scope.AddModel = {
            Header: {
                Id: null,
                MemberId: session.getPropertyLocalStorage('CurrentMember.MemberId', false),
                EstName: session.getPropertyLocalStorage('CurrentMember.EstName', false),
                Logo: null,
                LogoUrl: null,
                Website: null,
                Twitter: null,
                Instagram: null,
                Whatsapp: null,
            },
            Branches: []
        }
        //session.getPropertyLocalStorage('CurrentMember.Mobile', false)
        //session.getPropertyLocalStorage('CurrentMember.PhoneNumber', false)
        //session.getPropertyLocalStorage('CurrentMember.Email', false)

        $scope.Branch = {
            Id: null,
            ChamberId: null,
            HeaderId: null,
            BranchName: null,
            IsDefault: null,
            BranchDetails: {
                Id: null,
                BranchId: null,
                CityId: null,
                PhoneNumber: null,
                PhoneNumberList: [],
                Mobile: null,
                MobileList: [],
                Email: null,
                EmailList: [],
                Address: null,
                Lat: null,
                Lng: null
            }
        }

        $scope.clat = 23.844585547409892;
        $scope.clng = 45.560568035553864;
        $scope.positions = [{ lat: 23.844585547409892, lng: 45.560568035553864 }];


        ///////////////////////////////////////////////////////////////////////////////////////////////

        function GetData() {
            IntegrationSvc.GetDetails().then(function (response) {
                $scope.thereIsData = false;
                $scope.showLoad = true;
                if (response.success) {
                    if (response.data) {
                        if (response.data.length === 0) {
                            $scope.Branch.BranchDetails.Mobile = session.getPropertyLocalStorage('CurrentMember.Mobile', false);
                            $scope.Branch.BranchDetails.PhoneNumber = session.getPropertyLocalStorage('CurrentMember.PhoneNumber', false);
                            $scope.Branch.BranchDetails.Email = session.getPropertyLocalStorage('CurrentMember.Email', false);
                            $scope.Branch.BranchName = 'الفرع الرئيسي';
                            $scope.Branch.IsDefault = true;
                            $scope.AddModel = {
                                Header: {
                                    Id: null,
                                    MemberId: session.getPropertyLocalStorage('CurrentMember.MemberId', false),
                                    EstName: session.getPropertyLocalStorage('CurrentMember.EstName', false),
                                    Logo: null,
                                    Website: null,
                                    Twitter: null,
                                    Instagram: null,
                                    Whatsapp: null,
                                },
                                Branches: [$scope.Branch]
                            }
                            $scope.AddModel.Branches[0].BranchDetails.PhoneNumberList.push('');
                            $scope.AddModel.Branches[0].BranchDetails.EmailList.push('');
                            $scope.AddModel.Branches[0].BranchDetails.MobileList.push('');
                            $timeout(function () {
                                NgMap.initMap('takamolMap');
                            }, 600)
                        } else {
                            var data = $scope.capitalizeObject(response.data[0]);

                            $scope.AddModel = {
                                Header: {
                                    Id: data.Id,
                                    MemberId: data.MemberId,
                                    EstName: session.getPropertyLocalStorage('CurrentMember.EstName', false),
                                    Logo: data.Logo,
                                    LogoUrl: 'data:image/png;base64,' + data.Logo,
                                    Website: data.Website,
                                    Twitter: data.Twitter,
                                    Instagram: data.Instagram,
                                    Whatsapp: data.Whatsapp,
                                },
                                Branches: []
                            };

                            $scope.AddModel.Branches.push({
                                Id: data.BranchId,
                                ChamberId: data.ChamberId,
                                HeaderId: data.Id,
                                BranchName: data.BranchName,
                                IsDefault: data.IsDefault,
                                BranchDetails: {
                                    Id: data.DetailId,
                                    BranchId: data.BranchId,
                                    CityId: data.CityId,
                                    PhoneNumber: data.PhoneNumber,
                                    PhoneNumberList: [],
                                    MobileList: [],
                                    EmailList: [],
                                    Mobile: data.Mobile,
                                    Email: data.Email,
                                    Address: data.Address,
                                    Lat: data.Lat,
                                    Lng: data.Lng
                                }
                            });

                            $scope.AddModel.Branches[0].BranchDetails.PhoneNumberList = data.PhoneNumber?.split(',');
                            $scope.AddModel.Branches[0].BranchDetails.EmailList = data.Email?.split(',');
                            $scope.AddModel.Branches[0].BranchDetails.MobileList = data.Mobile?.split(',');

                            $scope.positions = [{ pos: [data.Lat, data.Lng], name: "الموقع الحالى" }];

                        }
                        //$scope.AddModel = $scope.capitalizeObject(response.data); 
                        // $scope.image = { Url: 'data:' + $scope.AddModel.AttachmentType + ';base64,' + $scope.AddModel.Slogan, Array: convertDataURIToBinary($scope.AddModel.Slogan), AttachmentType: $scope.AddModel.AttachmentType };

                    }


                    //add slogan and type to image object to be seen in screen
                    $scope.thereIsData = true;
                    $scope.showLoad = false;
                } else {
                    toaster.error(response.message);
                    $scope.thereIsData = true;
                    $scope.showLoad = false;
                }
            });
        }
        /////////////////////////////////////////////////////////////////////////////////////////////////
        //1 Phone, 2 Email, 3 Mobile
        $scope.addRemoveInput = function (type, isAdd, index) {
            switch (type) {
                case 1:
                    if (isAdd) {
                        if ($scope.AddModel.Branches[0].BranchDetails.PhoneNumberList.length < 3) {
                            $scope.AddModel.Branches[0].BranchDetails.PhoneNumberList.push('');
                        }
                    } else {
                        $scope.AddModel.Branches[0].BranchDetails.PhoneNumberList.splice(index, 1);;
                    }
                    break;
                case 2:
                    if (isAdd) {
                        if ($scope.AddModel.Branches[0].BranchDetails.EmailList.length < 3) {
                            $scope.AddModel.Branches[0].BranchDetails.EmailList.push('');
                        }
                    } else {
                        $scope.AddModel.Branches[0].BranchDetails.EmailList.splice(index, 1);;
                    }

                    break;
                default:
                    if (isAdd) {
                        if ($scope.AddModel.Branches[0].BranchDetails.MobileList.length < 3) {
                            $scope.AddModel.Branches[0].BranchDetails.MobileList.push('');
                        }
                    } else {
                        $scope.AddModel.Branches[0].BranchDetails.MobileList.splice(index, 1);;
                    }

            }
        }

        /////////////////////////////////////////////////////////////////////////////////////////////////

        $scope.addMarker = function (event) {
            $scope.positions = [{ pos: [event.latLng.lat(), event.latLng.lng()], name: "marker 1" }];
            $scope.getAddress(event.latLng.lat(), event.latLng.lng());
        }

        $scope.getLocation = function () {
            if (navigator.geolocation) {
                navigator.geolocation.getCurrentPosition(function (position) {
                    $scope.$evalAsync(function () {
                        $scope.clat = position.coords.latitude;
                        $scope.clng = position.coords.longitude;
                        $scope.positions = [{ pos: [position.coords.latitude, position.coords.longitude], name: "الموقع الحالى" }];
                        $scope.map.setCenter(position);
                        $scope.map.setZoom(10);
                        var geocoder = new google.maps.Geocoder();
                        var latlng = new google.maps.LatLng(position.coords.latitude, position.coords.longitude);

                        geocoder.geocode({ 'latLng': latlng }, function (results, status) {
                            if (status == google.maps.GeocoderStatus.OK) {
                                if (results[1]) {
                                    $scope.AddModel.Branches[0].BranchDetails.Address = results[1].formatted_address;
                                    $scope.AddModel.Branches[0].BranchDetails.Lat = $scope.clat;
                                    $scope.AddModel.Branches[0].BranchDetails.Lng = $scope.clng;
                                } else {
                                    console.log('Location not found');
                                }
                            } else {
                                console.log('Geocoder failed due to: ' + status);
                            }
                        });

                        // initializeCurrent(position.coords.latitude, position.coords.longitude);

                        //$scope.getAddress().then(function (address) {
                        //    $scope.AddModel.Branches[0].BranchDetails.Address = address;
                        //}, function (error) { console.log(error) });
                    })
                });
            }
        }

        $scope.getAddress = function (latitude, longitude) {
            var geocoder = new google.maps.Geocoder();
            var latlng = new google.maps.LatLng(latitude, longitude);
            $scope.map.setCenter(latlng);
            $scope.map.setZoom(10);
            geocoder.geocode({ 'latLng': latlng }, function (results, status) {
                if (status == google.maps.GeocoderStatus.OK) {
                    if (results[1]) {
                        $scope.AddModel.Branches[0].BranchDetails.Address = results[1].formatted_address;
                        $scope.AddModel.Branches[0].BranchDetails.Lat = latitude;
                        $scope.AddModel.Branches[0].BranchDetails.Lng = longitude;
                    } else {
                        console.log('Location not found');
                    }
                } else {
                    console.log('Geocoder failed due to: ' + status);
                }
            });
        }

        function initializeCurrent(latcurr, longcurr) {
            var address;
            var geocoder;
            geocoder = new google.maps.Geocoder();
            var latlng = new google.maps.LatLng(latcurr, longcurr);
            //  dataFactory.saveLatLng(latcurr);
            //  dataFactory.saveLongcurr(longcurr);
            geocoder.geocode(
                { 'latLng': latlng },
                function (results, status) {
                    if (status == google.maps.GeocoderStatus.OK) {
                        if (results[0]) {
                            var add = results[0].formatted_address;
                            console.log("add ", add)
                            var value = add.split(",");

                            var count = value.length;
                            var country = value[count - 1];
                            var state = value[count - 2];
                            console.log("state ", state);
                            var state1 = state.replace(/\d+/g, '');
                            console.log("state1 ", state1);
                            var city = value[count - 3];
                            address = city + " , " + state;
                            return address;
                        }
                        else {
                            alert("address not found");
                        }
                    }
                    else {
                        alert("Geocoder failed due to: " + status);
                    }
                }
            );
            return address;
        };

        $scope.SelectFile = function (e) {
            var allowedExtensions = /(\.jpg|\.jpeg|\.png|\.gif)$/i;
            if (!allowedExtensions.exec(e.target.value)) {
                toaster.error("قم برفع صورة فقط");
                return;
            }
            var reader = new FileReader();
            reader.onload = function (e) {
                $scope.AddModel.Header.LogoUrl = e.target.result;
                console.log(e.target.result);
                $scope.$apply();
            };
            reader.readAsDataURL(e.target.files[0]);
        };

        //Save & Update function
        $scope.Save = function (form, event) {
            $scope.isFormSubmitted = true;
            if (!form.$valid) {
                return false;
            }

            //if ($scope.AddModel.Header.LogoUrl == null) {
            //    toaster.error('شعار المنشأة مطلوب');
            //    return false;
            //}


            $scope.AddModel.Branches[0].BranchDetails.PhoneNumber = $scope.AddModel.Branches[0].BranchDetails.PhoneNumberList?.join();
            $scope.AddModel.Branches[0].BranchDetails.Email = $scope.AddModel.Branches[0].BranchDetails.EmailList.join();
            $scope.AddModel.Branches[0].BranchDetails.Mobile = $scope.AddModel.Branches[0].BranchDetails.MobileList.join();

            var lat = globalService.containsObject('pos', $scope.positions[0]) ? $scope.positions[0]?.pos[0] : null;
            var lng = globalService.containsObject('pos', $scope.positions[0]) ? $scope.positions[0]?.pos[1] : null;
            if (lat != null) {
                $scope.AddModel.Branches[0].BranchDetails.Lat = lat
            }
            if (lng != null) {
                $scope.AddModel.Branches[0].BranchDetails.Lng = lng;
            }

            //Logo & location
            if (!globalService.isNullOrEmpty($scope.AddModel.Header.LogoUrl)) {
                $scope.AddModel.Header.Logo = convertDataURIToBinary($scope.AddModel.Header.LogoUrl);
            }

            // globalService.base64ToArrayBuffer($scope.AddModel.Header.LogoUrl);
            //$scope.Branch.BranchDetails.Lat = $scope.positions[0].pos[0];
            //$scope.Branch.BranchDetails.Lng = $scope.positions[0].pos[1];

            $scope.thereIsData = false;
            $scope.showLoad = true;
            IntegrationSvc.AddEdit($scope.AddModel).then(function (response) {
                if (response.success) {
                    //  $scope.AddModel = $scope.capitalizeObject(response.data);
                    //add slogan and type to image object to be seen in screen
                    // $scope.image = { Url: 'data:' + $scope.AddModel.AttachmentType + ';base64,' + $scope.AddModel.Slogan, Array: convertDataURIToBinary($scope.AddModel.Slogan), AttachmentType: $scope.AddModel.AttachmentType };
                    $scope.thereIsData = true;
                    $scope.showLoad = false;
                    toaster.success(response.message);
                } else {
                    toaster.error(response.message);
                    $scope.thereIsData = true;
                    $scope.showLoad = false;
                }
            });
        }

        $scope.imageUpload = function (event) {
            var files = event.target.files; //FileList object
            for (var i = 0; i < files.length; i++) {
                var file = files[i];
                if (file.type === "application/pdf") {
                    toaster.error("قم برفع صورة فقط");
                    return;
                }
                $scope.image.AttachmentType = file.type;
                var reader = new FileReader();
                reader.onload = $scope.imageIsLoaded;
                reader.readAsDataURL(file);
            }
        }

        $scope.imageIsLoaded = function (e) {
            $scope.$apply(function () {
                var arr = convertDataURIToBinary(e.target.result);
                $scope.image.Url = e.target.result;
                $scope.image.Array = arr;
            });
        }

        function _base64ToArrayBuffer(base64) {
            var binary_string = window.atob(base64);
            var len = binary_string.length;
            var bytes = new Uint8Array(len);
            for (var i = 0; i < len; i++) {
                bytes[i] = binary_string.charCodeAt(i);
            }
            return bytes.buffer;
        }

        function convertDataURIToBinary(dataURI) {
            var BASE64_MARKER = ';base64,';
            var base64Index = dataURI.split(BASE64_MARKER).pop();
            var array = new Uint8Array(_base64ToArrayBuffer(base64Index));
            var arr = [];
            for (var i = 0; i < array.length; i++) {
                arr.push(array[i]);
            }
            return arr;
        }

        $scope.capitalizeObject = function (model) {
            var key, keys = Object.keys(model);
            var n = keys.length;
            var newobj = {};
            while (n--) {
                key = keys[n];
                newobj[key.charAt(0).toUpperCase() + key.substr(1)] = model[key];
            }
            model = newobj;
            return model;
        };

        ///////////////////////////////////////////////////////////


        if (document.getElementById('pac-input') != null) {
            var map = null;
            //NgMap.defaultOptions = {
            //    streetViewControl: false,
            //    mapTypeControl: false,
            //    mapTypeControlOptions: {
            //        mapTypeIds: ['hybrid'] // roadmap , satellite , hybrid , terrain
            //    }
            //};
            NgMap.getMap().then(function (map) {
                map = map;
                //map.data.setStyle(function (feature) {
                //    return ({
                //        fillColor: feature.getProperty('fill') ? feature.getProperty('fill') : 'transparent',
                //        strokeWeight: 0.5,
                //        fillOpacity: feature.getProperty('fillOpacity') ? feature.getProperty('fillOpacity') : 0.5,
                //        zIndex: 1000
                //    });
                //});
                // Create the search box and link it to the UI element.
                var input = document.getElementById('pac-input');
                var searchBox = new google.maps.places.SearchBox(input);
                map.controls[google.maps.ControlPosition.TOP_LEFT].push(input);


                //  Bias the SearchBox results towards current map's viewport.
                map.addListener('bounds_changed', function () {
                    searchBox.setBounds(map.getBounds());
                });
                var markers = [];
                var triggerMapSearch = function () {
                    setTimeout(function () {
                        var input = document.getElementById('pac-input');
                        google.maps.event.trigger(input, 'focus')
                        google.maps.event.trigger(input, 'keydown', {
                            keyCode: 13
                        });
                    }, 100);
                }

                searchBox.addListener('places_changed', function () {
                    var places = searchBox.getPlaces();
                    if (places.length == 0) {
                        return
                    }
                    //Getting latitude and longitude
                    var location = places[0].geometry.location;
                    var lat = location.lat();
                    var lng = location.lng();
                    $scope.positions = [{ pos: [lat, lng], name: "الموقع الحالى" }];
                    $scope.getAddress(lat, lng);
                })

                $rootScope.$on("test", triggerMapSearch);
                $timeout(function () {
                    google.maps.event.trigger(map, 'resize');
                    //map.setCenter(myLatLng);
                })
            });

        }


        ///////////////////////////////
        //PageLoad Functions
        GetData();

    }]);
;
