"use strict";
app.controller('NominationCandidateAuthController', ['$rootScope', '$scope', 'toaster', 'blockUI', 'ngProgress', '$location', 'globalService','$timeout', 'vcRecaptchaService', 'inputs', 'NominationCandidateSvc',
    function ($rootScope, $scope, toaster, blockUI, ngProgress, $location, globalService, $timeout, vcRecaptchaService, inputs, NominationCandidateSvc) {

        // Remove the token from the candidate object
        if($rootScope.candidate && $rootScope.candidate.memberShipToken) $rootScope.candidate.memberShipToken = null;

        $scope.showOtpModal = false;
        $scope.otp = {
            showTimer: false,
            timer: 0,
            isSent: false,
            code: '',
        };
        $scope.header = inputs.header;
        $scope.identityNumber = '';
        $scope.verifyOtpModel = {};
        $scope.captcha = {
            captchaKey: '6LfZPY8UAAAAAPId2zEnccJ4PSbTVXTEey9VxGRo',
            response: null,
            widgetId: null,
        };
        $scope.submit = function (form) {
            let isFormValid = globalService.checkFormValidityAndUpdateStatus(form)
            if(!isFormValid) return;
            $scope.isResend = false;
            $scope.sendOtp();
        }
        $scope.sendOtp = function () {
            $scope.otp.isSent = false;
            $scope.otp.code = '';
            let body = {
                identityNumber: $scope.identityNumber,
                reCaptchaResponse: $scope.captcha.response
            }
            blockUI.start();
            ngProgress.start();
            NominationCandidateSvc.sendOtp(body).then(function(response) {
                if (response.success) {
                    $scope.verifyOtpModel = response.data;
                    $scope.otp.isSent = true;
                    $scope.showOtpModal = true
                    otpTimer();
                } else {
                    $scope.otp.isSent = false;
                    $scope.otp.code = '';
                    $timeout(function () {
                        toaster.clear();
                        if (response.code === 14) {
                            toaster.error('لا يوجد لديك حساب بالبوابة الإلكترونية برجاء تسجيل حساب أولا.');
                        } else {
                            toaster.error(response.message);
                        }
                    }, 0);
                }
            }).catch(function (response) {
                $timeout(function () {
                    toaster.clear(); toaster.error(response.message);
                }, 0);
                if (response.execptionMessage) {
                    $timeout(function () {
                        toaster.clear(); toaster.error(response.execptionMessage);
                    }, 0);
                }
                $scope.otp.isSent = false;
                $scope.otp.code = '';
            }).finally(function () {
                ngProgress.complete();
                blockUI.stop();
                form.captchaKey.$setUntouched();
                $scope.cbExpiration();
            });
        };
        
        $scope.validateOtp = function(){
            $scope.verifyOtpModel.code = $scope.otp.code
            $scope.verifyOtpModel.identityNumber = $scope.identityNumber
            blockUI.start();
            ngProgress.start();
            NominationCandidateSvc.validateOtp($scope.verifyOtpModel)
            .then(function(response){
                if(response.success){
                    toaster.success('تم التحقق بنجاح');
                    $scope.showOtpModal = false;
                    $rootScope.candidate = response.data;
                    $rootScope.candidate.identityNumber = $scope.identityNumber;
                    $rootScope.candidate.memberShipToken = response.data.jwtToken;
                    $location.path(inputs.successRedirectPath);
                }else{
                    toaster.error('الكود غير صحيح');
                }
            }).finally(function () {
                ngProgress.complete();
                blockUI.stop();
            });;
        }
        $scope.$watch('otp.code.length', function (newValue, oldValue) {
            if (($scope.verifyOtpModel.codeLength === 1 && newValue === 4) || ($scope.verifyOtpModel.codeLength === 6 && newValue === 6)) {
                $scope.validateOtp();
            }
        });
        function otpTimer() {
            $scope.otp.showTimer = true;
            $scope.otp.timer = 120;
            var x = setInterval(function () {
                $scope.otp.timer = --$scope.otp.timer;
                if ($scope.otp.timer <= 0) {
                    clearInterval(x);
                    $scope.otp.showTimer = false;
                    $scope.otp.timer = 0;
                }
            }, 1000);
            
        }
        $scope.hideOtpModal = function(){
            $scope.otp.isSent = false;
            $scope.otp.timer = 120;
            $scope.otp.showTimer = false;
            $scope.showOtpModal = false;
        }

       
        $scope.cbExpiration = function () {
            vcRecaptchaService.reload($scope.captcha.widgetId);
            $scope.captcha.response = null;
        };
        $scope.setWidgetId = function (widgetId) {
            $scope.captcha.widgetId = widgetId;
        };
        
        $scope.sendCode = function () {
            // $scope.sendOtp();
            $scope.isResend = true;
        }
    }

]);;
"use strict";
app.controller('NominationCandidateOrganizationsController', ['$rootScope', '$scope', '$routeParams', 'toaster', 'blockUI', 'ngProgress', '$location', 'inputs', 'NominationCandidateSvc',
    function ($rootScope, $scope, $routeParams, toaster, blockUI, ngProgress, $location, inputs, NominationCandidateSvc) {

        $scope.IdentityNumber = $rootScope.candidate.identityNumber;
        $scope.RelatedMembershipsList = [];
        $scope.DelegatedMembershipsList = [];
        $scope.isVoting = inputs.isVoting;
        $scope.header = inputs.header;
        $scope.numberOfVoteByMemberships = $rootScope.numberOfVoteByMemberships;
        // Variables Declarations
        $scope.page = {
            noData: false,
            thereIsData: false,
            showLoad: false,
            itemsPerPage_R: 4,
            itemsPerPage_D: 4,
            currentPage_R: 1,
            currentPage_D: 1,
            totalItems_R: 0,
            totalItems_D: 0
        };
        $scope.searchModel = {
            searchValue: null,
            chamberId: null
        }
        $scope.GetMembershipsList = function () {
            var url = $rootScope;
            ngProgress.start();
            blockUI.start();
            if($rootScope.candidate.memberShipToken && $rootScope.candidate.memberShipToken !== $rootScope.candidate.jwtToken){
                $rootScope.candidate.jwtToken = $rootScope.candidate.memberShipToken;
            }
            NominationCandidateSvc.GetMembershipsList($scope.IdentityNumber, $rootScope.candidate.jwtToken).then(function (response) {
                blockUI.stop();
                ngProgress.complete();
                if (response.success) {
                    if(response.data) {
                        $rootScope.candidate.jwtToken = response.data.jwtToken;
                        if (response.data.finalList.length > 0) {
                            console.log(response);
                            $scope.RelatedMembershipsList = $.grep(response.data.finalList, function (b) {
                                return b.relatedType === 1;
                            });
                            $scope.DelegatedMembershipsList = $.grep(response.data.finalList, function (b) {
                                return b.relatedType === 2;
                            });
    
                            $scope.page.noData = false;
                            $scope.page.thereIsData = true;
                            $scope.page.showLoad = false;
                            ngProgress.complete();
    
                        } else {
                            $scope.page.noData = true;
                            $scope.page.thereIsData = false;
                            $scope.page.showLoad = false;
                            ngProgress.complete();
                            $scope.MembershipsList = [];
                        }
                    }
                } else {
                    $scope.page.noData = true;
                    $scope.page.thereIsData = false;
                    $scope.page.showLoad = false;
                    ngProgress.complete();
                }
            });
        }
        $scope.ValidateCrActivity = function myfunction(membershipDetail) {
            var obj = {
                NominationCommitteeId: $routeParams.CommitteeId,
                MemberId: membershipDetail.memberId,
                CrNumber: membershipDetail.crNumber,
                IdentityNumber: $scope.IdentityNumber,
                SkipCandidacyCheck: inputs.skipCandidacyCheck,
                IgnoreCommittee: ignoreCommittee,
               // IsVotingCheck:
            }
            ngProgress.start();
            blockUI.start();
            NominationCandidateSvc.validateCrActivity(obj, $rootScope.candidate.jwtToken).then(function (response) {
                blockUI.stop();
                ngProgress.complete();
                if (response.success) {
                    if (response.data != undefined && response.data.valid == false) {
                        swal({
                            type: "info",
                            title: 'الانشطة غير مطابقة',
                            text: 'لايمكن اختيار العضوية #' + membershipDetail.estName + ' نظرًا لان الانشطة غير مطابقة لنشاط اللجنة',
                            showCancelButton:true,
                            cancelButtonColor: "#cbc9c9",
                            confirmButtonText: inputs.isVoting ? "العودة للجان"  : 'حسناً',
                            cancelButtonText: inputs.isVoting ? "إختيار عضوية أخرى" : "إلغاء",
                            closeOnConfirm: true
                        }, function (isConfirm) {
                            if (isConfirm) {
                                if(inputs.isVoting){
                                    $location.path("/NominationCommittees/Vote");
                                }
                            }
                        });

                        return false;

                    } else {
                        let successCallBack = function () {
                            $rootScope.memberShip = {
                                estName: membershipDetail.estName,
                                crNumber: membershipDetail.crNumber,
                                memberId: membershipDetail.memberId,
                                mainActivity: membershipDetail.mainActivity,
                                relatedType: membershipDetail.relatedType,
                                subActivities: response.data.subActivities,
                                responsibleName: membershipDetail.responsibleName,
                                membershipCapital: response.data.membershipCapital
                            }
                            $rootScope.candidate.jwtToken = response.data.jwtToken;
                            if(inputs.nextStepUrl == '/Vote'){
                                $location.path($location.url() + inputs.nextStepUrl);
                            } else{
                                $location.path($location.url() + inputs.nextStepUrl);
                            }
                        }
                        if(inputs.isVoting){
                            successCallBack();
                        }else {
                            swal({
                                title: 'الانشطة مطابقة',
                                text: 'هل أنت متأكد من تقديم الترشيح على عضوية  #' + membershipDetail.estName,
                                // type: "warning",
                                showCancelButton: true,
                                confirmButtonColor: "#DD6B55",
                                confirmButtonText: "تأكيد",
                                cancelButtonText: "إلغاء",
                                closeOnConfirm: false
                            },
                                function (isConfirm) {
                                    if (isConfirm) {
                                        successCallBack()
                                        swal.close();
                                    } else {
                                        return false;
                                    }
                            });
                        }
                    }
                } else {
                    toaster.pop('error', response.message);
                }
            });
        }
        $scope.GoBack = function() {
            $location.path("/NominationCommittees");
        }

        $scope.GetMembershipsList();
    }

]);;
"use strict";
app.controller('NominationCandidateSubmitRequestController', ['$rootScope', '$scope', 'toaster', 'blockUI', 'ngProgress', '$timeout', '$routeParams', '$q', '$location', 'globalService', 'NominationCandidateSvc', 'LookupSvc', 'appConst',
    function ($rootScope, $scope, toaster, blockUI, ngProgress, $timeout, $routeParams, $q, $location, globalService, NominationCandidateSvc, lookupSvc, appConst) {
        $scope.RequestModel = {
            candidateName: $rootScope.candidate?.userFullName,
            identityNumber: $rootScope.candidate?.identityNumber,
            memberId: $rootScope.memberShip?.memberId,
            crNumber: $rootScope.memberShip?.crNumber,
            unifiedNumber: $rootScope.memberShip?.unifiedNumber,
            estName: $rootScope.memberShip?.estName,
            mainActivity: $rootScope.memberShip?.mainActivity,
            subActivity: $rootScope.memberShip?.subActivities,
            responsibleName: $rootScope.memberShip?.responsibleName,
            relationId: null,
            specializationId: null,
            nominationCommitteeId: $routeParams.CommitteeId,
            education: null,
            identityExpireDate: null,
            dateOfBirth: null,
            phoneNumber: $rootScope.candidate?.phoneNumber,
            email: $rootScope.candidate?.email,
            candidateInfo: null,
            grievanceText: null,
            nominationAttachments: [],
            CommitteeName: $rootScope.committee?.title,
            membershipCapital: $rootScope.memberShip?.membershipCapital,
            candidateImage: null
        }
        $scope.CommitteeId = $routeParams.CommitteeId
        $scope.IsGrievanceRequest = $rootScope.IsGrievanceRequest;
        $scope.imagesList = [];
        $scope.relations = [];
        $scope.specializations = [];
        $scope.SelectedFileForUpload = [];
        $scope.attachmentsInput = {};
        $scope.save = async function (form) {
            let isFormValid = globalService.checkFormValidityAndUpdateStatus(form)
            if (!isFormValid) {
                return toaster.error('من فضلك أكمل البيانات المطلوبة')
            }
            $scope.RequestModel.membershipWorkerCount =
                ($scope.RequestModel.membershipWorkerCount == null || $scope.RequestModel.membershipWorkerCount == undefined) ? 0 :
                    $scope.RequestModel.membershipWorkerCount;

            if ($scope.RequestModel.membershipWorkerCount == 0) {
                return toaster.error('عدد العاملين يجب ان يكون أكبر من 0 ');
            }
            //check attachments 
            let response = await checkAttachments()
            if (!response.Success && response.Message) {
                toaster.pop('error', response.Message);
                return false;
            }

            let requestBody = angular.copy($scope.RequestModel);
            if (requestBody.subActivity) requestBody.subActivity = JSON.stringify(requestBody.subActivity);
            requestBody.nominationAttachments = angular.copy($scope.imagesList);
            if (!requestBody.dateOfBirth) requestBody.dateOfBirth = null
            blockUI.start();
            ngProgress.start();
            try {
                requestBody.dateOfBirth = requestBody.dateOfBirth != null ? new Date(moment(requestBody.dateOfBirth).format('YYYY-MM-DD')).toISOString().split('T')[0] : null;
                requestBody.identityExpireDate = new Date(moment(requestBody.identityExpireDate).format('YYYY-MM-DD')).toISOString().split('T')[0];
                NominationCandidateSvc.request(requestBody).then(function (res) {
                    ngProgress.complete();
                    blockUI.stop();
                    if (res && res.success) {
                        toaster.pop('success', res?.message || "تم ارسال الطلب بنجاح");
                        $location.path('/NominationCommittees')
                    } else {
                        toaster.pop('error', res.message);
                    }
                })
            } catch (error) {
                ngProgress.complete();
                blockUI.stop();
            }
        }
        $scope.getLookups = function () {
            lookupSvc.Relations()
                .then(function (response) {
                    $scope.relations = response.data;
                });
            lookupSvc.Specializations()
                .then(function (response) {
                    $scope.specializations = response.data;
                });
        }
        $scope.getLookups()

        function checkAttachments() {
            var deferred = $q.defer();
            var FinalResponse = { Success: null, Message: null };
            if ($scope.RequestModel.AddAttachment === true) {
                var allRequiredAttachmentsIsAdded = $scope?.attachmentsInput?.attachmentList?.filter(item => item.IsRequired).every(item => {
                    return $scope.imagesList.find(v => v.attachmentTypeName === item.Name)
                })
                FinalResponse = { Success: allRequiredAttachmentsIsAdded, Message: allRequiredAttachmentsIsAdded ? null : 'فضلا يجب اضافة كل المرفقات الاجبارية' };
            }
            deferred.resolve(FinalResponse);
            return deferred.promise;
        }
        let delegateAttachmentName = 'خطاب تفويض مصدق من الغرفة';
        $scope.addDelegateAttachment = function () {
            if ($scope.attachmentsInput.attachmentList.find(v => v.Name === delegateAttachmentName)) return
            $scope.attachmentsInput.attachmentList.push({ Name: delegateAttachmentName, IsRequired: true, Id: $scope.attachmentsInput.attachmentList.length + 1 })
        }
        $scope.removeDelegateAttachment = function () {
            $scope.attachmentsInput.attachmentList = $scope.attachmentsInput?.attachmentList?.filter(v => v.Name !== delegateAttachmentName)
            $scope.imagesList = $scope.imagesList.filter(v => v.attachmentTypeName !== delegateAttachmentName)
        }
        $scope.attachmentsHandler = function () {
            let attachments = JSON.parse($scope.attachmentList)
            attachments = attachments.map((attachment, index) => new Object({
                Id: index + 1,
                Name: attachment.name,
                IsRequired: attachment.required,
                uploaded: false,
                File: null,
                Hide: false
            }))
            $scope.attachmentsInput = {
                addAttachment: true,
                attachmentExtentions: 'pdf,jpg,jpeg,png',
                attachmentList: attachments || [],
                attachmentSize: 5000,
                attachmentsNumber: attachments.length
            }
            if ($rootScope.memberShip?.relatedType == 2) $scope.RequestModel.relationId = 8; // اذا كان مفوض على العضوية فوضع قيمة افتراضية للعلاقة بالمنشأة مفوض
            if ($scope.RequestModel.relationId == 8) $scope.addDelegateAttachment() // اذا كان مفوض على العضوية فاضافة مرفق اجباري خطاب التفويض
            $scope.RequestModel.AttachmentsNumber = $scope.attachmentsInput.attachmentList.length;
            $scope.RequestModel.AddAttachment = true;
        }


        if ($rootScope.IsGrievanceRequest == false) {
            $scope.attachmentList = $rootScope.committee.attachments;
            $scope.attachmentsHandler();
        }
        $scope.UploadCandidateImage = function (event) {
            const file = event.files[0];
            var fileType = file.type;
            const maxfilesize = 2000000
            const validFileTypes = ['image/jpeg', 'image/png', 'image/gif'];
            angular.forEach(event, function (val, key) {
                var maxfilesize = 2000000
                var maxFileSizeInMbs = Math.ceil(maxfilesize / 1000000 * 100) / 100
                // Check if the file type is valid
                if (validFileTypes.includes(file.type) == false) {
                    toaster.pop('error', 'الصيغة المقبولة JPEG، PNG، أو GIF .');
                    return 0;
                }
                // Check if the file Size is valid
                var maxfilesizemessage = `لايمكن اضافة ملف اكبر من ${maxFileSizeInMbs} ميجا`
                if (file.size > maxfilesize) {
                    toaster.pop('error', maxfilesizemessage);
                    return 0;
                }
                $scope.fileType = file.type;
                if (file) {
                    const reader = new FileReader();
                    reader.onload = function (e) {
                        const arrayBuffer = e.target.result;
                        const byteArray = new Uint8Array(arrayBuffer);
                        const base64String =byteArrayToBase64(byteArray);
                        $scope.imageSrc = 'data:' + $scope.fileType + ';base64,' + base64String;
                        $scope.RequestModel.candidateImage = $scope.imageSrc // For displaying the image
                        $scope.$apply();
                    };
                    reader.readAsArrayBuffer(file); // Read as ArrayBuffer
                }
            });
        }
        function byteArrayToBase64(byteArray) {
            // Create a binary string from the byte array
            let binaryString = '';
            for (let i = 0; i < byteArray.length; i++) {
                binaryString += String.fromCharCode(byteArray[i]);
            }

            // Use btoa to convert the binary string to Base64
            return btoa(binaryString);
        }
        $scope.removeCandidateImage = function () {
            $scope.RequestModel.candidateImage = null;
            $scope.imageSrc = null;

        }
        $scope.selectFile = function (file, attachmentType) {
            PrepareUpload(file, attachmentType).then(function (response) {
                if (!response.Success) {
                    $timeout(function () {
                        toaster.clear(); toaster.error(response.Message);
                    }, 0);
                }
            });
        };
        $scope.removeImg = function (item) {
            var indexx = $scope.imagesList.indexOf(item);
            if (indexx !== -1) {
                $scope.imagesList = $.grep($scope.imagesList, function (v, k) {
                    return indexx !== k;
                });
                var file = $scope.SelectedFileForUpload.find(v => v.name === item.name);
                var index = $scope.SelectedFileForUpload.indexOf(file);
                $scope.SelectedFileForUpload.splice(index, 1);
                angular.forEach($scope.attachmentsInput.attachmentList, function (v, key) {
                    if (v.Id === item.attachmentTypeId)
                        v.uploaded = false;
                });
            }
        };
        $scope.imageIsLoaded = function (e) {
            $scope.$apply(function () {
                return new Uint8Array(e.target.result);
            });
        };
        function PrepareUpload(file, attachmentType) {
            var deferred = $q.defer();
            var FinalResponse = { Success: null, Message: null };
            var extentions = 'pdf,jpg,png,jpeg';
            if ($scope?.attachmentsInput?.attachmentExtentions) extentions = $scope.attachmentsInput.attachmentExtentions
            angular.forEach(file, function (val, key) {
                var ext = val.name.slice(val.name.lastIndexOf('.') + 1).toLowerCase();
                if (extentions.indexOf(ext) <= -1) {
                    angular.forEach(
                        angular.element("input[type='files']"),
                        function (inputElem) {
                            angular.element(inputElem).val(null);
                        });
                    FinalResponse = { Success: false, Message: appConst.fileTypeNotSupported };
                    file = [];
                    deferred.resolve(FinalResponse);
                    return deferred.promise;
                }
            });

            angular.forEach(file, function (val, key) {
                var maxfilesize = 5000000
                if ($scope?.attachmentsInput?.attachmentSize) maxfilesize = $scope.attachmentsInput.attachmentSize * 1000 // to convert kb to bytes
                var maxFileSizeInMbs = Math.ceil(maxfilesize / 1000000 * 100) / 100
                var maxfilesizemessage = `لايمكن اضافة ملف اكبر من ${maxFileSizeInMbs} ميجا`
                if (val.size > maxfilesize) {
                    FinalResponse = { Success: false, Message: maxfilesizemessage };
                    angular.forEach(
                        angular.element("input[type='files']"),
                        function (inputElem) {
                            angular.element(inputElem).val(null);
                        });
                    file = [];
                    deferred.resolve(FinalResponse);
                    return deferred.promise;
                }
            });

            if (window.File && window.FileList && window.FileReader) {
                var files = file;

                angular.forEach(files, function (val, key) {
                    var gg = $scope.SelectedFileForUpload;
                    $scope.SelectedFileForUpload = [];
                    $scope.SelectedFileForUpload.push(val);
                    angular.forEach(gg, function (v, key) {
                        $scope.SelectedFileForUpload.push(v);
                    });
                });

                Array.from(files).forEach(f => {
                    var reader = new FileReader();
                    var image = {
                        Name: f.name,
                        attachmentFileName: f.name,
                        attachmentImage: [],
                        Type: f.type,
                        attachmentType: f.type,
                        attachmentTypeId: attachmentType.Id,
                        attachmentTypeName: attachmentType.Name,
                    };
                    reader.onload = function (e) {
                        image.Src = e.target.result;
                    };
                    reader.readAsDataURL(f);
                    $timeout(function () {
                        reader = new FileReader();
                        reader.onload = function (e) {
                            $scope.$apply(function () {
                                var array = new Uint8Array(e.target.result);
                                var arr = [];
                                for (var i = 0; i < array.length; i++) {
                                    arr.push(array[i]);
                                }

                                if (arr.length > 0) {
                                    image.attachmentImage = arr;
                                    attachmentType.uploaded = true;
                                    $scope.imagesList.push(image);
                                }
                            });
                        };
                        reader.readAsArrayBuffer(f);
                    });
                });

                $('input[type="file"]').val(null);
                FinalResponse = { Success: true, Message: 'sucess load files ' };
                deferred.resolve(FinalResponse);
                return deferred.promise;

            } else {
                FinalResponse = { Success: false, Message: appConst.fileAPINotSupported };
                deferred.resolve(FinalResponse);
                return deferred.promise;
            }
        }
        $scope.GetNominationCandidateById = function () {
            ngProgress.start();
            blockUI.start();
            NominationCandidateSvc.DetailsCandidate($routeParams.RelatedRequestId).then(async function (response) {
                if (response.success) {
                    if (response.data != null) {
                        console.log(response);
                        $scope.RequestModel = {
                            candidateName: response.data?.candidateName,
                            candidateImage: response.data?.candidateImage,
                            identityNumber: response.data?.identityNumber,
                            unifiedNumber: response.data?.unifiedNumber,
                            memberId: response.data?.memberId,
                            crNumber: response.data?.crNumber,
                            estName: response.data?.estName,
                            mainActivity: response.data?.mainActivity,
                            subActivity: response.data.subActivity ? JSON.parse(response.data.subActivity) : [],
                            responsibleName: $rootScope.memberShip?.responsibleName,
                            relationId: response.data?.relationId,
                            specializationId: response.data?.specializationId,
                            nominationCommitteeId: response.data?.nominationCommitteeId,
                            RelatedRequestId: $routeParams.RelatedRequestId,
                            education: response.data?.education,
                            identityExpireDate: new Date(moment(response.data?.identityExpireDate).format('YYYY-MM-DD')),
                            dateOfBirth: new Date(moment(response.data?.dateOfBirth).format('YYYY-MM-DD')),
                            phoneNumber: response.data?.phoneNumber,
                            email: response.data?.email,
                            grievanceText: '',
                            candidateInfo: response.data?.candidateInfo,
                            nominationAttachments: [],
                            attachments: response.data.attachments,
                            CommitteeName: $rootScope.committee?.title,
                            membershipCapital: (response.data.membershipCapital != null
                                && response.data.membershipCapital != undefined
                                && response.data.membershipCapital != '') ? response.data.membershipCapital : $rootScope.memberShip?.membershipCapital,
                            membershipWorkerCount: (response.data.membershipWorkerCount != null
                                && response.data.membershipWorkerCount != undefined
                                && response.data.membershipWorkerCount != '') ? response.data.membershipWorkerCount : $rootScope.memberShip?.membershipWorkerCount

                        }
                        $rootScope.RelatedNominationCommitteeName = response.data.candidateName;
                        $scope.attachmentList = $scope.RequestModel.attachments;
                        $scope.attachmentsHandler();
                        response.data.nominationAttachments.forEach(function (att) {
                            var file = globalService.dataURLtoFile(att.attachmentImage, att.attachmentType, att.attachmentFileName);
                            let attachmentType = $scope.attachmentsInput.attachmentList.find(v => v.Name === att.attachmentTypeName)
                            $scope.selectFile([file], attachmentType);
                        });
                    } else {
                        $scope.MembershipsList = [];
                    }
                }
            }).finally(function () {
                ngProgress.complete();
                blockUI.stop();
            });
        }

        if ($rootScope.IsGrievanceRequest == true) {
            $scope.GetNominationCandidateById()
        }
        $scope.$watch('RequestModel.relationId', function (newValue, oldValue) {
            newValue == 8 ? $scope.addDelegateAttachment() : $scope.removeDelegateAttachment()
        });
    }

]);;
"use strict";
app.controller('NominationCommitteesController', ['localStorage', '$scope', '$location', 'session', 'toaster', 'blockUI', 'ngProgress', '$routeParams', '$sce', 'inputs', 'NominationCandidateSvc', 'NominationCommitteesSvc', '$rootScope',
    function (localStorage, $scope, $location, session, toaster, blockUI, ngProgress, $routeParams, $sce, inputs, NominationCandidateSvc, NominationCommitteesSvc, $rootScope) {

        $scope.header = inputs.header;
        $scope.subHeader = inputs.subHeader;
        $scope.availableToVote = inputs.availableToVote;
        $scope.showRequestsButton = inputs.showRequestsButton;
        $scope.showVoteButton = inputs.showVoteButton;
        $scope.IdentityNumber = inputs.identityNumber;
        $scope.page = {
            itemsPerPage_Committee: 8,
            currentPage_Committee: 1,
            totalItems_Committee: 0,
        };

        $scope.NominationTermsAccepted = sessionStorage.getItem('NominationTermsAccepted') == "true" ? true : false;// session.getPropertyLocalStorage('NominationTermsAccepted', false);
        var termsFile = $location.absUrl().split('#')[0] + 'UserGuide/nominationTerms.pdf';

        if (!$scope.NominationTermsAccepted) {
            // Fetch the PDF
            fetch(termsFile)
                .then(response => response.blob())
                .then(blob => {
                    var url = URL.createObjectURL(blob);
                    var iframe = document.getElementById('pdfIframe');
                    iframe.src = url;
                })
                .catch(error => {
                    console.error('Error fetching PDF:', error);
                });
        }

        ////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
        $scope.NominationCommitteesList = [];
        $scope.SelectedNominationCommitteesList = [];
        $scope.MembershipsList = [];
        $scope.GetActiveNominationCommittees = function () {
            // Remove the token from the candidate object
            //if ($rootScope.candidate && $rootScope.candidate.memberShipToken) $rootScope.candidate.memberShipToken = null;

            ngProgress.start();
            blockUI.start();
            NominationCandidateSvc.getActiveNominationCommittees($scope.availableToVote).then(function (response) {
                if (response.success) {
                    if (response.data.length > 0) {
                        $scope.NominationCommitteesList = response.data;
                    } else {
                        $scope.NominationCommitteesList = [];
                    }
                }
            }).finally(function () {
                blockUI.stop();
                ngProgress.complete();
            });
        }


        $scope.GetMembershipsList = function () {
            var url = $rootScope;
            ngProgress.start();
            blockUI.start();
            if ($rootScope.candidate.memberShipToken && $rootScope.candidate.memberShipToken !== $rootScope.candidate.jwtToken) {
                $rootScope.candidate.jwtToken = $rootScope.candidate.memberShipToken;
            }
            NominationCandidateSvc.GetMembershipsList($scope.IdentityNumber, $rootScope.candidate.jwtToken).then(function (response) {
                blockUI.stop();
                ngProgress.complete();
                if (response.success) {
                    if (response.data) {
                        $rootScope.candidate.jwtToken = response.data.jwtToken;
                        if (response.data.finalList.length > 0) {
                            console.log(response);
                            $scope.MembershipsList = response.data.finalList;
                            $scope.page.noData = false;
                            $scope.page.thereIsData = true;
                            $scope.page.showLoad = false;
                            ngProgress.complete();

                        } else {
                            $scope.page.noData = true;
                            $scope.page.thereIsData = false;
                            $scope.page.showLoad = false;
                            ngProgress.complete();
                            $scope.MembershipsList = [];
                        }
                    }
                } else {
                    $scope.page.noData = true;
                    $scope.page.thereIsData = false;
                    $scope.page.showLoad = false;
                    ngProgress.complete();
                }
            });
        }


        ////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
        $scope.GetMembershipsList();
        $scope.GetActiveNominationCommittees();
        ////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

        $scope.SelectedMemberships = [];

        $scope.SelectMembership = function (membershipDetail, ignoreCommittee) {
            if (!membershipDetail.isChecked) {
                let index = $scope.SelectedNominationCommitteesList.findIndex(record => record.memberDetails.memberId === membershipDetail.memberId);
                $scope.SelectedNominationCommitteesList.splice(index, 1);
                $rootScope.memberShip = {};
            } else {
                if ($scope.NominationCommitteesList.length < 1) {
                    toaster.clear();
                    membershipDetail.isChecked = false;
                    toaster.pop('error', $scope.availableToVote ? 'لا توجد لجان التصويت' : 'لا توجد لجان للترشح');
                } else {
                    $scope.ValidateCrActivity(membershipDetail, ignoreCommittee);
                }
            }
        }
        $scope.confirmCommittee = function (committeeId, membershipDetail, committeeTitle) {
            var obj = {
                NominationCommitteeId: committeeId,
                MemberId: membershipDetail.memberId,
                CrNumber: membershipDetail.crNumber,
                unifiedNumber: membershipDetail.unifiedNumber,
                IdentityNumber: $scope.IdentityNumber,
                SkipCandidacyCheck: $scope.availableToVote ? true : false,
                IgnoreCommittee: false,
                UnifiedNumber: membershipDetail.unifiedNumber,
                IsVotingCheck: $scope.availableToVote
            }
            ngProgress.start();
            blockUI.start();
            toaster.clear();
            NominationCandidateSvc.validateCrActivity(obj, $rootScope.candidate.jwtToken).then(function (response) {
                blockUI.stop();
                ngProgress.complete();
                if (response.success) {
                    // swal.close();
                    $rootScope.candidate.jwtToken = response.data.jwtToken;
                    let successCallBack = function () {
                        $rootScope.memberShip = {
                            estName: membershipDetail.estName,
                            crNumber: membershipDetail.crNumber,
                            memberId: membershipDetail.memberId,
                            unifiedNumber: membershipDetail.unifiedNumber,
                            mainActivity: membershipDetail.mainActivity,
                            relatedType: membershipDetail.relatedType,
                            subActivities: response.data.subActivities,
                            responsibleName: membershipDetail.responsibleName,
                            membershipCapital: response.data.membershipCapital
                        }
                        $rootScope.candidate.jwtToken = response.data.jwtToken;
                        $rootScope.candidate.voteJwtToken = response.data.jwtToken;
                        if (inputs.nextStepUrl == '/Vote') {
                            $location.path($location.url() + inputs.nextStepUrl);
                        } else {
                            $location.path($location.url() + inputs.nextStepUrl);
                        }
                    }
                    if (inputs.isVoting) {
                        successCallBack();
                    } else {
                        //swal({
                        //    title: 'الانشطة مطابقة',
                        //    text: 'هل أنت متأكد من تقديم الترشيح على عضوية  #' + membershipDetail.estName,
                        //    // type: "warning",
                        //    showCancelButton: true,
                        //    confirmButtonColor: "#DD6B55",
                        //    confirmButtonText: "تأكيد",
                        //    cancelButtonText: "إلغاء",
                        //    closeOnConfirm: false
                        //},
                        //    function (isConfirm) {
                        //        if (isConfirm) {
                        //            successCallBack()
                        //            swal.close();
                        //        } else {
                        //            return false;
                        //        }
                        //    });
                    }
                    $location.path("/NominationCommittees/Details/" + committeeId);

                    //if (inputs.isVoting) {
                    //    $location.path("/NominationCommittees/" + committeeId);
                    //}
                }
                else {
                    toaster.clear();
                    toaster.pop('error', response.message);
                }
            });
            //swal({
            //    type: "info",
            //    title: '',
            //    text: 'هل أنت متأكد من تحديد (' + committeeTitle + ') من خلال عضوية (' + membershipDetail.estName + ')',
            //    showCancelButton: true,
            //    cancelButtonColor: "#cbc9c9",
            //    confirmButtonText: inputs.isVoting ? "العودة للجان" : 'تأكيد',
            //    cancelButtonText: inputs.isVoting ? "إختيار عضوية أخرى" : "إلغاء",
            //    closeOnConfirm: true
            //}, function (isConfirm) {
            //    if (isConfirm) {


            //    }
            //});

        }
        $scope.ValidateCrActivity = function myfunction(membershipDetail, ignoreCommittee) {
            var obj = {
                NominationCommitteeId: $routeParams.CommitteeId,
                MemberId: membershipDetail.memberId,
                CrNumber: membershipDetail.crNumber,
                unifiedNumber: membershipDetail.unifiedNumber,
                IdentityNumber: $scope.IdentityNumber,
                SkipCandidacyCheck: inputs.skipCandidacyCheck,
                IgnoreCommittee: ignoreCommittee,
                UnifiedNumber:  membershipDetail.unifiedNumber,
                IsVotingCheck: $scope.availableToVote
            }
            ngProgress.start();
            blockUI.start();
            toaster.clear();

            
            if (obj.UnifiedNumber == null || obj.UnifiedNumber == "0" || obj.UnifiedNumber == "") {
                toaster.clear();
                toaster.pop('error', "الرقم الموحد مطلوب ، تواصل مع الغرفة لتحديث بياناتك .");
                blockUI.stop();
                ngProgress.complete();
                return false;
            }

            NominationCandidateSvc.validateCrActivity(obj, $rootScope.candidate.jwtToken).then(function (response) {
                blockUI.stop();
                ngProgress.complete();
                if (response.success) {
                    if (response.data.valid && ignoreCommittee) {
                        var filteredCommittees = $.grep($scope.NominationCommitteesList, function (b) {
                            var committeeActivities = JSON.parse(b.activities);
                            var exist = committeeActivities.some(function (a) {
                                return response.data.subActivities.some(function (b) {
                                    return Number(a.code) === Number(b.id);
                                });
                            });
                            if (exist) {
                                return b;
                            }
                        });

                        membershipDetail.subActivities = response.data.subActivities;
                        membershipDetail.membershipCapital = response.data.membershipCapital;
                        $rootScope.candidate.jwtToken = response.data.jwtToken;
                        $rootScope.memberShip = membershipDetail;
                        $scope.SelectedNominationCommitteesList.push({
                            memberDetails: membershipDetail,
                            Committees: filteredCommittees
                        });
                        return;
                    }
                    if (response.data != undefined && response.data.valid == false) {
                        swal({
                            type: "info",
                            title: 'الانشطة غير مطابقة',
                            text: 'لايمكن اختيار العضوية #' + membershipDetail.estName + ' نظرًا لان الانشطة غير مطابقة لنشاط اللجنة',
                            showCancelButton: true,
                            cancelButtonColor: "#cbc9c9",
                            confirmButtonText: inputs.isVoting ? "العودة للجان" : 'حسناً',
                            cancelButtonText: inputs.isVoting ? "إختيار عضوية أخرى" : "إلغاء",
                            closeOnConfirm: true
                        }, function (isConfirm) {
                            if (isConfirm) {
                                if (inputs.isVoting) {
                                    $location.path("/NominationCommittees/Vote");
                                }
                            }
                        });

                        return false;

                    } else {
                        let successCallBack = function () {
                            $rootScope.memberShip = {
                                estName: membershipDetail.estName,
                                crNumber: membershipDetail.crNumber,
                                memberId: membershipDetail.memberId,
                                unifiedNumber: membershipDetail.unifiedNumber,
                                mainActivity: membershipDetail.mainActivity,
                                relatedType: membershipDetail.relatedType,
                                subActivities: response.data.subActivities,
                                responsibleName: membershipDetail.responsibleName,
                                membershipCapital: response.data.membershipCapital
                            }
                            $rootScope.candidate.jwtToken = response.data.jwtToken;
                            if (inputs.nextStepUrl == '/Vote') {
                                $location.path($location.url() + inputs.nextStepUrl);
                            } else {
                                $location.path($location.url() + inputs.nextStepUrl);
                            }
                        }
                        if (inputs.isVoting) {
                            successCallBack();
                        } else {
                            swal({
                                title: 'الانشطة مطابقة',
                                text: 'هل أنت متأكد من تقديم الترشيح على عضوية  #' + membershipDetail.estName,
                                // type: "warning",
                                showCancelButton: true,
                                confirmButtonColor: "#DD6B55",
                                confirmButtonText: "تأكيد",
                                cancelButtonText: "إلغاء",
                                closeOnConfirm: false
                            },
                                function (isConfirm) {
                                    if (isConfirm) {
                                        successCallBack()
                                        swal.close();
                                    } else {
                                        return false;
                                    }
                                });
                        }
                    }
                } else {
                    membershipDetail.isChecked = false;
                    toaster.clear();
                    toaster.pop('error', response.message);
                }
            });
        }

        $scope.sanitizeMe = function (text) {
            return $sce.trustAsHtml(text);
        };
        $scope.getSlogans = function () {
            NominationCommitteesSvc.Slogans().then(function (response) {
                $scope.slogans = response.default.reduce(function (acc, item) {
                    acc[item.id] = item.icon;
                    return acc;
                }, {});
            });
        }
        $scope.getSlogans();

        $scope.trustSrc = function (src) {
            return $sce.trustAsResourceUrl(src);
        }

        $scope.acceptTerms = function (isAccepted) {
            if (isAccepted) {
                sessionStorage.setItem('NominationTermsAccepted', true);
                $scope.NominationTermsAccepted = true;
                return true;
            } else {
                toaster.error({ title: "يرجي الموافقة على لائحة اللجان الوطنية والقطاعية للإستمرار" });
                return false;
            }
        }
    }
]);;
"use strict";
app.controller('NominationCommitteeController', ['$rootScope', '$location', '$routeParams', '$scope', 'toaster', '$sce', 'blockUI', 'ngProgress', '$timeout', 'NominationCommitteesSvc',
    function ($rootScope, $location, $routeParams, $scope, toaster, $sce, blockUI, ngProgress, $timeout, NominationCommitteesSvc) {

        $scope.CommitteeDetail = {};
        $scope.IsShowModal = false;
        $scope.IsNominationDateExpired = false;
        $scope.WinnersList = [];
        $scope.winnersPage = {
            itemsPerPage: 9,
            currentPage: 1,
            totalItems: 0,
        };
        $scope.ViewNominationCommitteeById = function () {
            ngProgress.start();
            blockUI.start();
            $scope.CommitteeId = $routeParams.CommitteeId;
            NominationCommitteesSvc.viewNominationCommitteeById($scope.CommitteeId).then(function (response) {
                if (response.success && response.data != undefined) {
                    console.log(response);
                    $scope.CommitteeDetail = response.data;
                    $scope.CommitteeDetail.activities = JSON.parse(response.data.activities);
                    // Load initial activities
                    $scope.loadMoreActivities();

                    $rootScope.numberOfVoteByMemberships = $scope.CommitteeDetail.numberOfVoteByMemberships;
                    if ($scope.CommitteeDetail?.winAnnounced == true) {
                        $scope.GetNominationCommitteeWinners();
                    }
                    $scope.getSlogan();

                } else {
                    $scope.CommitteeDetail = {};
                }
            }).finally(function () {
                blockUI.stop();
                ngProgress.complete();
            });
        }
        $scope.saveCommitteDetails = function () {
            $rootScope.committee = $scope.CommitteeDetail;
        }
        $scope.GoToNominate = function () {

            var obj = {
                NominationCommitteeId: $routeParams.CommitteeId,
                MemberId: $rootScope.memberShip.memberId,
                CrNumber: $rootScope.memberShip.crNumber,
                IdentityNumber: $rootScope.candidate.identityNumber
   
            }
            NominationCommitteesSvc.CheckNominationCandidate(obj).then(function (response) {
                if (response.success) {
                    console.log(response);
                    swal({
                        title: 'الانشطة مطابقة',
                        text: 'هل أنت متأكد من تقديم الترشيح على عضوية  #' + $rootScope.memberShip?.estName,
                        // type: "warning",
                        showCancelButton: true,
                        confirmButtonColor: "#DD6B55",
                        confirmButtonText: "تأكيد",
                        cancelButtonText: "إلغاء",
                        closeOnConfirm: false
                    },
                        function (isConfirm) {
                            if (isConfirm) {
                                swal.close();
                                var nominationFromDate = $scope.convertDateToMoment($scope.CommitteeDetail.nominationFromDate);
                                var nominationToDate = $scope.convertDateToMoment($scope.CommitteeDetail.nominationToDate);
                                var currentDate = $scope.convertDateToMoment();
                                // اثناء فترة الترشح 
                                if ($scope.checkForNominationDate(currentDate, nominationFromDate, nominationToDate)) {
                                    // التحويل الى طلب الترشح
                                    $scope.saveCommitteDetails();
                                    //$location.path("/NominationCommittees/" + $routeParams.CommitteeId + "/Candidate");
                                    $location.path("/NominationCommittees/" + $routeParams.CommitteeId + "/Candidate/Organizations/Submit");
                                }
                                // فترة الترشح لم تبدا بعد
                                else if (moment(currentDate).isBefore(nominationFromDate)) {
                                    $scope.IsShowModal = true;
                                    $scope.IsNominationDateExpired = false;
                                }// تم انتهاء فترة الترشح
                                else {
                                    $scope.IsShowModal = true;
                                    $scope.IsNominationDateExpired = true;
                                }

                            } else {
                                swal.close();
                                return false;
                            }
                        });

                } else {
                    toaster.error(response.message);
                }
            }).finally(function () {
            });
        }
        $scope.goToVote = function () {
            $scope.saveCommitteDetails();
            $location.path('/NominationCommittees/' + $scope.CommitteeId + '/Voting/Memberships/Vote'); 
            //$location.path("/NominationCommittees/" + $routeParams.CommitteeId + "/Voting/Auth");
        }
        $scope.GoBack = function myfunction() {
            $rootScope.memberShip = {};
            $location.path("/NominationCommittees");
        }
        $scope.ViewNominationCommitteeById();
        $scope.sanitizeMe = function (text) {
            return $sce.trustAsHtml(text);
        };
        $scope.checkForNominationDate = function (currentDate, nominationFromDate, nominationToDate) {
            let d1 = moment(currentDate).isSame(nominationFromDate);
            let d2 = moment(currentDate).isAfter(nominationFromDate);
            let d3 = moment(currentDate).isBefore(nominationToDate);
            let d4 = moment(currentDate).isSame(nominationToDate);
            if ((d1 || d2) && (d3 || d4)) {
                return true;
            }
            return false;
        }
        $scope.convertDateToMoment = function (date) {
            return moment(date ? new Date(date) : new Date).format('YYYY-MM-DD');
        }
        $scope.GetNominationCommitteeWinners = function () {
            $scope.CommitteeId = $routeParams.CommitteeId;
            NominationCommitteesSvc.GetNominationCommitteeWinners($scope.CommitteeId, $scope.winnersPage.currentPage, $scope.winnersPage.itemsPerPage).then(function (response) {
                if (response.success && response.data != undefined) {
                    console.log(response);
                    $scope.WinnersList = [...$scope.WinnersList, ...response.data];
                    $scope.winnersPage.totalItems = response.data[0].rowsCounts;

                } else {
                    $scope.WinnersList = []
                }
            }).finally(function () {
            });
        }
        $scope.showMore = function (pageIndex) {
            $scope.winnersPage.currentPage = pageIndex;
            $scope.winnersPage.itemsPerPage = 9;
            $scope.GetNominationCommitteeWinners();
        };
        
  
        $scope.getShortName = function (fullName) {
            const strings = fullName.split(' ')
            return strings[0].charAt(0) + ' ' + strings[1].charAt(0);
        }
        $scope.getSlogan = function () {
            NominationCommitteesSvc.Slogans().then(function (response) {
                $scope.slogan = response?.default?.filter(function (slogan) {
                    return slogan.id == $scope.CommitteeDetail.slogan;
                })[0]?.icon;
            });
        }
   
        $scope.paginatedActivities = [];     // Activities to display
        $scope.itemsPerScroll = 10;     // Number of Activities to load per scroll
        $scope.currentIndex = 0;        // Index to keep track of loaded Activities
        $scope.loadingActivities = false;         // Loading indicator
        $scope.allActivitiesLoaded = false;   // Flag to indicate all data is loaded
        // Function to load more Activities
        $scope.loadMoreActivities = function () {
            if ($scope.loadingActivities || $scope.allActivitiesLoaded) return; // Avoid redundant calls
            $scope.loadingActivities = true;

            // Calculate the next set of items to load
            const nextItems = $scope.CommitteeDetail.activities.slice($scope.currentIndex, $scope.currentIndex + $scope.itemsPerScroll);

            if (nextItems.length > 0) {
                $scope.paginatedActivities = $scope.paginatedActivities.concat(nextItems);
                $scope.currentIndex += $scope.itemsPerScroll; // Move the index forward
            } else {
                $scope.allActivitiesLoaded = true; // No more items to load
            }

            $scope.loadingActivities = false;
        };

   
   
    }

]);;
"use strict";
app.controller("NominationCandidateCandidacyApplicationController", [
    "$rootScope",
    "$scope",
    "toaster",
    "blockUI",
    "$location",
    "NominationCandidateSvc",
    "renderFile",
    "$sce",
    function ($rootScope, $scope, toaster, blockUI, $location, NominationCandidateSvc, renderFile, $sce) {
        $scope.identityNumber = $rootScope.candidate.identityNumber;
        $scope.userFullName = $rootScope.candidate.userFullName;
        // $scope.identityNumber = "2410238360";
        $scope.model = {
            PageIndex: 1,
            PageSize: 5,
            IdentityNumber: $scope.identityNumber 
        };
        $scope.nominationStatus = {
            Accepted: 1,
            Rejected: 2,
            Pending: 3,
            AcceptedAfterGrievance: 4,
            Winner: 5,
        };
        $scope.applications = [];
        $scope.totalItems = 0;
        $scope.loading = true;
        $scope.thereIsData = true;
        $scope.showRejectModal = false;
        $scope.rejectReason = "";
        $scope.RelatedRequestId = null;
        $scope.isGrievanceAllowed = false;
        $scope.showAttachment = false;

        $scope.getCandidacyApplications = function () {
            blockUI.start();
            $scope.loading = true;
            try {
                NominationCandidateSvc.requests($scope.model).then(function (response) {
                    $scope.loading = false;
                    if (response && response.success) {
                        if (response.data.length === 0) {
                            $scope.thereIsData = false;
                        } else {
                            $scope.thereIsData = true;
                            $scope.applications = [...$scope.applications, ...response.data];
                            $scope.totalItems = response.data[0].rowsCounts;
                            $scope.loading = false;
                            blockUI.stop();
                        }
                    }
                });
            } catch (error) {
                blockUI.stop();
                toaster.error({ title: "حدث خطأ ما", body: "يرجى المحاولة مرة أخرى" });
                $scope.loading = false;
            }
            blockUI.stop();
        };

        $scope.showMore = function (pageIndex) {
            $scope.model.PageIndex = pageIndex;
            $scope.getCandidacyApplications();
        };

        $scope.getCandidacyApplications();

        $scope.application = {};
        $scope.showRejectReason = function (application) {
            if (application.nominationStatusId !== $scope.nominationStatus.Rejected) return;

            $scope.showRejectModal = true;
            $scope.rejectReason = application.rejectreason;
            $scope.RelatedRequestId = application.id;
            $scope.isGrievance = application.relatedRequestId ? true : false;
            $scope.isGrievanceAllowed = application.isGrievanceAllowed;
            $rootScope.RelatedNominationCommitteeName = application.nominationCommittee;
            $scope.application = application;
        };
        $scope.AddGrievanceRequest = function (application) {
            $rootScope.RelatedNominationCommitteeName = application.nominationCommittee;
            $location.path("/NominationCandidate/CandidacyApplication/List/" + application.id);
        }
        $scope.$destroy = function () {
            $rootScope.RouteTo = null;
        };

        $scope.refresh = function () {
            $scope.model.PageIndex = 1;
            $scope.applications = [];
            $scope.getCandidacyApplications();
        }
        $scope.openAttachment = function(application) {
            blockUI.start();
            NominationCandidateSvc.DetailsCandidate(application.id).then(function (response) {
                blockUI.stop();
                if (response && response.success) {
                    $scope.attachments = response.data.nominationAttachments;
                    $scope.showAttachmentModal = true;
                }
            });
        }

        $scope.AttachDownload = function (x) {
            $scope.FileExt = x.attachmentFileName.substr(x.attachmentFileName.length - 3);
            renderFile.generateFileType($scope.FileExt);
            renderFile.init({ data: x.attachmentImage, name: x.attachmentFileName, type: $scope.FileExt });
        };

        $scope.selectAttachment = function(attachment) {
            $scope.selectedAttachment = attachment;
            if(attachment.attachmentFileName.includes('.pdf') || attachment.attachmentFileName.includes('.PDF'))
                {
                     $scope.pdfDataUrl = $sce.trustAsResourceUrl('data:' + attachment.attachmentType + ';base64,' + attachment.attachmentImage);
                }
            $scope.showAttachment = true;
        }
        $scope.hideAttachment = function() {
            $scope.showAttachment = false;
            $scope.selectAttachment = null;
        }
    },
]);
