"use strict";
app.controller("NominationVoteController", [
  "$rootScope",
  "$location",
  "$routeParams",
  "$scope",
  "toaster",
  "blockUI",
  "ngProgress",
  "NominationVoteSvc",
  "NominationCandidateSvc",
  "SweetAlert",
  function (
    $rootScope,
    $location,
    $routeParams,
    $scope,
    toaster,
    blockUi,
    ngProgress,
    NominationVoteSvc,
    NominationCandidateSvc,
    SweetAlert
  ) {
    $scope.committeeId = $routeParams.CommitteeId;
    $scope.memberShip = $rootScope.memberShip;
    $scope.candidate = $rootScope.candidate;
    $scope.committeeName = $rootScope.committee.title;
    // $scope.candidate = {
    //   $id: "2",
    //   email: "mhelaly@worldofss.com",
    //   identityNumber: "2410238360",
    //   phoneNumber: "0567472422",
    //   userFullName: "محمود هلالى",
    // };
    $scope.chamber = $rootScope.chamberSettings;
    $scope.model = {
      PageIndex: 1,
      PageSize: 1000,
      StartRowNumber: 1,
      IdentityNumber: $scope.candidate.identityNumber,
      MemberId: $scope.memberShip.memberId,
      NominationCommitteeId: $scope.committeeId,
      Pagination: 20 
    };

    $scope.candidates = [];
    $scope.paginatedCandidates = [];
    $scope.selectedItems = {};
    $scope.selectionLimit = $rootScope.committee.numberOfVoteForCandidates;
    $scope.remainingVotes = 0;
    $scope.selectedBefore = 0;

    $scope.candidateInfo = "";
    $scope.showInfoModal = false;
    $scope.disableSubmit = true;
    $scope.toggleSelection = function (id) {
      $scope.disableSubmit = true;
      if ($scope.selectedItems[id]) {
        if (Object.keys($scope.selectedItems).filter((key) => $scope.selectedItems[key]).length > $scope.remainingVotes) {
          $scope.selectedItems[id] = false;
          SweetAlert.swal("لا يمكنك التصويت على أكثر من " + $scope.selectionLimit );
        }
      }
      if(Object.keys($scope.selectedItems).filter((key) => $scope.selectedItems[key]).length > 0) {
        $scope.disableSubmit = false;
      }
    };

    $scope.getNominationCandidatesForVote = function () {
      blockUi.start();
      ngProgress.start();
      $scope.thereIsData = false;
      $scope.loading = true;
      $scope.candidates = [];
      try {
          NominationCandidateSvc.ForVoting($scope.model, $rootScope.candidate.voteJwtToken ?? $rootScope.candidate.jwtToken).then(function (response) {
          ngProgress.complete();
          if (response && response.success) {
            if(response.data) {
              $rootScope.candidate.jwtToken = response.data.jwtToken;
              if (response.data.data.length === 0) {
                $scope.thereIsData = false;
                $scope.candidates = [];
              } else {
                $scope.thereIsData = true;
                $scope.totalItems = response.data.data[0].rowsCounts;
                $scope.candidates = response.data.data.map((c, i) => ({...c, index: i}));
                $scope.selectedBefore = $scope.candidates.filter((c) => c.isVoted).length;
                $scope.remainingVotes = $scope.selectionLimit - $scope.selectedBefore;
                $scope.getPaginationRange();
              }
            }
          }
          $scope.loading = false;
          blockUi.stop();
        });
      } catch (error) {
        console.log(error);
        blockUi.stop();
        ngProgress.complete();
        toaster.error({ title: "حدث خطأ ما", body: "يرجى المحاولة مرة أخرى" });
      }
    };
    $scope.showInfo = function (candidateInfo) {
      $scope.candidateInfo = candidateInfo;
      $scope.showInfoModal = true;
    };

    $scope.pageChanged = function (newPage) {
      $scope.model.PageIndex = newPage;
      $scope.getPaginationRange();
    };

    $scope.getPaginationRange = function () {
      var startIndex = ($scope.model.PageIndex - 1) * $scope.model.Pagination;
      var endIndex = startIndex + $scope.model.Pagination;
      $scope.paginatedCandidates = $scope.candidates.slice(startIndex, endIndex);
    };

    $scope.addVotes = function () {
      if($scope.disableSubmit) return;
      var nominationVotes = {
        NominationCommitteeId: $scope.committeeId,
        NominationCandidateIds: Object.keys($scope.selectedItems).filter((key) => $scope.selectedItems[key]),
        VoterIdentityNumber: $scope.candidate.identityNumber,
        VoterName: $scope.candidate.userFullName,
        VoterMemberId: $scope.memberShip.memberId,
        VoterCrNumber: $scope.memberShip.crNumber,
      };
      if (nominationVotes.NominationCandidateIds.length === 0) {
        SweetAlert.swal({
          title: "يرجى اختيار مرشح واحد على الأقل",
          text: "",
          type: "warning",
        });
        return;
      }

      SweetAlert.swal(
        {
          title: "هل أنت متأكد؟",
          text: `هل أنت متأكد من التصويت ${nominationVotes.NominationCandidateIds.length > 1 ? "لمرشحين -" :"لمرشح - " } ${$scope.committeeName} `,
          type: "warning",
          showCancelButton: true,
          confirmButtonColor: "#DD6B55",
          confirmButtonText: "نعم انا متاكد",
          cancelButtonText: "الغاء",
          closeOnConfirm: true,
          closeOnCancel: true,
        },
        function (isConfirmed) {
          if (isConfirmed) {
            try {
              blockUi.start();
              ngProgress.start();
              NominationCandidateSvc.AddVotes(nominationVotes, $rootScope.candidate.jwtToken).then(
                function (response) {
                  blockUi.stop();
                  ngProgress.complete();
                  if (response && response.success) {
                    SweetAlert.swal({
                      title: `تم التصويت لمرشحين لجنة ${$scope.committeeName} بنجاح`,
                      text: "",
                      type: "success",
                    });
                    $location.path("/NominationCommittees/Vote");
                  } else {
                    toaster.error({ title: "حدث خطأ ما", body: response.message });
                  }
                }
              );
            } catch (error) {
              console.log(error);
              blockUi.stop();
              ngProgress.complete();
              toaster.error({ title: "حدث خطأ ما", body: "يرجى المحاولة مرة أخرى" });
            }
          }
        }
      );
    };

    $scope.getNominationCandidatesForVote();
  },
]);
;
